	db ((6) << 4) | (5)
	db ((4) << 4) | (4)
	db ((3) << 4) | (3)
	db ((2) << 4) | (2)
	db ((1) << 4) | (1)

.wave1
	db ((0) << 4) | (2)
	db ((4) << 4) | (6)
	db ((8) << 4) | (10)
	db ((12) << 4) | (14)
	db ((14) << 4) | (15)
	db ((15) << 4) | (15)
	db ((15) << 4) | (14)
	db ((14) << 4) | (14)
	db ((13) << 4) | (13)
	db ((12) << 4) | (11)
	db ((10) << 4) | (9)
	db ((8) << 4) | (7)
	db ((6) << 4) | (5)
	db ((4) << 4) | (3)
	db ((2) << 4) | (2)
	db ((1) << 4) | (1)

.wave2
	db ((1) << 4) | (3)
	db ((6) << 4) | (9)
	db ((11) << 4) | (13)
	db ((14) << 4) | (14)
	db ((14) << 4) | (14)
	db ((15) << 4) | (15)
	db ((15) << 4) | (15)
	db ((14) << 4) | (13)
	db ((13) << 4) | (14)
	db ((15) << 4) | (15)
	db ((15) << 4) | (15)
	db ((14) << 4) | (14)
	db ((14) << 4) | (14)
	db ((13) << 4) | (11)
	db ((9) << 4) | (6)
	db ((3) << 4) | (1)

.wave3
	db ((0) << 4) | (2)
	db ((4) << 4) | (6)
	db ((8) << 4) | (10)
