SECTION "Audio Engine 1", ROMX

;@ path: audio/play_battle_music
;@ def PlayBattleMusic()
;@ Stop all sound, wait a frame, then start the battle theme: gym leader (also for Lance), final battle
;@ against the rival, trainer or wild battle. Also switches the low-health alarm off.
;@ test: skip waits for the next frame
PlayBattleMusic::
;> wAudioFadeOutControl = 0
	xor a
	ld [wAudioFadeOutControl], a
;> wLowHealthAlarm = 0
	ld [wLowHealthAlarm], a
;> wNewSoundID = SFX_STOP_ALL_MUSIC
	dec a ; SFX_STOP_ALL_MUSIC
	ld [wNewSoundID], a
;> PlaySound(SFX_STOP_ALL_MUSIC)
	call PlaySound
;> DelayFrame()
	call DelayFrame
	ld c, BANK(Music_GymLeaderBattle)
;> if wGymLeaderNo or wCurOpponent == OPP_LANCE:
	ld a, [wGymLeaderNo]
	and a
	jr z, .notGymLeaderBattle
;>     song = Music_GymLeaderBattle
	ld a, MUSIC_GYM_LEADER_BATTLE
	jr .playSong
.notGymLeaderBattle
;> elif wCurOpponent < OPP_ID_OFFSET:
;>     song = Music_WildBattle
	ld a, [wCurOpponent]
	cp OPP_ID_OFFSET
	jr c, .wildBattle
;> elif wCurOpponent == OPP_RIVAL3:
;>     song = Music_FinalBattle
	cp OPP_RIVAL3
	jr z, .finalBattle
	cp OPP_LANCE
	jr nz, .normalTrainerBattle
	ld a, MUSIC_GYM_LEADER_BATTLE ; lance also plays gym leader theme
	jr .playSong
.normalTrainerBattle
;> else:
;>     song = Music_TrainerBattle
	ld a, MUSIC_TRAINER_BATTLE
	jr .playSong
.finalBattle
	ld a, MUSIC_FINAL_BATTLE
	jr .playSong
.wildBattle
	ld a, MUSIC_WILD_BATTLE
.playSong
;> PlayMusic((song - SFX_Headers_1) // 3, BANK(Music_GymLeaderBattle))   # all in the same audio bank
	jp PlayMusic
; The first of three duplicated sound engines.

;@ path: audio/engine_1
;@ def Audio1_UpdateMusic()
;@ The sound engine's frame, for the sounds in this audio bank: every channel that is playing runs one
;@ frame. While the music is paused (wMuteAudioAndPauseMusic) the music channels are skipped, and the first
;@ time round all output is switched off; effects keep playing.
;@ test: [mem.__setitem__(wChannelFlags1 + i, mem[wChannelFlags1 + i] & ~(1 << BIT_PITCH_SLIDE_ON)) for i in range(8)]
Audio1_UpdateMusic::
;> for channel in range(CHAN1, CHAN8 + 1):
	ld c, CHAN1
.loop
;>     if not wChannelSoundIDs[channel]:
;>         continue
	ld b, 0
	ld hl, wChannelSoundIDs
	add hl, bc
	ld a, [hl]
	and a
	jr z, .nextChannel
;>     if channel < CHAN5 and wMuteAudioAndPauseMusic:
	ld a, c
	cp CHAN5
	jr nc, .applyAffects ; if sfx channel
	ld a, [wMuteAudioAndPauseMusic]
	and a
	jr z, .applyAffects
;>         if not wMuteAudioAndPauseMusic & 1 << BIT_MUTE_AUDIO:
	bit BIT_MUTE_AUDIO, a
	jr nz, .nextChannel
;>             wMuteAudioAndPauseMusic = wMuteAudioAndPauseMusic | 1 << BIT_MUTE_AUDIO
	set BIT_MUTE_AUDIO, a
	ld [wMuteAudioAndPauseMusic], a
;>             rAUDTERM = 0
	xor a ; disable all channels' output
	ldh [rAUDTERM], a
;>             rAUD3ENA = 0
	ldh [rAUD3ENA], a
;>             rAUD3ENA = AUD3ENA_ON
	ld a, AUD3ENA_ON
	ldh [rAUD3ENA], a
;>         continue
	jr .nextChannel
.applyAffects
;>     Audio1_ApplyMusicAffects(channel)
	call Audio1_ApplyMusicAffects
.nextChannel
	ld a, c
	inc c ; inc channel number
	cp CHAN8
	jr nz, .loop
	ret

; this routine checks flags for music effects currently applied
; to the channel and calls certain functions based on flags.
;@ path: audio/engine_1
;@ def Audio1_ApplyMusicAffects(channel: c)
;@ One frame of a channel: when its note is over, read on to the next note; otherwise count down and apply
;@ what changes during a note - the duty cycle pattern, a pitch slide, or vibrato (after its delay, the
;@ frequency swings above and below the note on alternate steps). A music channel an effect is using waits.
;@ test: channel = rand(0, 7)
;@ test: [mem.__setitem__(wChannelFlags1 + i, mem[wChannelFlags1 + i] & ~(1 << BIT_PITCH_SLIDE_ON)) for i in range(8)]
Audio1_ApplyMusicAffects:
;> delay = wChannelNoteDelayCounters[channel]
	ld b, $0
	ld hl, wChannelNoteDelayCounters ; delay until next note
	add hl, bc
	ld a, [hl]
;> if delay == 1:                                 # the note is over
;>     return Audio1_PlayNextNote(channel, 0)
	cp 1 ; if the delay is 1, play next note
	jp z, Audio1_PlayNextNote
;> wChannelNoteDelayCounters[channel] = (delay - 1) & 0xFF
	dec a ; otherwise, decrease the delay timer
	ld [hl], a
;> if channel < CHAN5:
	ld a, c
	cp CHAN5
	jr nc, .startChecks ; if a sfx channel
;>     if wChannelSoundIDs[CHAN5 + channel]:      # an effect is using its hardware channel
;>         return
	ld hl, wChannelSoundIDs + CHAN5
	add hl, bc
	ld a, [hl]
	and a
	jr z, .startChecks
	ret
.startChecks
;> if wChannelFlags1[channel] & 1 << BIT_ROTATE_DUTY_CYCLE:
	ld hl, wChannelFlags1
	add hl, bc
	bit BIT_ROTATE_DUTY_CYCLE, [hl]
	jr z, .checkForExecuteMusic
;>     Audio1_ApplyDutyCyclePattern(channel)
	call Audio1_ApplyDutyCyclePattern
.checkForExecuteMusic
;> if not wChannelFlags2[channel] & 1 << BIT_EXECUTE_MUSIC:
	ld b, 0
	ld hl, wChannelFlags2
	add hl, bc
	bit BIT_EXECUTE_MUSIC, [hl]
	jr nz, .checkForPitchSlide
;>     if wChannelFlags1[channel] & 1 << BIT_NOISE_OR_SFX:
;>         return                                 # an effect's own notes have no slides or vibrato
	ld hl, wChannelFlags1
	add hl, bc
	bit BIT_NOISE_OR_SFX, [hl]
	jr nz, .skipPitchSlideVibrato
.checkForPitchSlide
;> if wChannelFlags1[channel] & 1 << BIT_PITCH_SLIDE_ON:
	ld hl, wChannelFlags1
	add hl, bc
	bit BIT_PITCH_SLIDE_ON, [hl]
	jr z, .checkVibratoDelay
;>     return Audio1_ApplyPitchSlide(channel, 0)
	jp Audio1_ApplyPitchSlide
.checkVibratoDelay
;> if wChannelVibratoDelayCounters[channel]:     # the vibrato waits for its delay
	ld hl, wChannelVibratoDelayCounters
	add hl, bc
	ld a, [hl]
	and a ; check if delay is over
	jr z, .checkForVibrato
;>     wChannelVibratoDelayCounters[channel] = wChannelVibratoDelayCounters[channel] - 1
	dec [hl] ; otherwise, dec delay
.skipPitchSlideVibrato
;>     return
	ret
.checkForVibrato
;> extent = wChannelVibratoExtents[channel]
	ld hl, wChannelVibratoExtents
	add hl, bc
	ld a, [hl]
;> if not extent:                                # no vibrato
;>     return
	and a
	jr nz, .vibrato
	ret ; no vibrato
.vibrato
;> rate = wChannelVibratoRates[channel]         # high nibble: reload value, low nibble: counter
	ld d, a
	ld hl, wChannelVibratoRates
	add hl, bc
	ld a, [hl]
;> if rate & 0xF:
	and $f
	and a
	jr z, .applyVibrato
;>     wChannelVibratoRates[channel] = rate - 1
;>     return
	dec [hl] ; decrement counter
	ret
.applyVibrato
;> wChannelVibratoRates[channel] = rate | rate >> 4  # reload the counter
	ld a, [hl]
	swap [hl]
	or [hl]
	ld [hl], a ; reload the counter
;> low = wChannelFrequencyLowBytes[channel]     # the note's frequency
	ld hl, wChannelFrequencyLowBytes
	add hl, bc
	ld e, [hl] ; get note pitch
;> if wChannelFlags1[channel] & 1 << BIT_VIBRATO_DIRECTION:   # up and down on alternate steps
	ld hl, wChannelFlags1
	add hl, bc
; This is the only code that sets/resets the vibrato direction bit, so it
; continuously alternates which path it takes.
	bit BIT_VIBRATO_DIRECTION, [hl]
	jr z, .unset
;>     wChannelFlags1[channel] = wChannelFlags1[channel] & ~(1 << BIT_VIBRATO_DIRECTION) & 0xFF
	res BIT_VIBRATO_DIRECTION, [hl]
;>     below = extent & 0xF                      # the extent below the note
	ld a, d
	and $f
	ld d, a
;>     low = max(low - below, 0)
	ld a, e
	sub d
	jr nc, .noCarry
	ld a, 0
.noCarry
	jr .done
.unset
;> else:
;>     wChannelFlags1[channel] = wChannelFlags1[channel] | 1 << BIT_VIBRATO_DIRECTION
	set BIT_VIBRATO_DIRECTION, [hl]
;>     above = extent >> 4                       # the extent above the note
	ld a, d
	and $f0
	swap a
;>     low = min(low + above, 0xFF)
	add e
	jr nc, .done
	ld a, $ff
.done
;> mem[Audio1_GetRegisterPointer(REG_FREQUENCY_LO, channel)] = low
	ld d, a
	ld b, REG_FREQUENCY_LO
	call Audio1_GetRegisterPointer
	ld [hl], d
	ret

; this routine executes all music commands that take up no time,
; like tempo changes, duty cycle changes etc. and doesn't return
; until the first note is reached
;@ path: audio/engine_1
;@ def Audio1_PlayNextNote(channel: c, zero: b)
;@ A note has ended: restart the vibrato delay, end any pitch slide, and run the channel's commands up to
;@ its next note. b is 0 on entry.
;@ test: channel = rand(0, 7); zero = 0
;@ test: [mem.__setitem__(wChannelFlags1 + i, mem[wChannelFlags1 + i] & ~(1 << BIT_PITCH_SLIDE_ON)) for i in range(8)]
Audio1_PlayNextNote:
; reload the vibrato delay counter
;> wChannelVibratoDelayCounters[channel] = wChannelVibratoDelayCounterReloadValues[channel]
	ld hl, wChannelVibratoDelayCounterReloadValues
	add hl, bc
	ld a, [hl]
	ld hl, wChannelVibratoDelayCounters
	add hl, bc
	ld [hl], a

;> # the pitch slide is over
;> wChannelFlags1[channel] = wChannelFlags1[channel] & ~(1 << BIT_PITCH_SLIDE_ON | 1 << BIT_PITCH_SLIDE_DECREASING) & 0xFF
	ld hl, wChannelFlags1
	add hl, bc
	res BIT_PITCH_SLIDE_ON, [hl]
	res BIT_PITCH_SLIDE_DECREASING, [hl]
;> Audio1_sound_ret(channel)
	call Audio1_sound_ret
	ret

;@ path: audio/engine_1
;@ def Audio1_sound_ret(channel: c)
;@ Read and run a channel's next command. This is where the command chain starts: each handler below
;@ checks for its command and passes anything else on to the next one, until a note ends the frame's work.
;@ The sound_ret command itself returns from a sound_call, or ends the channel: its output is switched
;@ off, a finished cry restores the volume, and the channel's sound ID is cleared.
;@ test: channel = rand(0, 7)
;@ test: [mem.__setitem__(wChannelFlags1 + i, mem[wChannelFlags1 + i] & ~(1 << BIT_PITCH_SLIDE_ON)) for i in range(8)]
Audio1_sound_ret:
;> cmd = Audio1_GetNextMusicByte(channel)
	call Audio1_GetNextMusicByte
	ld d, a
;> if cmd != sound_ret_cmd:
;>     return Audio1_sound_call(channel, cmd, cmd)    # not this command: on down the chain
	cp sound_ret_cmd
	jp nz, Audio1_sound_call
;> if wChannelFlags1[channel] & 1 << BIT_SOUND_CALL:   # the end of a sound_call
	ld b, 0
	ld hl, wChannelFlags1
	add hl, bc
	bit BIT_SOUND_CALL, [hl]
	jr nz, .returnFromCall
;>@rf     wChannelFlags1[channel] = wChannelFlags1[channel] & ~(1 << BIT_SOUND_CALL) & 0xFF
;>@ri     i = 2 * channel & 0xFF                     # both tables hold 2-byte pointers
;>@rc     cur = addr(wChannelCommandPointers) + i
;>@rs     saved = addr(wChannelReturnAddresses) + i
;>@rp     mem[cur] = mem[saved]                      # back to the command after the call
;>@rp2     mem[cur + 1] = mem[saved + 1]
;>@rr     return Audio1_sound_ret(channel)            # and run it
;> if channel < CHAN4:
;>     disable = True                              # a music channel has ended: its output goes off
	ld a, c
	cp CHAN4
	jr nc, .noiseOrSfxChannel
	jr .disableChannelOutput
.noiseOrSfxChannel
;> else:                                           # an effect has ended: the hardware goes back to the music
;>     wChannelFlags1[channel] = wChannelFlags1[channel] & ~(1 << BIT_NOISE_OR_SFX) & 0xFF
	res BIT_NOISE_OR_SFX, [hl]
;>     wChannelFlags2[channel] = wChannelFlags2[channel] & ~(1 << BIT_EXECUTE_MUSIC) & 0xFF
	ld hl, wChannelFlags2
	add hl, bc
	res BIT_EXECUTE_MUSIC, [hl]
;>     if channel == CHAN7:
	cp CHAN7
	jr nz, .skipSfxChannel3
; restart hardware channel 3 (wave channel) output
;>         rAUD3ENA = AUD3ENA_OFF
	ld a, AUD3ENA_OFF
	ldh [rAUD3ENA], a
;>         rAUD3ENA = AUD3ENA_ON
	ld a, AUD3ENA_ON
	ldh [rAUD3ENA], a
.skipSfxChannel3
;>     disable = channel == CHAN7 and wDisableChannelOutputWhenSfxEnds != 0
	jr nz, .dontDisable
	ld a, [wDisableChannelOutputWhenSfxEnds]
	and a
	jr z, .dontDisable
;>     if disable:
;>         wDisableChannelOutputWhenSfxEnds = 0
	xor a
	ld [wDisableChannelOutputWhenSfxEnds], a
	jr .disableChannelOutput
.dontDisable
;=@cut
	jr .afterDisable
.returnFromCall
;=@rf
	res BIT_SOUND_CALL, [hl]
;=@ri
	ld d, $0
	ld a, c
	add a
	ld e, a
;=@rc
	ld hl, wChannelCommandPointers
	add hl, de
	push hl ; store current channel address
;=@rs
	ld hl, wChannelReturnAddresses
	add hl, de
	ld e, l
	ld d, h
	pop hl
;=@rp
	ld a, [de]
	ld [hli], a
;=@rp2
	inc de
	ld a, [de]
	ld [hl], a ; loads channel address to return to
;=@rr
	jp Audio1_sound_ret
.disableChannelOutput
;>@cut if disable:
;>     rAUDTERM = rAUDTERM & mem[Audio1_HWChannelDisableMasks + channel]
	ld hl, Audio1_HWChannelDisableMasks
	add hl, bc
	ldh a, [rAUDTERM]
	and [hl]
	ldh [rAUDTERM], a
.afterDisable
;>@cry if (SFX_Cry00_1 - SFX_Headers_1) // 3 <= wChannelSoundIDs[CHAN5] < ((SFX_Cry25_1 - SFX_Headers_1) // 3 + 3):   # a cry is playing
	ld a, [wChannelSoundIDs + CHAN5]
	cp CRY_SFX_START
	jr nc, .maybeCry
	jr .skipCry
.maybeCry
;=@cry
	ld a, [wChannelSoundIDs + CHAN5]
	cp CRY_SFX_END
	jr z, .skipCry
	jr c, .cry
	jr .skipCry
.cry
;>     if channel != CHAN5 and Audio1_GoBackOneCommandIfCry(channel):
;>         return                                  # the cry's other channels wait for channel 5
	ld a, c
	cp CHAN5
	jr z, .skipRewind
	call Audio1_GoBackOneCommandIfCry
	ret c
.skipRewind
;>     rAUDVOL = wSavedVolume                      # the cry is over: the volume from before it
	ld a, [wSavedVolume]
	ldh [rAUDVOL], a
;>     wSavedVolume = 0
	xor a
	ld [wSavedVolume], a
.skipCry
;> wChannelSoundIDs[channel] = 0                   # the channel is free
	ld hl, wChannelSoundIDs
	add hl, bc
	ld [hl], b
	ret

;@ path: audio/engine_1
;@ def Audio1_sound_call(channel: c, cmd: a, cmd_d: d)
;@ sound_call: remember where the channel is and continue at the address that follows (a subroutine of
;@ sound data). The command byte arrives in both a and d.
;@ test: cmd = sound_call_cmd if rand(0, 1) else rand(0, 255); cmd_d = cmd; channel = rand(0, 7)
;@ test: [mem.__setitem__(wChannelFlags1 + i, mem[wChannelFlags1 + i] & ~(1 << BIT_PITCH_SLIDE_ON)) for i in range(8)]
Audio1_sound_call:
;> if cmd != sound_call_cmd:
;>     return Audio1_sound_loop(channel, cmd, cmd_d)
	cp sound_call_cmd
	jp nz, Audio1_sound_loop
;> lo = Audio1_GetNextMusicByte(channel)        # the address to call
	call Audio1_GetNextMusicByte
	push af
;> hi = Audio1_GetNextMusicByte(channel)
	call Audio1_GetNextMusicByte
	ld d, a
	pop af
	ld e, a
	push de ; store pointer
;> i = 2 * channel & 0xFF
	ld d, $0
	ld a, c
	add a
	ld e, a
;> cur = addr(wChannelCommandPointers) + i
	ld hl, wChannelCommandPointers
	add hl, de
	push hl
;> saved = addr(wChannelReturnAddresses) + i
	ld hl, wChannelReturnAddresses
	add hl, de
	ld e, l
	ld d, h
	pop hl
;> mem[saved] = mem[cur]                       # where to come back to
	ld a, [hli]
	ld [de], a
;> mem[saved + 1] = mem[cur + 1]
	inc de
	ld a, [hld]
	ld [de], a ; copy current channel address
;> mem[cur] = lo
	pop de
	ld [hl], e
;> mem[cur + 1] = hi
	inc hl
	ld [hl], d ; overwrite current address with pointer
;> wChannelFlags1[channel] = wChannelFlags1[channel] | 1 << BIT_SOUND_CALL
	ld b, $0
	ld hl, wChannelFlags1
	add hl, bc
	set BIT_SOUND_CALL, [hl] ; set the call flag
;> return Audio1_sound_ret(channel)
	jp Audio1_sound_ret

;@ path: audio/engine_1
;@ def Audio1_sound_loop(channel: c, cmd: a, cmd_d: d)
;@ sound_loop count, address: jump back `count` times (0 = forever), then go on after the command.
;@ test: cmd = sound_loop_cmd if rand(0, 1) else rand(0, 255); cmd_d = cmd; channel = rand(0, 7)
;@ test: [mem.__setitem__(wChannelFlags1 + i, mem[wChannelFlags1 + i] & ~(1 << BIT_PITCH_SLIDE_ON)) for i in range(8)]
Audio1_sound_loop:
;> if cmd != sound_loop_cmd:
;>     return Audio1_note_type(channel, cmd, cmd_d)
	cp sound_loop_cmd
	jp nz, Audio1_note_type
;> count = Audio1_GetNextMusicByte(channel)
	call Audio1_GetNextMusicByte
	ld e, a
;> if count:
	and a
	jr z, .infiniteLoop
;>     if wChannelLoopCounters[channel] == count:
	ld b, 0
	ld hl, wChannelLoopCounters
	add hl, bc
	ld a, [hl]
	cp e
	jr nz, .loopAgain
;>         wChannelLoopCounters[channel] = 1      # done: skip the address
	ld a, $1 ; if no more loops to make,
	ld [hl], a
;>         Audio1_GetNextMusicByte(channel)
	call Audio1_GetNextMusicByte ; skip pointer
;>         Audio1_GetNextMusicByte(channel)
	call Audio1_GetNextMusicByte
;>         return Audio1_sound_ret(channel)
	jp Audio1_sound_ret
.loopAgain ; inc loop count
;>     wChannelLoopCounters[channel] = (wChannelLoopCounters[channel] + 1) & 0xFF
	inc a
	ld [hl], a
	; fall through
.infiniteLoop ; overwrite current address with pointer
;> lo = Audio1_GetNextMusicByte(channel)
	call Audio1_GetNextMusicByte
	push af
;> hi = Audio1_GetNextMusicByte(channel)
	call Audio1_GetNextMusicByte
	ld b, a
;> i = 2 * channel & 0xFF
	ld d, $0
	ld a, c
	add a
	ld e, a
;> wChannelCommandPointers[i] = lo
	ld hl, wChannelCommandPointers
	add hl, de
	pop af
	ld [hli], a
;> wChannelCommandPointers[i + 1] = hi
	ld [hl], b
;> return Audio1_sound_ret(channel)
	jp Audio1_sound_ret

;@ path: audio/engine_1
;@ def Audio1_note_type(channel: c, cmd: a, cmd_d: d)
;@ note_type speed, volume, fade: the low nibble is the note speed; then one byte of volume and fade (none on
;@ the noise channel). On the wave channel the byte picks the wave instrument and a volume level instead.
;@ test: cmd = note_type_cmd | rand(0, 15) if rand(0, 1) else rand(0, 255); cmd_d = cmd; channel = rand(0, 7)
;@ test: [mem.__setitem__(wChannelFlags1 + i, mem[wChannelFlags1 + i] & ~(1 << BIT_PITCH_SLIDE_ON)) for i in range(8)]
Audio1_note_type:
;> if cmd & 0xF0 != note_type_cmd:
;>     return Audio1_toggle_perfect_pitch(channel, cmd_d)
	and $f0
	cp note_type_cmd
	jp nz, Audio1_toggle_perfect_pitch
;> wChannelNoteSpeeds[channel] = cmd_d & 0xF
	ld a, d
	and $f
	ld b, $0
	ld hl, wChannelNoteSpeeds
	add hl, bc
	ld [hl], a ; store low nibble as speed
;> if channel != CHAN4:                          # the noise channel has no parameter byte
	ld a, c
	cp CHAN4
	jr z, .noiseChannel ; noise channel has 0 params
;>     param = Audio1_GetNextMusicByte(channel)
	call Audio1_GetNextMusicByte
	ld d, a
;>     if channel == CHAN3:
	ld a, c
	cp CHAN3
	jr z, .musicChannel3
;>@mw         slot = addr(wMusicWaveInstrument)
;>     elif channel == CHAN7:
	cp CHAN7
	jr nz, .skipChannel3
;>         slot = addr(wSfxWaveInstrument)
	ld hl, wSfxWaveInstrument
	jr .channel3
.musicChannel3
;=@mw
	ld hl, wMusicWaveInstrument
.channel3
;>     if channel in (CHAN3, CHAN7):              # the wave channel
;>         mem[slot] = param & 0xF                # the wave instrument
	ld a, d
	and $f
	ld [hl], a ; store low nibble of param as wave instrument
;>         param = (param & 0x30) << 1            # and a volume level
	ld a, d
	and $30
	sla a
	ld d, a
	; fall through

	; if channel 3, store high nibble as volume
	; else, store volume (high nibble) and fade (low nibble)
.skipChannel3
;>     wChannelVolumes[channel] = param
	ld b, 0
	ld hl, wChannelVolumes
	add hl, bc
	ld [hl], d
.noiseChannel
;> return Audio1_sound_ret(channel)
	jp Audio1_sound_ret

;@ path: audio/engine_1
;@ def Audio1_toggle_perfect_pitch(channel: c, cmd: d)
;@ toggle_perfect_pitch: from now on play every note one step higher (or stop doing so).
;@ test: cmd = toggle_perfect_pitch_cmd if rand(0, 1) else rand(0, 255); channel = rand(0, 7)
;@ test: [mem.__setitem__(wChannelFlags1 + i, mem[wChannelFlags1 + i] & ~(1 << BIT_PITCH_SLIDE_ON)) for i in range(8)]
Audio1_toggle_perfect_pitch:
;> if cmd != toggle_perfect_pitch_cmd:
;>     return Audio1_vibrato(channel, cmd, cmd)
	ld a, d
	cp toggle_perfect_pitch_cmd
	jr nz, Audio1_vibrato
;> wChannelFlags1[channel] = wChannelFlags1[channel] ^ 1 << BIT_PERFECT_PITCH
	ld b, 0
	ld hl, wChannelFlags1
	add hl, bc
	ld a, [hl]
	xor 1 << BIT_PERFECT_PITCH
	ld [hl], a
;> return Audio1_sound_ret(channel)
	jp Audio1_sound_ret

;@ path: audio/engine_1
;@ def Audio1_vibrato(channel: c, cmd: a, cmd_d: d)
;@ vibrato delay, extent and rate: after `delay` frames the pitch wobbles by `extent` steps around the note,
;@ split into half above and half below.
;@ test: cmd = vibrato_cmd if rand(0, 1) else rand(0, 255); cmd_d = cmd; channel = rand(0, 7)
;@ test: [mem.__setitem__(wChannelFlags1 + i, mem[wChannelFlags1 + i] & ~(1 << BIT_PITCH_SLIDE_ON)) for i in range(8)]
Audio1_vibrato:
;> if cmd != vibrato_cmd:
;>     return Audio1_pitch_slide(channel, cmd, cmd_d)
	cp vibrato_cmd
	jr nz, Audio1_pitch_slide
;> delay = Audio1_GetNextMusicByte(channel)
	call Audio1_GetNextMusicByte
;> wChannelVibratoDelayCounters[channel] = delay
	ld b, 0
	ld hl, wChannelVibratoDelayCounters
	add hl, bc
	ld [hl], a ; store delay
;> wChannelVibratoDelayCounterReloadValues[channel] = delay
	ld hl, wChannelVibratoDelayCounterReloadValues
	add hl, bc
	ld [hl], a ; store delay
;> param = Audio1_GetNextMusicByte(channel)
	call Audio1_GetNextMusicByte
	ld d, a

; The high nybble of the command byte is the extent of the vibrato.
; Let n be the extent.
; The upper nybble of the channel's byte in the wChannelVibratoExtents
; array will store the extent above the note: (n / 2) + (n % 2).
; The lower nybble will store the extent below the note: (n / 2).
; These two values add to the total extent, n.
;> extent = param >> 4
	and $f0
	swap a
;> half = extent // 2                           # below the note
	ld b, 0
	ld hl, wChannelVibratoExtents
	add hl, bc
	srl a
	ld e, a
;> wChannelVibratoExtents[channel] = (half + extent % 2) << 4 | half   # above | below
	adc b
	swap a
	or e
	ld [hl], a

; The low nybble of the command byte is the rate of the vibrato.
; The high and low nybbles of the channel's byte in the wChannelVibratoRates
; array are both initialised to this value because the high nybble is the
; counter reload value and the low nybble is the counter itself, which should
; start at its value upon reload.
;> rate = param & 0xF
	ld a, d
	and $f
	ld d, a
;> wChannelVibratoRates[channel] = rate << 4 | rate      # reload value and counter
	ld hl, wChannelVibratoRates
	add hl, bc
	swap a
	or d
	ld [hl], a

;> return Audio1_sound_ret(channel)
	jp Audio1_sound_ret

;@ path: audio/engine_1
;@ def Audio1_pitch_slide(channel: c, cmd: a, cmd_d: d)
;@ pitch_slide length, octave and note: the next note slides towards this target pitch.
;@ test: cmd = pitch_slide_cmd if rand(0, 1) else rand(0, 255); cmd_d = cmd; channel = rand(0, 7)
;@ test: [mem.__setitem__(wChannelFlags1 + i, mem[wChannelFlags1 + i] & ~(1 << BIT_PITCH_SLIDE_ON)) for i in range(8)]
Audio1_pitch_slide:
;> if cmd != pitch_slide_cmd:
;>     return Audio1_duty_cycle(channel, cmd, cmd_d)
	cp pitch_slide_cmd
	jr nz, Audio1_duty_cycle
;> wChannelPitchSlideLengthModifiers[channel] = Audio1_GetNextMusicByte(channel)
	call Audio1_GetNextMusicByte
	ld b, 0
	ld hl, wChannelPitchSlideLengthModifiers
	add hl, bc
	ld [hl], a
;> target = Audio1_GetNextMusicByte(channel)
	call Audio1_GetNextMusicByte
	ld d, a
;> freq = Audio1_CalculateFrequency(target & 0xF, target >> 4)
	and $f0
	swap a
	ld b, a
	ld a, d
	and $f
	call Audio1_CalculateFrequency
;> wChannelPitchSlideTargetFrequencyHighBytes[channel] = freq >> 8
	ld b, 0
	ld hl, wChannelPitchSlideTargetFrequencyHighBytes
	add hl, bc
	ld [hl], d
;> wChannelPitchSlideTargetFrequencyLowBytes[channel] = freq & 0xFF
	ld hl, wChannelPitchSlideTargetFrequencyLowBytes
	add hl, bc
	ld [hl], e
;> wChannelFlags1[channel] = wChannelFlags1[channel] | 1 << BIT_PITCH_SLIDE_ON
	ld b, 0
	ld hl, wChannelFlags1
	add hl, bc
	set BIT_PITCH_SLIDE_ON, [hl]
;> return Audio1_note_length(channel, Audio1_GetNextMusicByte(channel))
	call Audio1_GetNextMusicByte
	ld d, a
	jp Audio1_note_length

;@ path: audio/engine_1
;@ def Audio1_duty_cycle(channel: c, cmd: a, cmd_d: d)
;@ duty_cycle n: the square wave's duty (0 = 12.5%, 1 = 25%, 2 = 50%, 3 = 75%).
;@ test: cmd = duty_cycle_cmd if rand(0, 1) else rand(0, 255); cmd_d = cmd; channel = rand(0, 7)
;@ test: [mem.__setitem__(wChannelFlags1 + i, mem[wChannelFlags1 + i] & ~(1 << BIT_PITCH_SLIDE_ON)) for i in range(8)]
Audio1_duty_cycle:
;> if cmd != duty_cycle_cmd:
;>     return Audio1_tempo(channel, cmd, cmd_d)
	cp duty_cycle_cmd
	jr nz, Audio1_tempo
;> duty = (Audio1_GetNextMusicByte(channel) & 3) << 6     # into bits 6-7, where the hardware has it
	call Audio1_GetNextMusicByte
	rrca
	rrca
	and $c0
;> wChannelDutyCycles[channel] = duty
	ld b, 0
	ld hl, wChannelDutyCycles
	add hl, bc
	ld [hl], a ; store duty cycle
;> return Audio1_sound_ret(channel)
	jp Audio1_sound_ret

;@ path: audio/engine_1
;@ def Audio1_tempo(channel: c, cmd: a, cmd_d: d)
;@ tempo hi, lo: the music's tempo (on a music channel) or the effects' tempo; the fractional parts of the
;@ note timers start again from 0.
;@ test: cmd = tempo_cmd if rand(0, 1) else rand(0, 255); cmd_d = cmd; channel = rand(0, 7)
;@ test: [mem.__setitem__(wChannelFlags1 + i, mem[wChannelFlags1 + i] & ~(1 << BIT_PITCH_SLIDE_ON)) for i in range(8)]
Audio1_tempo:
;> if cmd != tempo_cmd:
;>     return Audio1_stereo_panning(channel, cmd, cmd_d)
	cp tempo_cmd
	jr nz, Audio1_stereo_panning
;> if channel < CHAN5:
	ld a, c
	cp CHAN5
	jr nc, .sfxChannel
;>     wMusicTempo[0] = Audio1_GetNextMusicByte(channel)
	call Audio1_GetNextMusicByte
	ld [wMusicTempo], a ; store first param
;>     wMusicTempo[1] = Audio1_GetNextMusicByte(channel)
	call Audio1_GetNextMusicByte
	ld [wMusicTempo + 1], a ; store second param
;>     fill(addr(wChannelNoteDelayCountersFractionalPart), 0, 4)       # the music channels' fractions
	xor a
	ld [wChannelNoteDelayCountersFractionalPart], a ; clear RAM
	ld [wChannelNoteDelayCountersFractionalPart + 1], a
	ld [wChannelNoteDelayCountersFractionalPart + 2], a
	ld [wChannelNoteDelayCountersFractionalPart + 3], a
	jr .musicChannelDone
.sfxChannel
;> else:
;>     wSfxTempo[0] = Audio1_GetNextMusicByte(channel)
	call Audio1_GetNextMusicByte
	ld [wSfxTempo], a ; store first param
;>     wSfxTempo[1] = Audio1_GetNextMusicByte(channel)
	call Audio1_GetNextMusicByte
	ld [wSfxTempo + 1], a ; store second param
;>     fill(addr(wChannelNoteDelayCountersFractionalPart) + 4, 0, 4)   # the effect channels' fractions
	xor a
	ld [wChannelNoteDelayCountersFractionalPart + 4], a ; clear RAM
	ld [wChannelNoteDelayCountersFractionalPart + 5], a
	ld [wChannelNoteDelayCountersFractionalPart + 6], a
	ld [wChannelNoteDelayCountersFractionalPart + 7], a
.musicChannelDone
;> return Audio1_sound_ret(channel)
	jp Audio1_sound_ret

;@ path: audio/engine_1
;@ def Audio1_stereo_panning(channel: c, cmd: a, cmd_d: d)
;@ stereo_panning: which channels play on the left and right speaker.
;@ test: cmd = stereo_panning_cmd if rand(0, 1) else rand(0, 255); cmd_d = cmd; channel = rand(0, 7)
;@ test: [mem.__setitem__(wChannelFlags1 + i, mem[wChannelFlags1 + i] & ~(1 << BIT_PITCH_SLIDE_ON)) for i in range(8)]
Audio1_stereo_panning:
;> if cmd != stereo_panning_cmd:
;>     return Audio1_unknownmusic0xef(channel, cmd, cmd_d)
	cp stereo_panning_cmd
	jr nz, Audio1_unknownmusic0xef
;> wStereoPanning = Audio1_GetNextMusicByte(channel)
	call Audio1_GetNextMusicByte
	ld [wStereoPanning], a ; store panning
;> return Audio1_sound_ret(channel)
	jp Audio1_sound_ret

; this appears to never be used
;@ path: audio/engine_1
;@ def Audio1_unknownmusic0xef(channel: c, cmd: a, cmd_d: d)
;@ Command $EF: start another sound from inside the sound data, and let it switch its channel's output off
;@ when it ends. No sound in the game uses it.
;@ test: cmd = unknownmusic0xef_cmd if rand(0, 1) else rand(0, 255); cmd_d = cmd; channel = rand(0, 7)
;@ test: [mem.__setitem__(wChannelFlags1 + i, mem[wChannelFlags1 + i] & ~(1 << BIT_PITCH_SLIDE_ON)) for i in range(8)]
Audio1_unknownmusic0xef:
;> if cmd != unknownmusic0xef_cmd:
;>     return Audio1_duty_cycle_pattern(channel, cmd, cmd_d)
	cp unknownmusic0xef_cmd
	jr nz, Audio1_duty_cycle_pattern
;> Audio1_PlaySound(Audio1_GetNextMusicByte(channel))
	call Audio1_GetNextMusicByte
	push bc
	call Audio1_PlaySound
	pop bc
;> if not wDisableChannelOutputWhenSfxEnds:
	ld a, [wDisableChannelOutputWhenSfxEnds]
	and a
	jr nz, .skip
;>     wDisableChannelOutputWhenSfxEnds = wChannelSoundIDs[CHAN8]
	ld a, [wChannelSoundIDs + CHAN8]
	ld [wDisableChannelOutputWhenSfxEnds], a
;>     wChannelSoundIDs[CHAN8] = 0
	xor a
	ld [wChannelSoundIDs + CHAN8], a
.skip
;> return Audio1_sound_ret(channel)
	jp Audio1_sound_ret

;@ path: audio/engine_1
;@ def Audio1_duty_cycle_pattern(channel: c, cmd: a, cmd_d: d)
;@ duty_cycle_pattern: four 2-bit duties that take turns, one per frame.
;@ test: cmd = duty_cycle_pattern_cmd if rand(0, 1) else rand(0, 255); cmd_d = cmd; channel = rand(0, 7)
;@ test: [mem.__setitem__(wChannelFlags1 + i, mem[wChannelFlags1 + i] & ~(1 << BIT_PITCH_SLIDE_ON)) for i in range(8)]
Audio1_duty_cycle_pattern:
;> if cmd != duty_cycle_pattern_cmd:
;>     return Audio1_volume(channel, cmd, cmd_d)
	cp duty_cycle_pattern_cmd
	jr nz, Audio1_volume
;> pattern = Audio1_GetNextMusicByte(channel)
	call Audio1_GetNextMusicByte
;> wChannelDutyCyclePatterns[channel] = pattern
	ld b, 0
	ld hl, wChannelDutyCyclePatterns
	add hl, bc
	ld [hl], a ; store full pattern
;> wChannelDutyCycles[channel] = pattern & 0xC0
	and %11000000
	ld hl, wChannelDutyCycles
	add hl, bc
	ld [hl], a ; store first duty cycle
;> wChannelFlags1[channel] = wChannelFlags1[channel] | 1 << BIT_ROTATE_DUTY_CYCLE
	ld hl, wChannelFlags1
	add hl, bc
	set BIT_ROTATE_DUTY_CYCLE, [hl]
;> return Audio1_sound_ret(channel)
	jp Audio1_sound_ret

;@ path: audio/engine_1
;@ def Audio1_volume(channel: c, cmd: a, cmd_d: d)
;@ volume: the master volume of both speakers.
;@ test: cmd = volume_cmd if rand(0, 1) else rand(0, 255); cmd_d = cmd; channel = rand(0, 7)
;@ test: [mem.__setitem__(wChannelFlags1 + i, mem[wChannelFlags1 + i] & ~(1 << BIT_PITCH_SLIDE_ON)) for i in range(8)]
Audio1_volume:
;> if cmd != volume_cmd:
;>     return Audio1_execute_music(channel, cmd, cmd_d)
	cp volume_cmd
	jr nz, Audio1_execute_music
;> rAUDVOL = Audio1_GetNextMusicByte(channel)
	call Audio1_GetNextMusicByte
	ldh [rAUDVOL], a ; store volume
;> return Audio1_sound_ret(channel)
	jp Audio1_sound_ret

;@ path: audio/engine_1
;@ def Audio1_execute_music(channel: c, cmd: a, cmd_d: d)
;@ execute_music: an effect channel reads the rest of its data as music commands (no sfx_note or pitch_sweep).
;@ test: cmd = execute_music_cmd if rand(0, 1) else rand(0, 255); cmd_d = cmd; channel = rand(0, 7)
;@ test: [mem.__setitem__(wChannelFlags1 + i, mem[wChannelFlags1 + i] & ~(1 << BIT_PITCH_SLIDE_ON)) for i in range(8)]
Audio1_execute_music:
;> if cmd != execute_music_cmd:
;>     return Audio1_octave(channel, cmd, cmd_d)
	cp execute_music_cmd
	jr nz, Audio1_octave
;> wChannelFlags2[channel] = wChannelFlags2[channel] | 1 << BIT_EXECUTE_MUSIC
	ld b, $0
	ld hl, wChannelFlags2
	add hl, bc
	set BIT_EXECUTE_MUSIC, [hl]
;> return Audio1_sound_ret(channel)
	jp Audio1_sound_ret

;@ path: audio/engine_1
;@ def Audio1_octave(channel: c, cmd: a, cmd_d: d)
;@ octave n: the octave of the notes that follow.
;@ test: cmd = octave_cmd | rand(0, 15) if rand(0, 1) else rand(0, 255); cmd_d = cmd; channel = rand(0, 7)
;@ test: [mem.__setitem__(wChannelFlags1 + i, mem[wChannelFlags1 + i] & ~(1 << BIT_PITCH_SLIDE_ON)) for i in range(8)]
Audio1_octave:
;> if cmd & 0xF0 != octave_cmd:
;>     return Audio1_sfx_note(channel, cmd & 0xF0, cmd_d)
	and $f0
	cp octave_cmd
	jr nz, Audio1_sfx_note
;> wChannelOctaves[channel] = cmd_d & 0xF
	ld hl, wChannelOctaves
	ld b, 0
	add hl, bc
	ld a, d
	and $f
	ld [hl], a ; store low nibble as octave
;> return Audio1_sound_ret(channel)
	jp Audio1_sound_ret

; sfx_note is either square_note or noise_note depending on the channel
;@ path: audio/engine_1
;@ def Audio1_sfx_note(channel: c, cmd: a, cmd_d: d)
;@ A sound effect's note (square_note or noise_note): length, volume envelope and frequency written straight
;@ to the channel's registers. a holds the command's high nibble, d the whole command.
;@ test: cmd_d = sfx_note_cmd | rand(0, 15) if rand(0, 1) else rand(0, 255); cmd = cmd_d & 0xF0; channel = rand(0, 7)
;@ test: [mem.__setitem__(wChannelFlags1 + i, mem[wChannelFlags1 + i] & ~(1 << BIT_PITCH_SLIDE_ON)) for i in range(8)]
;@ test: mem[wChannelFlags1 + channel] |= 1 << BIT_NOISE_OR_SFX
Audio1_sfx_note:
;> if cmd != sfx_note_cmd:
;>     return Audio1_pitch_sweep(channel, cmd_d)
	cp sfx_note_cmd
	jr nz, Audio1_pitch_sweep
;> if channel < CHAN4:                            # only on the noise and effect channels
;>     return Audio1_pitch_sweep(channel, cmd_d)
	ld a, c
	cp CHAN4 ; is this a noise or sfx channel?
	jr c, Audio1_pitch_sweep ; no
;> if wChannelFlags2[channel] & 1 << BIT_EXECUTE_MUSIC:   # not while it reads music commands
;>     return Audio1_pitch_sweep(channel, cmd_d)
	ld b, 0
	ld hl, wChannelFlags2
	add hl, bc
	bit BIT_EXECUTE_MUSIC, [hl] ; is execute_music being used?
	jr nz, Audio1_pitch_sweep ; yes
;> Audio1_note_length(channel, cmd_d)
	call Audio1_note_length

; This code seems to do the same thing as what Audio1_ApplyDutyCycleAndSoundLength
; does below.
;> length = wChannelNoteDelayCounters[channel]   # (left in a by note_length)
	ld d, a
;> value = wChannelDutyCycles[channel] | length
	ld b, 0
	ld hl, wChannelDutyCycles
	add hl, bc
	ld a, [hl]
	or d
	ld d, a
;> mem[Audio1_GetRegisterPointer(REG_DUTY_SOUND_LEN, channel)] = value
	ld b, REG_DUTY_SOUND_LEN
	call Audio1_GetRegisterPointer
	ld [hl], d

;> envelope = Audio1_GetNextMusicByte(channel)
	call Audio1_GetNextMusicByte
	ld d, a
;> mem[Audio1_GetRegisterPointer(REG_VOLUME_ENVELOPE, channel)] = envelope
	ld b, REG_VOLUME_ENVELOPE
	call Audio1_GetRegisterPointer
	ld [hl], d
;> lo = Audio1_GetNextMusicByte(channel)
	call Audio1_GetNextMusicByte
	ld e, a
;> hi = 0
;> if channel != CHAN8:
	ld a, c
	cp CHAN8
	ld a, 0
	jr z, .skip
; Channels 1 through 3 have 2 registers that control frequency, but the noise
; channel a single register (the polynomial counter) that controls frequency,
; so this command has one less byte on the noise channel.
;>     hi = Audio1_GetNextMusicByte(channel)
	push de
	call Audio1_GetNextMusicByte
	pop de
.skip
;> freq = hi << 8 | lo
	ld d, a
	push de
;> Audio1_ApplyDutyCycleAndSoundLength(channel)
	call Audio1_ApplyDutyCycleAndSoundLength
;> Audio1_EnableChannelOutput(channel)
	call Audio1_EnableChannelOutput
;> Audio1_ApplyWavePatternAndFrequency(channel, freq)
	pop de
	call Audio1_ApplyWavePatternAndFrequency
	ret

;@ path: audio/engine_1
;@ def Audio1_pitch_sweep(channel: c, cmd: d)
;@ pitch_sweep: an effect on channel 1 sets the hardware frequency sweep.
;@ test: cmd = pitch_sweep_cmd if rand(0, 1) else rand(0, 255); channel = rand(0, 7)
;@ test: [mem.__setitem__(wChannelFlags1 + i, mem[wChannelFlags1 + i] & ~(1 << BIT_PITCH_SLIDE_ON)) for i in range(8)]
Audio1_pitch_sweep:
;> if channel < CHAN5:                             # only effects use it
;>     return Audio1_note(channel, cmd)
	ld a, c
	cp CHAN5
	jr c, Audio1_note ; if not a sfx
;> if cmd != pitch_sweep_cmd:
;>     return Audio1_note(channel, cmd)
	ld a, d
	cp pitch_sweep_cmd
	jr nz, Audio1_note
;> if wChannelFlags2[channel] & 1 << BIT_EXECUTE_MUSIC:
;>     return Audio1_note(channel, cmd)
	ld b, $0
	ld hl, wChannelFlags2
	add hl, bc
	bit BIT_EXECUTE_MUSIC, [hl]
	jr nz, Audio1_note ; no
;> rAUD1SWEEP = Audio1_GetNextMusicByte(channel)
	call Audio1_GetNextMusicByte
	ldh [rAUD1SWEEP], a
;> return Audio1_sound_ret(channel)
	jp Audio1_sound_ret

;@ path: audio/engine_1
;@ def Audio1_note(channel: c, cmd: d)
;@ A note. On the music noise channel it is a drum: drum_note plays a noise instrument (one of the noise
;@ sound effects) and waits; a single byte below $B0 is an unused shorter form of it.
;@ test: cmd = rand(0, 255); channel = CHAN4 if rand(0, 1) else rand(0, 7)
;@ test: [mem.__setitem__(wChannelFlags1 + i, mem[wChannelFlags1 + i] & ~(1 << BIT_PITCH_SLIDE_ON)) for i in range(8)]
Audio1_note:
;> if channel != CHAN4:                            # drums only on the noise channel
;>     return Audio1_note_length(channel, cmd)
	ld a, c
	cp CHAN4
	jr nz, Audio1_note_length ; if not noise channel
;> kind = cmd & 0xF0
	ld a, d
	and $f0
;> if kind == drum_note_cmd:
	cp drum_note_cmd
	jr z, .drum_note
;>@dlen     cmd = cmd & 0xF                         # the length
;>@dins     instrument = Audio1_GetNextMusicByte(channel)   # the instrument in the next byte
;> elif kind > drum_note_cmd:
;>     return Audio1_note_length(channel, cmd)
	jr nc, Audio1_note_length

	; this executes when on the noise channel and
	; the command id is less than drum_note_cmd ($b0)
	; in this case, the upper nybble is used as the noise instrument ($1-$a)
	; and the lower nybble is the length minus 1 (0-15)
	; however, this doesn't work for instrument #2 because the command id
	; is captured by the noise_note command (command id $2x)
	; this essentially acts like a drum_note command that is only 1 byte
	; instead of 2 and can only be used with instruments 1 and 3 through 10
	; this is unused by the game
;> else:
;>     instrument = cmd >> 4
	swap a
	ld b, a
;>     cmd = cmd & 0xF                             # the length
	ld a, d
	and $f
	ld d, a
	ld a, b
;>     # (the length and channel are kept for later)
	push de
	push bc
	jr .playDnote

.drum_note
;=@dlen
	ld a, d
	and $f
	push af
	push bc
;=@dins
	call Audio1_GetNextMusicByte ; get drum_note instrument
.playDnote
;> if not wDisableChannelOutputWhenSfxEnds:
	ld d, a
	ld a, [wDisableChannelOutputWhenSfxEnds]
	and a
	jr nz, .skipDnote
;>     Audio1_PlaySound(instrument)                # the instrument is a noise sound effect
	ld a, d
	call Audio1_PlaySound
.skipDnote
;> return Audio1_note_length(channel, cmd)         # and wait for the drum's length
	pop bc
	pop de

;@ path: audio/engine_1
;@ def Audio1_note_length(channel: c, cmd: d)
;@ How long the note lasts: (length + 1) * note speed * tempo, in 1/256 frames, added to the fractional part
;@ left over from the last note. Then the note's pitch, unless this is an effect's own note.
;@ test: cmd = rand(0, 255); channel = rand(0, 7)
;@ test: [mem.__setitem__(wChannelFlags1 + i, mem[wChannelFlags1 + i] & ~(1 << BIT_PITCH_SLIDE_ON)) for i in range(8)]
Audio1_note_length:
;> kept = cmd                                      # for note_pitch
	ld a, d
	push af
;> length = (cmd & 0xF) + 1                        # in 16ths
	and $f
	inc a
	ld b, 0
	ld e, a  ; store note length (in 16ths)
	ld d, b
;> ticks = Audio1_MultiplyAdd(wChannelNoteSpeeds[channel], length, 0) & 0xFF
	ld hl, wChannelNoteSpeeds
	add hl, bc
	ld a, [hl]
	ld l, b
	call Audio1_MultiplyAdd
;> if channel < CHAN5:
	ld a, c
	cp CHAN5
	jr nc, .sfxChannel
;>     tempo = wMusicTempo[0] << 8 | wMusicTempo[1]
	ld a, [wMusicTempo]
	ld d, a
	ld a, [wMusicTempo + 1]
	ld e, a
	jr .skip
.sfxChannel
;> elif channel == CHAN8:
;>     tempo = 0x100
	ld d, $1
	ld e, $0
	cp CHAN8
	jr z, .skip ; if noise channel
;> else:
;>     Audio1_SetSfxTempo()
	call Audio1_SetSfxTempo
;>     tempo = wSfxTempo[0] << 8 | wSfxTempo[1]
	ld a, [wSfxTempo]
	ld d, a
	ld a, [wSfxTempo + 1]
	ld e, a
.skip
;> total = Audio1_MultiplyAdd(ticks, tempo, wChannelNoteDelayCountersFractionalPart[channel])
	ld a, l ; a = note_length * note_speed
	ld b, 0
	ld hl, wChannelNoteDelayCountersFractionalPart
	add hl, bc
	ld l, [hl]
	call Audio1_MultiplyAdd
;> wChannelNoteDelayCountersFractionalPart[channel] = total & 0xFF
	ld e, l
	ld d, h ; de = note_delay_frac_part + (note_length * note_speed * tempo)
	ld hl, wChannelNoteDelayCountersFractionalPart
	add hl, bc
	ld [hl], e
;> wChannelNoteDelayCounters[channel] = total >> 8      # whole frames
	ld a, d
	ld hl, wChannelNoteDelayCounters
	add hl, bc
	ld [hl], a
;> if wChannelFlags2[channel] & 1 << BIT_EXECUTE_MUSIC:
;>     return Audio1_note_pitch(channel, kept)
	ld hl, wChannelFlags2
	add hl, bc
	bit BIT_EXECUTE_MUSIC, [hl]
	jr nz, Audio1_note_pitch
;> if not wChannelFlags1[channel] & 1 << BIT_NOISE_OR_SFX:
;>     return Audio1_note_pitch(channel, kept)
	ld hl, wChannelFlags1
	add hl, bc
	bit BIT_NOISE_OR_SFX, [hl]
	jr z, Audio1_note_pitch
;> return                                          # an effect's note sets no pitch here (kept is dropped)
	pop hl
	ret

;@ path: audio/engine_1
;@ def Audio1_note_pitch(channel: c, cmd)
;@ The note's pitch: a rest silences the channel (unless an effect has it); a note gets its frequency from
;@ the pitch table and the channel's octave, starts any pitch slide, and is written to the hardware - but a
;@ music channel stays quiet while an effect plays on it. The command byte is the one note_length left on
;@ the stack.
;@ test: skip starts by popping the command byte Audio1_note_length pushed
Audio1_note_pitch:
;> if cmd & 0xF0 == rest_cmd:
	pop af
	and $f0
	cp rest_cmd
	jr nz, .notRest
;>     if channel < CHAN5:
	ld a, c
	cp CHAN5
	jr nc, .next
; If this isn't an SFX channel, try the corresponding SFX channel.
;>         if wChannelSoundIDs[CHAN5 + channel]:
;>             return                              # an effect has the hardware channel
	ld hl, wChannelSoundIDs + CHAN5
	add hl, bc
	ld a, [hl]
	and a
	jr nz, .done
	; fall through
.next
;>     if channel == CHAN3 or channel == CHAN7:
	ld a, c
	cp CHAN3
	jr z, .channel3
	cp CHAN7
	jr nz, .notChannel3
.channel3
;>         mask = mem[Audio1_HWChannelDisableMasks + channel]
	ld b, 0
	ld hl, Audio1_HWChannelDisableMasks
	add hl, bc
;>         rAUDTERM = rAUDTERM & mask              # the wave channel's output off
	ldh a, [rAUDTERM]
	and [hl]
	ldh [rAUDTERM], a ; disable hardware channel 3's output
	jr .done
.notChannel3
;>     else:
;>         reg = Audio1_GetRegisterPointer(REG_VOLUME_ENVELOPE, channel)
	ld b, REG_VOLUME_ENVELOPE
	call Audio1_GetRegisterPointer
;>         mem[reg] = 8                            # volume 0, rising
	ld a, $8 ; fade in sound
	ld [hli], a
;>         mem[reg + 2] = 0x80                     # restart the channel
	inc hl
	ld a, $80 ; restart sound
	ld [hl], a
.done
;>     return
	ret
.notRest
;> freq = Audio1_CalculateFrequency(cmd >> 4, wChannelOctaves[channel])
	swap a
	ld b, 0
	ld hl, wChannelOctaves
	add hl, bc
	ld b, [hl]
	call Audio1_CalculateFrequency
;> if wChannelFlags1[channel] & 1 << BIT_PITCH_SLIDE_ON:
;>     freq = Audio1_InitPitchSlideVars(channel, freq, 0)
	ld b, 0
	ld hl, wChannelFlags1
	add hl, bc
	bit BIT_PITCH_SLIDE_ON, [hl]
	jr z, .skipPitchSlide
	call Audio1_InitPitchSlideVars
.skipPitchSlide
;> if channel < CHAN5:
	push de
	ld a, c
	cp CHAN5
	jr nc, .sfxChannel ; if sfx channel
; If this isn't an SFX channel, try the corresponding SFX channel.
;>     busy = wChannelSoundIDs[CHAN5 + channel]
	ld hl, wChannelSoundIDs + CHAN5
	ld d, 0
	ld e, a
	add hl, de
	ld a, [hl]
;>     if busy:
	and a
	jr nz, .noSfx
	jr .sfxChannel
.noSfx
;>         return                                  # the music stays quiet under the effect
	pop de
	ret
.sfxChannel
;> volume = wChannelVolumes[channel]
	ld b, 0
	ld hl, wChannelVolumes
	add hl, bc
	ld d, [hl]
;> mem[Audio1_GetRegisterPointer(REG_VOLUME_ENVELOPE, channel)] = volume
	ld b, REG_VOLUME_ENVELOPE
	call Audio1_GetRegisterPointer
	ld [hl], d
;> Audio1_ApplyDutyCycleAndSoundLength(channel)
	call Audio1_ApplyDutyCycleAndSoundLength
;> Audio1_EnableChannelOutput(channel)
	call Audio1_EnableChannelOutput
;> if wChannelFlags1[channel] & 1 << BIT_PERFECT_PITCH:
	pop de
	ld b, $0
	ld hl, wChannelFlags1
	add hl, bc
	bit BIT_PERFECT_PITCH, [hl] ; has toggle_perfect_pitch been used?
	jr z, .skipFrequencyInc
;>     freq = freq & 0xFF00 | (freq + 1) & 0xFF    # the carry into the high byte never happens
	inc e                       ; if yes, increment the frequency by 1
	jr nc, .skipFrequencyInc    ; Likely a mistake, because `inc` does not set flag C.
	                            ; Fortunately this does not seem to affect any notes that actually occur.
	inc d
.skipFrequencyInc
;> wChannelFrequencyLowBytes[channel] = freq & 0xFF
	ld hl, wChannelFrequencyLowBytes
	add hl, bc
	ld [hl], e
;> Audio1_ApplyWavePatternAndFrequency(channel, freq)
	call Audio1_ApplyWavePatternAndFrequency
	ret

;@ path: audio/engine_1
;@ def Audio1_EnableChannelOutput(channel: c)
;@ Turn a channel's output on in rAUDTERM. For the noise effect channel, or a music channel no effect is
;@ covering, only on the sides wStereoPanning allows.
;@ test: channel = rand(0, 7)
Audio1_EnableChannelOutput:
;> value = rAUDTERM | mem[Audio1_HWChannelEnableMasks + channel]   # this channel's bits on
	ld b, 0
	ld hl, Audio1_HWChannelEnableMasks
	add hl, bc
	ldh a, [rAUDTERM]
	or [hl] ; set this channel's bits
	ld d, a
;> pan = channel == CHAN8 or channel < CHAN5
	ld a, c
	cp CHAN8
	jr z, .noiseChannelOrNoSfx
	cp CHAN5
	jr nc, .skip ; if sfx channel
; If this isn't an SFX channel, try the corresponding SFX channel.
;> if channel < CHAN5 and wChannelSoundIDs[CHAN5 + channel]:
;>     pan = False                                 # an effect covers this music channel
	ld hl, wChannelSoundIDs + CHAN5
	add hl, bc
	ld a, [hl]
	and a
	jr nz, .skip
.noiseChannelOrNoSfx
; If this is the SFX noise channel or a music channel whose corresponding
; SFX channel is off, apply stereo panning.
;> if pan:
;>     sides = wStereoPanning & mem[Audio1_HWChannelEnableMasks + channel]
	ld a, [wStereoPanning]
	ld hl, Audio1_HWChannelEnableMasks
	add hl, bc
	and [hl]
	ld d, a
;>     value = rAUDTERM & mem[Audio1_HWChannelDisableMasks + channel] | sides
	ldh a, [rAUDTERM]
	ld hl, Audio1_HWChannelDisableMasks
	add hl, bc
	and [hl] ; reset this channel's output bits
	or d ; set this channel's output bits that enabled in [wStereoPanning]
	ld d, a
.skip
;> rAUDTERM = value
	ld a, d
	ldh [rAUDTERM], a
	ret

;@ path: audio/engine_1
;@ def Audio1_ApplyDutyCycleAndSoundLength(channel: c)
;@ Write a channel's duty/length register: the note's length, plus the duty cycle on the square and
;@ noise channels (the wave channel has no duty).
;@ test: channel = rand(0, 7)
Audio1_ApplyDutyCycleAndSoundLength:
;> value = wChannelNoteDelayCounters[channel]    # the note's length
	ld b, 0
	ld hl, wChannelNoteDelayCounters ; use the note delay as sound length
	add hl, bc
	ld d, [hl]
;> if channel != CHAN3 and channel != CHAN7:
	ld a, c
	cp CHAN3
	jr z, .skipDuty ; if music channel 3
	cp CHAN7
	jr z, .skipDuty ; if sfx channel 3
; include duty cycle (except on channel 3 which doesn't have it)
;>     value = value & 0x3F
	ld a, d
	and $3f
	ld d, a
;>     value = value | wChannelDutyCycles[channel]
	ld hl, wChannelDutyCycles
	add hl, bc
	ld a, [hl]
	or d
	ld d, a
.skipDuty
;> mem[Audio1_GetRegisterPointer(REG_DUTY_SOUND_LEN, channel)] = value
	ld b, REG_DUTY_SOUND_LEN
	call Audio1_GetRegisterPointer
	ld [hl], d
	ret

;@ path: audio/engine_1
;@ def Audio1_ApplyWavePatternAndFrequency(channel: c, freq: de)
;@ Start a note on a channel: on the wave channel first load its instrument's 32 samples into wave RAM
;@ (with the channel stopped), then write the frequency with the counter-mode flag.
;@ test: channel = rand(0, 7)
Audio1_ApplyWavePatternAndFrequency:
;> if channel == CHAN3 or channel == CHAN7:     # the wave channel
	ld a, c
	cp CHAN3
	jr z, .channel3
	cp CHAN7
	jr nz, .notChannel3
	; fall through
.channel3
;>     instrument = wMusicWaveInstrument if channel == CHAN3 else wSfxWaveInstrument
	push de
	ld de, wMusicWaveInstrument
	cp CHAN3
	jr z, .next
	ld de, wSfxWaveInstrument
.next
;>     i = 2 * instrument & 0xFF
	ld a, [de]
	add a
	ld d, 0
	ld e, a
;>     src = mem16[Audio1_WavePointers + i]       # its 32 samples
	ld hl, Audio1_WavePointers
	add hl, de
	ld e, [hl]
	inc hl
	ld d, [hl]
;=@wave
	ld hl, _AUD3WAVERAM
	ld b, AUD3WAVE_SIZE - 1
;>     rAUD3ENA = 0                               # stopped while its wave RAM is written
	ld a, $0 ; stop hardware channel 3
	ldh [rAUD3ENA], a
.loop
;>@wave     for i in range(AUD3WAVE_SIZE):
;>         mem[_AUD3WAVERAM + i] = mem[src + i]
	ld a, [de]
	inc de
	ld [hli], a
;=@wave
	ld a, b
	dec b
	and a
	jr nz, .loop
;>     rAUD3ENA = AUD3ENA_ON
	ld a, AUD3ENA_ON ; start hardware channel 3
	ldh [rAUD3ENA], a
	pop de
.notChannel3
;> hi = (freq >> 8 | 0x80) & 0xC7
	ld a, d
	or $80 ; use counter mode (i.e. disable output when the counter reaches 0)
	and $c7 ; zero the unused bits in the register
	ld d, a
;> reg = Audio1_GetRegisterPointer(REG_FREQUENCY_LO, channel)
	ld b, REG_FREQUENCY_LO
	call Audio1_GetRegisterPointer
;> mem[reg] = freq & 0xFF
	ld [hl], e ; store frequency low byte
;> mem[reg + 1] = hi
	inc hl
	ld [hl], d ; store frequency high byte
;> Audio1_ApplyFrequencyModifier(reg + 1, hi << 8 | freq & 0xFF)
	call Audio1_ApplyFrequencyModifier
	ret

;@ path: audio/engine_1
;@ def Audio1_SetSfxTempo()
;@ Sound effects normally run at tempo $100; a cry runs at $80 plus its tempo modifier.
Audio1_SetSfxTempo:
;> if Audio1_IsCry():
	call Audio1_IsCry
	jr nc, .notCry
;>     tempo = wTempoModifier + 0x80
	ld d, 0
	ld a, [wTempoModifier]
	add $80
	jr nc, .next
	inc d
.next
;>     wSfxTempo[1] = tempo & 0xFF
	ld [wSfxTempo + 1], a
;>     wSfxTempo[0] = tempo >> 8
	ld a, d
	ld [wSfxTempo], a
	jr .done
.notCry
;> else:
;>     wSfxTempo[1] = 0                           # tempo $100
	xor a
	ld [wSfxTempo + 1], a
;>     wSfxTempo[0] = 1
	ld a, $1
	ld [wSfxTempo], a
.done
	ret

;@ path: audio/engine_1
;@ def Audio1_ApplyFrequencyModifier(reg: hl, freq: de)
;@ While a cry plays, raise the frequency just written to the register pair ending at `reg` by the cry's
;@ pitch modifier.
;@ test: reg = rand(0xC001, 0xDF00)
Audio1_ApplyFrequencyModifier:
;> if Audio1_IsCry():
	call Audio1_IsCry
	jr nc, .done
; if playing a cry, add the cry's frequency modifier
;>     freq = (freq + wFrequencyModifier) & 0xFFFF
	ld a, [wFrequencyModifier]
	add e
	jr nc, .noCarry
	inc d
.noCarry
;>     mem[reg - 1] = freq & 0xFF
	dec hl
	ld e, a
	ld [hl], e
;>     mem[reg] = freq >> 8
	inc hl
	ld [hl], d
.done
	ret

;@ path: audio/engine_1
;@ def Audio1_GoBackOneCommandIfCry(channel: c) -> carry
;@ For a cry, step the channel's data pointer back one byte (so the byte is read again) and return carry.
;@ test: channel = rand(0, 7)
Audio1_GoBackOneCommandIfCry:
;> if not Audio1_IsCry():
;>     return False
	call Audio1_IsCry
	jr nc, .done
;> p = addr(wChannelCommandPointers) + 2 * channel
	ld hl, wChannelCommandPointers
	ld e, c
	ld d, 0
	sla e
	rl d
	add hl, de
;> borrow = mem[p] == 0
;> mem[p] = (mem[p] - 1) & 0xFF                  # one byte back
	ld a, [hl]
	sub 1
	ld [hl], a
;> mem[p + 1] = (mem[p + 1] - borrow) & 0xFF
	inc hl
	ld a, [hl]
	sbc 0
	ld [hl], a
;> return True
	scf
	ret
.done
	scf
	ccf
	ret

;@ path: audio/engine_1
;@ def Audio1_IsCry() -> carry
;@ Whether the sound effect on channel 5 is a Pokemon cry.
Audio1_IsCry:
; Returns whether the currently playing audio is a cry in carry.
;> sound = wChannelSoundIDs[CHAN5]
	ld a, [wChannelSoundIDs + CHAN5]
;> if sound < (SFX_Cry00_1 - SFX_Headers_1) // 3:
;>     return False
	cp CRY_SFX_START
	jr nc, .next
	jr .no
.next
;> return sound < ((SFX_Cry25_1 - SFX_Headers_1) // 3 + 3)                     # the answer goes back in the carry flag
	cp CRY_SFX_END
	jr z, .no
	jr c, .yes
.no
;> # .no: carry clear
	scf
	ccf
	ret
.yes
;> # .yes: carry set
	scf
	ret

;@ path: audio/engine_1
;@ def Audio1_ApplyPitchSlide(channel: c, zero: b)
;@ One frame of a pitch slide: move the frequency a step (plus the fractional step) towards the target, and
;@ stop the slide once it would pass it. b is 0 on entry.
;@ test: channel = rand(0, 7); zero = 0
Audio1_ApplyPitchSlide:
;> if not wChannelFlags1[channel] & 1 << BIT_PITCH_SLIDE_DECREASING:
	ld hl, wChannelFlags1
	add hl, bc
	bit BIT_PITCH_SLIDE_DECREASING, [hl]
	jp nz, .frequencyDecreasing
; frequency increasing
;>     cur_lo = wChannelPitchSlideCurrentFrequencyLowBytes[channel]
	ld hl, wChannelPitchSlideCurrentFrequencyLowBytes
	add hl, bc
	ld e, [hl]
;>     cur = wChannelPitchSlideCurrentFrequencyHighBytes[channel] << 8 | cur_lo
	ld hl, wChannelPitchSlideCurrentFrequencyHighBytes
	add hl, bc
	ld d, [hl]
;>     step = wChannelPitchSlideFrequencySteps[channel]
	ld hl, wChannelPitchSlideFrequencySteps
	add hl, bc
	ld l, [hl]
	ld h, b
;>     new = (cur + step) & 0xFFFF
	add hl, de
	ld d, h
	ld e, l
;>     step_frac = wChannelPitchSlideFrequencyStepsFractionalPart[channel]
	ld hl, wChannelPitchSlideCurrentFrequencyFractionalPart
	add hl, bc
	push hl
	ld hl, wChannelPitchSlideFrequencyStepsFractionalPart
	add hl, bc
	ld a, [hl]
;>     frac = wChannelPitchSlideCurrentFrequencyFractionalPart[channel] + step_frac
	pop hl
	add [hl]
;>     wChannelPitchSlideCurrentFrequencyFractionalPart[channel] = frac & 0xFF
	ld [hl], a
;>     new = (new + (frac >> 8)) & 0xFFFF         # plus the fraction's carry
	ld a, 0
	adc e
	ld e, a
	ld a, 0
	adc d
	ld d, a
;>     target_hi = wChannelPitchSlideTargetFrequencyHighBytes[channel]
	ld hl, wChannelPitchSlideTargetFrequencyHighBytes
	add hl, bc
	ld a, [hl]
;>     reached = new >> 8 > target_hi
	cp d
	jp c, .reachedTargetFrequency
;>     if new >> 8 == target_hi:
	jr nz, .applyUpdatedFrequency
;>         reached = new & 0xFF > wChannelPitchSlideTargetFrequencyLowBytes[channel]
	ld hl, wChannelPitchSlideTargetFrequencyLowBytes
	add hl, bc
	ld a, [hl]
	cp e
	jp c, .reachedTargetFrequency
	jr .applyUpdatedFrequency
.frequencyDecreasing
;> else:
;>     cur_lo = wChannelPitchSlideCurrentFrequencyLowBytes[channel]
	ld hl, wChannelPitchSlideCurrentFrequencyLowBytes
	add hl, bc
	ld a, [hl]
;>     cur = wChannelPitchSlideCurrentFrequencyHighBytes[channel] << 8 | cur_lo
	ld hl, wChannelPitchSlideCurrentFrequencyHighBytes
	add hl, bc
	ld d, [hl]
;>     step = wChannelPitchSlideFrequencySteps[channel]
	ld hl, wChannelPitchSlideFrequencySteps
	add hl, bc
	ld e, [hl]
;>     new = (cur - step) & 0xFFFF
	sub e
	ld e, a
	ld a, d
	sbc b
	ld d, a
;>     frac = wChannelPitchSlideFrequencyStepsFractionalPart[channel] * 2   # the fractional step doubles each frame
;>     wChannelPitchSlideFrequencyStepsFractionalPart[channel] = frac & 0xFF
	ld hl, wChannelPitchSlideFrequencyStepsFractionalPart
	add hl, bc
	ld a, [hl]
	add a
	ld [hl], a
;>     new = (new - (frac >> 8)) & 0xFFFF         # minus its carry
	ld a, e
	sbc b
	ld e, a
	ld a, d
	sbc b
	ld d, a
;>     target_hi = wChannelPitchSlideTargetFrequencyHighBytes[channel]
	ld hl, wChannelPitchSlideTargetFrequencyHighBytes
	add hl, bc
;>     reached = new >> 8 < target_hi
	ld a, d
	cp [hl]
	jr c, .reachedTargetFrequency
;>     if new >> 8 == target_hi:
	jr nz, .applyUpdatedFrequency
;>         reached = new & 0xFF < wChannelPitchSlideTargetFrequencyLowBytes[channel]
	ld hl, wChannelPitchSlideTargetFrequencyLowBytes
	add hl, bc
	ld a, e
	cp [hl]
	jr c, .reachedTargetFrequency
.applyUpdatedFrequency
;> if reached:                                     # the slide ends at its target
;>@stop     wChannelFlags1[channel] = wChannelFlags1[channel] & ~(1 << BIT_PITCH_SLIDE_ON | 1 << BIT_PITCH_SLIDE_DECREASING) & 0xFF
;>@ret     return
;> wChannelPitchSlideCurrentFrequencyLowBytes[channel] = new & 0xFF
	ld hl, wChannelPitchSlideCurrentFrequencyLowBytes
	add hl, bc
	ld [hl], e
;> wChannelPitchSlideCurrentFrequencyHighBytes[channel] = new >> 8
	ld hl, wChannelPitchSlideCurrentFrequencyHighBytes
	add hl, bc
	ld [hl], d
;> reg = Audio1_GetRegisterPointer(REG_FREQUENCY_LO, channel)
	ld b, REG_FREQUENCY_LO
	call Audio1_GetRegisterPointer
;> mem[reg] = new & 0xFF
	ld a, e
	ld [hli], a
;> mem[reg + 1] = new >> 8
	ld [hl], d
	ret
.reachedTargetFrequency
; Turn off pitch slide when the target frequency has been reached.
;=@stop
	ld hl, wChannelFlags1
	add hl, bc
	res BIT_PITCH_SLIDE_ON, [hl]
	res BIT_PITCH_SLIDE_DECREASING, [hl]
;=@ret
	ret

;@ path: audio/engine_1
;@ def Audio1_InitPitchSlideVars(channel: c, freq: de, zero: b) -> de
;@ Set up a pitch slide from freq to the target: the slide lasts the note's length minus the length
;@ modifier (at least 1 frame); the distance divided by that length gives the step per frame and a
;@ fractional step. Returns (steps + 1, remainder - length) in de. b is 0 on entry.
;@ test: channel = rand(0, 7); zero = 0
;@ test: mod = rand(0, 100); mem[wChannelPitchSlideLengthModifiers + channel] = mod; mem[wChannelNoteDelayCounters + channel] = mod + rand(16, 155)
Audio1_InitPitchSlideVars:
;> wChannelPitchSlideCurrentFrequencyHighBytes[channel] = freq >> 8
	ld hl, wChannelPitchSlideCurrentFrequencyHighBytes
	add hl, bc
	ld [hl], d
;> wChannelPitchSlideCurrentFrequencyLowBytes[channel] = freq & 0xFF
	ld hl, wChannelPitchSlideCurrentFrequencyLowBytes
	add hl, bc
	ld [hl], e
;> length = wChannelNoteDelayCounters[channel] - wChannelPitchSlideLengthModifiers[channel]
	ld hl, wChannelNoteDelayCounters
	add hl, bc
	ld a, [hl]
	ld hl, wChannelPitchSlideLengthModifiers
	add hl, bc
	sub [hl]
;> if length < 0:                                 # at least one frame
;>     length = 1
	jr nc, .next
	ld a, 1
.next
;> wChannelPitchSlideLengthModifiers[channel] = length   # from now on it holds the slide's length
	ld [hl], a
;> lo = (freq & 0xFF) - wChannelPitchSlideTargetFrequencyLowBytes[channel]
	ld hl, wChannelPitchSlideTargetFrequencyLowBytes
	add hl, bc
	ld a, e
	sub [hl]
	ld e, a
;> hi = ((freq >> 8) - (lo < 0)) & 0xFF
	ld a, d
	sbc b
;> if hi >= wChannelPitchSlideTargetFrequencyHighBytes[channel]:   # sliding down: current - target
	ld hl, wChannelPitchSlideTargetFrequencyHighBytes
	add hl, bc
	sub [hl]
	jr c, .targetFrequencyGreater
;>     diff = (hi - wChannelPitchSlideTargetFrequencyHighBytes[channel]) << 8 | lo & 0xFF
	ld d, a
;>     wChannelFlags1[channel] = wChannelFlags1[channel] | 1 << BIT_PITCH_SLIDE_DECREASING
	ld b, 0
	ld hl, wChannelFlags1
	add hl, bc
	set BIT_PITCH_SLIDE_DECREASING, [hl]
	jr .next2
.targetFrequencyGreater
; If the target frequency is greater, subtract the current frequency from
; the target frequency to get the absolute difference.
;> else:                                          # sliding up: target - current
;>     cur_hi = wChannelPitchSlideCurrentFrequencyHighBytes[channel]
	ld hl, wChannelPitchSlideCurrentFrequencyHighBytes
	add hl, bc
	ld d, [hl]
;>     cur_lo = wChannelPitchSlideCurrentFrequencyLowBytes[channel]
	ld hl, wChannelPitchSlideCurrentFrequencyLowBytes
	add hl, bc
	ld e, [hl]
;>     lo = wChannelPitchSlideTargetFrequencyLowBytes[channel] - cur_lo
	ld hl, wChannelPitchSlideTargetFrequencyLowBytes
	add hl, bc
	ld a, [hl]
	sub e
	ld e, a

; Bug. Instead of borrowing from the high byte of the target frequency as it
; should, it borrows from the high byte of the current frequency instead.
; This means that the result will be 0x200 greater than it should be if the
; low byte of the current frequency is greater than the low byte of the
; target frequency.
;>     hi = (cur_hi - (lo < 0)) & 0xFF
	ld a, d
	sbc b
	ld d, a

;>     diff = (wChannelPitchSlideTargetFrequencyHighBytes[channel] - hi) % 256 << 8 | lo & 0xFF
	ld hl, wChannelPitchSlideTargetFrequencyHighBytes
	add hl, bc
	ld a, [hl]
	sub d
	ld d, a
;>     wChannelFlags1[channel] = wChannelFlags1[channel] & ~(1 << BIT_PITCH_SLIDE_DECREASING) & 0xFF
	ld b, 0
	ld hl, wChannelFlags1
	add hl, bc
	res BIT_PITCH_SLIDE_DECREASING, [hl]

.next2
;> count = 0                                      # diff / length, by subtracting the length until it borrows
	ld hl, wChannelPitchSlideLengthModifiers
	add hl, bc
.divideLoop
;>@dv while True:
;>     count += 1
	inc b
;>     borrow = (diff & 0xFF) < length
;>     diff = diff & 0xFF00 | (diff - length) & 0xFF
	ld a, e
	sub [hl]
	ld e, a
;>     if not borrow:
;>         continue
	jr nc, .divideLoop
;>     if diff >> 8 == 0:
;>         break
	ld a, d
	and a
	jr z, .doneDividing
;>     diff -= 0x100                              # the borrow from the high byte
	dec a
	ld d, a
;=@dv
	jr .divideLoop
.doneDividing
;> rest = (diff + length) & 0xFF                  # the remainder
	ld a, e ; a = remainder - dividend
	add [hl]
;> wChannelPitchSlideFrequencySteps[channel] = count       # the quotient + 1
	ld d, b ; d = quotient + 1
	ld b, 0
	ld hl, wChannelPitchSlideFrequencySteps
	add hl, bc
	ld [hl], d ; store quotient + 1
;> wChannelPitchSlideFrequencyStepsFractionalPart[channel] = rest
	ld hl, wChannelPitchSlideFrequencyStepsFractionalPart
	add hl, bc
	ld [hl], a ; store remainder - dividend
;> wChannelPitchSlideCurrentFrequencyFractionalPart[channel] = rest
	ld hl, wChannelPitchSlideCurrentFrequencyFractionalPart
	add hl, bc
	ld [hl], a ; store remainder - dividend
;> return count << 8 | diff & 0xFF
	ret

;@ path: audio/engine_1
;@ def Audio1_ApplyDutyCyclePattern(channel: c)
;@ Step a channel's duty cycle pattern: four 2-bit duty values that rotate each frame, the top one going
;@ into the channel's duty register.
;@ test: channel = rand(0, 7)
Audio1_ApplyDutyCyclePattern:
;> p = wChannelDutyCyclePatterns[channel]
	ld b, 0
	ld hl, wChannelDutyCyclePatterns
	add hl, bc
	ld a, [hl]
;> p = (p << 2 | p >> 6) & 0xFF                   # rotate the next duty to the top
	rlca
	rlca
;> wChannelDutyCyclePatterns[channel] = p
	ld [hl], a
;> duty = p & 0xC0
	and $c0
	ld d, a
;> reg = Audio1_GetRegisterPointer(REG_DUTY_SOUND_LEN, channel)
	ld b, REG_DUTY_SOUND_LEN
	call Audio1_GetRegisterPointer
;> mem[reg] = mem[reg] & 0x3F | duty             # the duty is the register's top two bits
	ld a, [hl]
	and $3f
	or d
	ld [hl], a
	ret

;@ path: audio/engine_1
;@ def Audio1_GetNextMusicByte(channel: c) -> a
;@ Read the next byte of a channel's sound data and move its pointer on.
;@ test: channel = rand(0, 7)
Audio1_GetNextMusicByte:
;> i = 2 * channel & 0xFF
	ld d, 0
	ld a, c
	add a
	ld e, a
;> ptr = wChannelCommandPointers[i] | wChannelCommandPointers[i + 1] << 8
	ld hl, wChannelCommandPointers
	add hl, de
	ld a, [hli]
	ld e, a
	ld a, [hld]
	ld d, a
;> byte = mem[ptr]
	ld a, [de] ; get next music command
;> ptr = (ptr + 1) & 0xFFFF
	inc de
;> wChannelCommandPointers[i] = ptr & 0xFF
	ld [hl], e ; store address of next command
;> wChannelCommandPointers[i + 1] = ptr >> 8
	inc hl
	ld [hl], d
;> return byte
	ret

;@ path: audio/engine_1
;@ def Audio1_GetRegisterPointer(reg: b, channel: c) -> hl
;@ Address of sound register `reg` (0-4) of the hardware channel behind software channel `channel`.
Audio1_GetRegisterPointer:
; hl = address of hardware sound register b for software channel c
;> p = Audio1_HWChannelBaseAddresses + channel
	ld a, c
	ld hl, Audio1_HWChannelBaseAddresses
	add l
	jr nc, .noCarry
	inc h
.noCarry
	ld l, a
;> base = mem[p]                                 # low byte of the channel's first register
	ld a, [hl]
;> return 0xFF00 | (base + reg) & 0xFF
	add b
	ld l, a
	ld h, $ff
	ret

;@ path: audio/engine_1
;@ def Audio1_MultiplyAdd(n: a, step: de, base: l) -> hl
;@ base + n * step, by shifting and adding.
Audio1_MultiplyAdd:
; hl = l + (a * de)
;> result = base
	ld h, 0
.loop
;>@lp while True:
;>     low_bit, n = n & 1, n >> 1
	srl a
;>     if low_bit:
;>         result = (result + step) & 0xFFFF
	jr nc, .skipAdd
	add hl, de
.skipAdd
;>     step = (step << 1) & 0xFFFF
	sla e
	rl d
;>     if not n:
;>         break
	and a
	jr z, .done
;=@lp
	jr .loop
.done
;> return result
	ret

;@ path: audio/engine_1
;@ def Audio1_CalculateFrequency(note: a, octave: b) -> de
;@ The frequency register value for a note (0 = C ... 11 = B) in an octave: the pitch table holds octave 7;
;@ each octave below halves it. The top bits get the "restart" flag the register needs.
;@ test: note = rand(0, 11); octave = rand(0, 7)
Audio1_CalculateFrequency:
; return the frequency for note a, octave b in de
;> i = 2 * note                                   # 2 bytes per pitch
	ld h, 0
	ld l, a
	add hl, hl
	ld d, h
	ld e, l
;> freq = mem[Audio1_Pitches + i] | mem[Audio1_Pitches + i + 1] << 8
	ld hl, Audio1_Pitches
	add hl, de
	ld e, [hl]
	inc hl
	ld d, [hl]
;> o = octave
	ld a, b
.loop
;>@lp while o != 7:                               # each octave below 7 halves it
	cp 7
	jr z, .done
;>     freq = freq >> 1 | freq & 0x8000            # arithmetic shift: the table values are negative
	sra d
	rr e
;>     o = (o + 1) & 0xFF
	inc a
;=@lp
	jr .loop
.done
;> return (freq + 0x800) & 0xFFFF
	ld a, 8
	add d
	ld d, a
	ret

;@ path: audio/engine_1
;@ def Audio1_PlaySound(sound: a)
;@ Start a sound from this audio bank: $FF stops everything, IDs up to the last effect and $FF are effects,
;@ the rest (and $FE) are songs. A song resets the four music channels; an effect takes over only the
;@ channels it uses, unless a more important effect (lower ID) is playing there - noise instruments, the
;@ drums, never interrupt a real effect on the noise channel. Then each channel gets its start address
;@ from the sound's header (3 bytes per channel). A cry also claims all four effect channels and saves the
;@ volume.
Audio1_PlaySound::
;> wSoundID = sound
	ld [wSoundID], a
;> noise_end = (SFX_Noise_Instrument19_1 - SFX_Headers_1) // 3 + 1   # sound IDs count 3-byte headers
;> stop = sound == SFX_STOP_ALL_MUSIC
	cp SFX_STOP_ALL_MUSIC
	jp z, .stopAllAudio
;> last_sfx = (SFX_Safari_Zone_PA - SFX_Headers_1) // 3
;> music = last_sfx < sound <= 0xFE                # the rest are sound effects
	cp MAX_SFX_ID_1
	jp z, .playSfx
	jp c, .playSfx
	cp $fe
	jr z, .playMusic
	jp nc, .playSfx

.playMusic
;> if music:
;>     wUnusedMusicByte = 0
	xor a
	ld [wUnusedMusicByte], a
;>     wDisableChannelOutputWhenSfxEnds = 0
	ld [wDisableChannelOutputWhenSfxEnds], a
;>     wMusicTempo[1] = 0
	ld [wMusicTempo + 1], a
;>     wMusicWaveInstrument = 0
	ld [wMusicWaveInstrument], a
;>     wSfxWaveInstrument = 0
	ld [wSfxWaveInstrument], a
;>     fill(wChannelReturnAddresses, 0, NUM_CHANNELS)      # 8 bytes: the four music channels' pointers
	ld d, NUM_CHANNELS
	ld hl, wChannelReturnAddresses
	call .FillMem
;>     fill(wChannelCommandPointers, 0, NUM_CHANNELS)
	ld hl, wChannelCommandPointers
	call .FillMem
;>     fill(wChannelSoundIDs, 0, NUM_MUSIC_CHANS)          # and every per-channel variable
	ld d, NUM_MUSIC_CHANS
	ld hl, wChannelSoundIDs
	call .FillMem
;>     fill(wChannelFlags1, 0, NUM_MUSIC_CHANS)
;>     fill(wChannelDutyCycles, 0, NUM_MUSIC_CHANS)
	ld hl, wChannelFlags1
	call .FillMem
	ld hl, wChannelDutyCycles
	call .FillMem
;>     fill(wChannelDutyCyclePatterns, 0, NUM_MUSIC_CHANS)
;>     fill(wChannelVibratoDelayCounters, 0, NUM_MUSIC_CHANS)
	ld hl, wChannelDutyCyclePatterns
	call .FillMem
	ld hl, wChannelVibratoDelayCounters
	call .FillMem
;>     fill(wChannelVibratoExtents, 0, NUM_MUSIC_CHANS)
;>     fill(wChannelVibratoRates, 0, NUM_MUSIC_CHANS)
	ld hl, wChannelVibratoExtents
	call .FillMem
	ld hl, wChannelVibratoRates
	call .FillMem
;>     fill(wChannelFrequencyLowBytes, 0, NUM_MUSIC_CHANS)
;>     fill(wChannelVibratoDelayCounterReloadValues, 0, NUM_MUSIC_CHANS)
	ld hl, wChannelFrequencyLowBytes
	call .FillMem
	ld hl, wChannelVibratoDelayCounterReloadValues
	call .FillMem
;>     fill(wChannelFlags2, 0, NUM_MUSIC_CHANS)
;>     fill(wChannelPitchSlideLengthModifiers, 0, NUM_MUSIC_CHANS)
	ld hl, wChannelFlags2
	call .FillMem
	ld hl, wChannelPitchSlideLengthModifiers
	call .FillMem
;>     fill(wChannelPitchSlideFrequencySteps, 0, NUM_MUSIC_CHANS)
;>     fill(wChannelPitchSlideFrequencyStepsFractionalPart, 0, NUM_MUSIC_CHANS)
	ld hl, wChannelPitchSlideFrequencySteps
	call .FillMem
	ld hl, wChannelPitchSlideFrequencyStepsFractionalPart
	call .FillMem
;>     fill(wChannelPitchSlideCurrentFrequencyFractionalPart, 0, NUM_MUSIC_CHANS)
;>     fill(wChannelPitchSlideCurrentFrequencyHighBytes, 0, NUM_MUSIC_CHANS)
	ld hl, wChannelPitchSlideCurrentFrequencyFractionalPart
	call .FillMem
	ld hl, wChannelPitchSlideCurrentFrequencyHighBytes
	call .FillMem
;>     fill(wChannelPitchSlideCurrentFrequencyLowBytes, 0, NUM_MUSIC_CHANS)
;>     fill(wChannelPitchSlideTargetFrequencyHighBytes, 0, NUM_MUSIC_CHANS)
	ld hl, wChannelPitchSlideCurrentFrequencyLowBytes
	call .FillMem
	ld hl, wChannelPitchSlideTargetFrequencyHighBytes
	call .FillMem
;>     fill(wChannelPitchSlideTargetFrequencyLowBytes, 0, NUM_MUSIC_CHANS)
	ld hl, wChannelPitchSlideTargetFrequencyLowBytes
	call .FillMem
;>     fill(wChannelLoopCounters, 1, NUM_MUSIC_CHANS)      # these start at 1
	ld a, $1
	ld hl, wChannelLoopCounters
	call .FillMem
;>     fill(wChannelNoteDelayCounters, 1, NUM_MUSIC_CHANS)
;>     fill(wChannelNoteSpeeds, 1, NUM_MUSIC_CHANS)
	ld hl, wChannelNoteDelayCounters
	call .FillMem
	ld hl, wChannelNoteSpeeds
	call .FillMem
;>     wMusicTempo[0] = 1
;>     wStereoPanning = 0xFF                       # both sides
	ld [wMusicTempo], a
	ld a, $ff
	ld [wStereoPanning], a
;>     rAUDVOL = 0
	xor a
	ldh [rAUDVOL], a
;>     rAUD1SWEEP = AUD1SWEEP_DOWN                 # sweep off
	ld a, AUD1SWEEP_DOWN
	ldh [rAUD1SWEEP], a
;>     rAUDTERM = 0
	ld a, 0
	ldh [rAUDTERM], a
;>     rAUD3ENA = 0                                # restart the wave channel
;>     rAUD3ENA = AUD3ENA_ON
	xor a
	ldh [rAUD3ENA], a
	ld a, AUD3ENA_ON
	ldh [rAUD3ENA], a
;>     rAUDVOL = 0x77                              # full volume
	ld a, $77
	ldh [rAUDVOL], a
	jp .playSoundCommon

.playSfx
;> elif not stop:
;>     i = 3 * sound
	ld l, a
	ld e, a
	ld h, 0
	ld d, h
	add hl, hl
	add hl, de
;>     header = (SFX_Headers_1 + i) & 0xFFFF
	ld de, SFX_Headers_1
	add hl, de
;>     wSfxHeaderPointer[0] = header >> 8
;>     wSfxHeaderPointer[1] = header & 0xFF
	ld a, h
	ld [wSfxHeaderPointer], a
	ld a, l
	ld [wSfxHeaderPointer + 1], a
;>     last = mem[header] >> 6                     # the effect's number of channels - 1
	ld a, [hl]
	and $c0
	rlca
	rlca
	ld c, a
.sfxChannelLoop
;>@loop     for k in range(last, -1, -1):          # its channels, last first
;>         i = 3 * k
	ld d, c
	ld a, c
	add a
	add c
	ld c, a
	ld b, 0
;>         entry = header + i                      # (the header address comes back from wSfxHeaderPointer)
	ld a, [wSfxHeaderPointer]
	ld h, a
	ld a, [wSfxHeaderPointer + 1]
	ld l, a
	add hl, bc
	ld c, d
;>         ch = mem[entry] & 0xF                   # the software channel
	ld a, [hl]
	and $f
	ld e, a ; software channel ID
;>         playing = wChannelSoundIDs[ch]
;>         if playing:                             # the channel is busy
	ld d, 0
	ld hl, wChannelSoundIDs
	add hl, de
	ld a, [hl]
	and a
	jr z, .playChannel
;>             if ch == CHAN8:
	ld a, e
	cp CHAN8
	jr nz, .notNoiseChannel
;>                 if wSoundID < noise_end:
;>                     return                      # a drum never interrupts an effect on the noise channel
	ld a, [wSoundID]
	cp NOISE_INSTRUMENTS_END
	jr nc, .notNoiseInstrument
	ret
.notNoiseInstrument
;>                 replace = playing <= noise_end  # while a drum may always be replaced
	ld a, [hl]
	cp NOISE_INSTRUMENTS_END
	jr z, .playChannel
	jr c, .playChannel
.notNoiseChannel
;>             if not (ch == CHAN8 and replace) and wSoundID > playing:
;>                 return                          # a more important effect (lower ID) plays there
	ld a, [wSoundID]
	cp [hl]
	jr z, .playChannel
	jr c, .playChannel
	ret
.playChannel
;>         # (a = 0 for the clearing below)
	xor a
;>         j = 2 * ch                              # the pointer tables have 2 bytes per channel
	push de
	ld h, d
	ld l, e
	add hl, hl
	ld d, h
	ld e, l
;>         wChannelReturnAddresses[j] = 0
;>         wChannelReturnAddresses[j + 1] = 0
	ld hl, wChannelReturnAddresses
	add hl, de
	ld [hli], a
	ld [hl], a
;>         wChannelCommandPointers[j] = 0
;>         wChannelCommandPointers[j + 1] = 0
	ld hl, wChannelCommandPointers
	add hl, de
	ld [hli], a
	ld [hl], a
	pop de
;>         wChannelSoundIDs[ch] = 0
;>         wChannelFlags1[ch] = 0
	ld hl, wChannelSoundIDs
	add hl, de
	ld [hl], a
	ld hl, wChannelFlags1
	add hl, de
	ld [hl], a
;>         wChannelDutyCycles[ch] = 0
;>         wChannelDutyCyclePatterns[ch] = 0
	ld hl, wChannelDutyCycles
	add hl, de
	ld [hl], a
	ld hl, wChannelDutyCyclePatterns
	add hl, de
	ld [hl], a
;>         wChannelVibratoDelayCounters[ch] = 0
;>         wChannelVibratoExtents[ch] = 0
	ld hl, wChannelVibratoDelayCounters
	add hl, de
	ld [hl], a
	ld hl, wChannelVibratoExtents
	add hl, de
	ld [hl], a
;>         wChannelVibratoRates[ch] = 0
;>         wChannelFrequencyLowBytes[ch] = 0
	ld hl, wChannelVibratoRates
	add hl, de
	ld [hl], a
	ld hl, wChannelFrequencyLowBytes
	add hl, de
	ld [hl], a
;>         wChannelVibratoDelayCounterReloadValues[ch] = 0
;>         wChannelPitchSlideLengthModifiers[ch] = 0
	ld hl, wChannelVibratoDelayCounterReloadValues
	add hl, de
	ld [hl], a
	ld hl, wChannelPitchSlideLengthModifiers
	add hl, de
	ld [hl], a
;>         wChannelPitchSlideFrequencySteps[ch] = 0
;>         wChannelPitchSlideFrequencyStepsFractionalPart[ch] = 0
	ld hl, wChannelPitchSlideFrequencySteps
	add hl, de
	ld [hl], a
	ld hl, wChannelPitchSlideFrequencyStepsFractionalPart
	add hl, de
	ld [hl], a
;>         wChannelPitchSlideCurrentFrequencyFractionalPart[ch] = 0
;>         wChannelPitchSlideCurrentFrequencyHighBytes[ch] = 0
	ld hl, wChannelPitchSlideCurrentFrequencyFractionalPart
	add hl, de
	ld [hl], a
	ld hl, wChannelPitchSlideCurrentFrequencyHighBytes
	add hl, de
	ld [hl], a
;>         wChannelPitchSlideCurrentFrequencyLowBytes[ch] = 0
;>         wChannelPitchSlideTargetFrequencyHighBytes[ch] = 0
	ld hl, wChannelPitchSlideCurrentFrequencyLowBytes
	add hl, de
	ld [hl], a
	ld hl, wChannelPitchSlideTargetFrequencyHighBytes
	add hl, de
	ld [hl], a
;>         wChannelPitchSlideTargetFrequencyLowBytes[ch] = 0
;>         wChannelFlags2[ch] = 0
	ld hl, wChannelPitchSlideTargetFrequencyLowBytes
	add hl, de
	ld [hl], a
	ld hl, wChannelFlags2
	add hl, de
	ld [hl], a
;>         wChannelLoopCounters[ch] = 1
	ld a, $1
	ld hl, wChannelLoopCounters
	add hl, de
	ld [hl], a
;>         wChannelNoteDelayCounters[ch] = 1
;>         wChannelNoteSpeeds[ch] = 1
	ld hl, wChannelNoteDelayCounters
	add hl, de
	ld [hl], a
	ld hl, wChannelNoteSpeeds
	add hl, de
	ld [hl], a
;>         if ch == CHAN5:
;>             rAUD1SWEEP = AUD1SWEEP_DOWN         # sweep off
	ld a, e
	cp CHAN5
	jr nz, .skipSweepDisable
	ld a, AUD1SWEEP_DOWN
	ldh [rAUD1SWEEP], a ; sweep off
.skipSweepDisable
;=@loop
	ld a, c
	and a
	jp z, .playSoundCommon
	dec c
	jp .sfxChannelLoop

.stopAllAudio
;> else:                                           # stop everything
;>     rAUDENA = AUDENA_ON
	ld a, AUDENA_ON
	ldh [rAUDENA], a ; sound hardware on
;>     rAUD3ENA = AUDENA_ON
	ldh [rAUD3ENA], a ; wave playback on
;>     rAUDTERM = 0
	xor a
	ldh [rAUDTERM], a ; no sound output
;>     rAUD3LEVEL = 0
	ldh [rAUD3LEVEL], a ; mute channel 3 (wave channel)
;>     rAUD1SWEEP = AUD1SWEEP_DOWN
	ld a, AUD1SWEEP_DOWN
	ldh [rAUD1SWEEP], a ; sweep off
;>     rAUD1ENV = AUD1SWEEP_DOWN                   # (the same value: volume 0)
	ldh [rAUD1ENV], a ; mute channel 1 (pulse channel 1)
;>     rAUD2ENV = AUD1SWEEP_DOWN
	ldh [rAUD2ENV], a ; mute channel 2 (pulse channel 2)
;>     rAUD4ENV = AUD1SWEEP_DOWN
	ldh [rAUD4ENV], a ; mute channel 4 (noise channel)
;>     rAUD1HIGH = AUD1HIGH_LENGTH_ON
	ld a, AUD1HIGH_LENGTH_ON
	ldh [rAUD1HIGH], a ; counter mode
;>     rAUD2HIGH = AUD1HIGH_LENGTH_ON
	ldh [rAUD2HIGH], a
;>     rAUD4GO = AUD1HIGH_LENGTH_ON
	ldh [rAUD4GO], a
;>     rAUDVOL = 0x77
	ld a, $77
	ldh [rAUDVOL], a ; full volume
;>     wUnusedMusicByte = 0
	xor a
	ld [wUnusedMusicByte], a
;>     wDisableChannelOutputWhenSfxEnds = 0
	ld [wDisableChannelOutputWhenSfxEnds], a
;>     wMuteAudioAndPauseMusic = 0
	ld [wMuteAudioAndPauseMusic], a
;>     wMusicTempo[1] = 0
	ld [wMusicTempo + 1], a
;>     wSfxTempo[1] = 0
	ld [wSfxTempo + 1], a
;>     wMusicWaveInstrument = 0
	ld [wMusicWaveInstrument], a
;>     wSfxWaveInstrument = 0
	ld [wSfxWaveInstrument], a
;>     fill(wChannelCommandPointers, 0, 0xA0)      # every channel variable up to the note timers
	ld d, $a0
	ld hl, wChannelCommandPointers
	call .FillMem
;>     fill(wChannelNoteDelayCounters, 1, 0x18)    # note timers, loop counters, note speeds
	ld a, $1
	ld d, $18
	ld hl, wChannelNoteDelayCounters
	call .FillMem
;>     wMusicTempo[0] = 1
	ld [wMusicTempo], a
;>     wSfxTempo[0] = 1
	ld [wSfxTempo], a
;>     wStereoPanning = 0xFF
;>     return
	ld a, $ff
	ld [wStereoPanning], a
	ret

; fills d bytes at hl with a
.FillMem
;> # .FillMem is the fill() used above: d bytes at hl set to a
	ld b, d
.loop
	ld [hli], a
	dec b
	jr nz, .loop
	ret

.playSoundCommon
;> sound = wSoundID
	ld a, [wSoundID]
;> i = 3 * sound
	ld l, a
	ld e, a
	ld h, 0
	ld d, h
	add hl, hl
	add hl, de
;> header = (SFX_Headers_1 + i) & 0xFFFF
	ld de, SFX_Headers_1
	add hl, de
;> p = header
	ld e, l
	ld d, h
	ld hl, wChannelCommandPointers
;> n = mem[p] >> 6                                 # the number of channels - 1
	ld a, [de] ; get channel number
	ld b, a
	rlca
	rlca
	and $3
	ld c, a
;> ch = mem[p] & 0xF                               # the first entry's channel
	ld a, b
	and $f
;> channels = n + 1
	ld b, c
	inc b
;> p += 1
	inc de
;> slot = 0                                        # which channel's pointer the next entry fills
	ld c, 0
.commandPointerLoop
;>@each for _ in range(channels):
;>     while slot != ch:
	cp c
	jr z, .next
;>         slot = (slot + 1) & 0xFF
	inc c
	inc hl
	inc hl
	jr .commandPointerLoop
.next
;>     # (the slot, the counter and ch are kept)
	push hl
	push bc
	push af
;>     wChannelSoundIDs[ch] = wSoundID
	ld b, 0
	ld c, a
	ld hl, wChannelSoundIDs
	add hl, bc
	ld a, [wSoundID]
	ld [hl], a
;>     if ch >= CHAN4:
;>         wChannelFlags1[ch] = wChannelFlags1[ch] | 1 << BIT_NOISE_OR_SFX
	pop af
	cp CHAN4
	jr c, .skipSettingFlag
	ld hl, wChannelFlags1
	add hl, bc
	set BIT_NOISE_OR_SFX, [hl]
.skipSettingFlag
;>     mem[wChannelCommandPointers + 2 * slot] = mem[p]          # the channel's start address
	pop bc
	pop hl
	ld a, [de] ; get channel pointer
	ld [hli], a
;>     mem[wChannelCommandPointers + 2 * slot + 1] = mem[p + 1]
	inc de
	ld a, [de]
	ld [hli], a
	inc de
;>     slot = (slot + 1) & 0xFF
	inc c
;=@each
	dec b
	ld a, b
	and a
;>     ch = mem[p + 2]                             # the next entry's channel byte
;>     p += 3
	ld a, [de]
	inc de
;=@each
	jr nz, .commandPointerLoop
;>@cry if (SFX_Cry00_1 - SFX_Headers_1) // 3 <= wSoundID < ((SFX_Cry25_1 - SFX_Headers_1) // 3 + 3):     # a cry
	ld a, [wSoundID]
	cp CRY_SFX_START
	jr nc, .maybeCry
	jr .done
.maybeCry
;=@cry
	ld a, [wSoundID]
	cp CRY_SFX_END
	jr z, .done
	jr c, .cry
	jr .done
.cry
;>     for i in range(CHAN5, CHAN8 + 1):           # claims all four effect channels
;>         wChannelSoundIDs[i] = wSoundID
	ld hl, wChannelSoundIDs + CHAN5
	ld [hli], a
	ld [hli], a
	ld [hli], a
	ld [hl], a
;>     wChannelCommandPointers[2 * CHAN7] = Audio1_CryRet & 0xFF   # its wave channel ends at once
;>     wChannelCommandPointers[2 * CHAN7 + 1] = Audio1_CryRet >> 8
	ld hl, wChannelCommandPointers + CHAN7 * 2 ; sfx wave channel pointer
	ld de, Audio1_CryRet
	ld [hl], e
	inc hl
	ld [hl], d ; overwrite pointer to point to sound_ret
;>     if not wSavedVolume:
;>         wSavedVolume = rAUDVOL                  # kept for when the cry ends
	ld a, [wSavedVolume]
	and a
	jr nz, .done
	ldh a, [rAUDVOL]
	ld [wSavedVolume], a
;>         rAUDVOL = 0x77                          # full volume
	ld a, $77
	ldh [rAUDVOL], a ; full volume
.done
	ret

;@ path: audio/engine_1
Audio1_CryRet:
	db sound_ret_cmd

;@ path: audio/engine_1
Audio1_HWChannelBaseAddresses:
; the low bytes of each HW channel's base address
	db HW_CH1_BASE, HW_CH2_BASE, HW_CH3_BASE, HW_CH4_BASE ; channels 0-3
	db HW_CH1_BASE, HW_CH2_BASE, HW_CH3_BASE, HW_CH4_BASE ; channels 4-7

;@ path: audio/engine_1
Audio1_HWChannelDisableMasks:
	db HW_CH1_DISABLE_MASK, HW_CH2_DISABLE_MASK, HW_CH3_DISABLE_MASK, HW_CH4_DISABLE_MASK ; channels 0-3
	db HW_CH1_DISABLE_MASK, HW_CH2_DISABLE_MASK, HW_CH3_DISABLE_MASK, HW_CH4_DISABLE_MASK ; channels 4-7

;@ path: audio/engine_1
Audio1_HWChannelEnableMasks:
	db HW_CH1_ENABLE_MASK, HW_CH2_ENABLE_MASK, HW_CH3_ENABLE_MASK, HW_CH4_ENABLE_MASK ; channels 0-3
	db HW_CH1_ENABLE_MASK, HW_CH2_ENABLE_MASK, HW_CH3_ENABLE_MASK, HW_CH4_ENABLE_MASK ; channels 4-7

;@ path: audio/engine_1
Audio1_Pitches:
; This file is INCLUDEd three times, once in each audio engine.

	dw $F82C ; C_
	dw $F89D ; C#
	dw $F907 ; D_
	dw $F96B ; D#
	dw $F9CA ; E_
	dw $FA23 ; F_
	dw $FA77 ; F#
	dw $FAC7 ; G_
	dw $FB12 ; G#
	dw $FB58 ; A_
	dw $FB9B ; A#
	dw $FBDA ; B_
; an alternate start for MeetRival which has a different first measure
;@ path: audio/alternate_tempo
;@ def Music_RivalAlternateStart()
;@ Play the rival's theme with a different first measure: start the song, then point its three channels
;@ at the alternate openings.
Music_RivalAlternateStart::
;> PlayMusic((Music_MeetRival - SFX_Headers_1) // 3, BANK(Music_MeetRival))
	ld c, BANK(Music_MeetRival)
	ld a, MUSIC_MEET_RIVAL
	call PlayMusic
;> ptr = Audio1_OverwriteChannelPointer(wChannelCommandPointers, Music_MeetRival_Ch1_AlternateStart)
	ld hl, wChannelCommandPointers
	ld de, Music_MeetRival_Ch1_AlternateStart
	call Audio1_OverwriteChannelPointer
;> ptr = Audio1_OverwriteChannelPointer(ptr, Music_MeetRival_Ch2_AlternateStart)
	ld de, Music_MeetRival_Ch2_AlternateStart
	call Audio1_OverwriteChannelPointer
;> Audio1_OverwriteChannelPointer(ptr, Music_MeetRival_Ch3_AlternateStart)    # it follows
	ld de, Music_MeetRival_Ch3_AlternateStart

;@ path: audio/alternate_tempo
;@ def Audio1_OverwriteChannelPointer(ptr: hl, address: de) -> hl
;@ Point a channel at other sound data: store `address` at `ptr` and move on to the next channel's pointer.
;@ test: ptr = wChannelCommandPointers + 2 * rand(0, 7)
Audio1_OverwriteChannelPointer:
;> mem16[ptr] = address
;> return ptr + 2
	ld a, e
	ld [hli], a
	ld a, d
	ld [hli], a
	ret

; an alternate tempo for MeetRival which is slightly slower
;@ path: audio/alternate_tempo
;@ def Music_RivalAlternateTempo()
;@ Play the rival's theme a little slower: its first channel starts at a version with another tempo.
Music_RivalAlternateTempo::
;> PlayMusic((Music_MeetRival - SFX_Headers_1) // 3, BANK(Music_MeetRival))
;> Audio1_OverwriteChannelPointer(wChannelCommandPointers, Music_MeetRival_Ch1_AlternateTempo)
	ld c, BANK(Music_MeetRival)
	ld a, MUSIC_MEET_RIVAL
	call PlayMusic
	ld hl, wChannelCommandPointers
	ld de, Music_MeetRival_Ch1_AlternateTempo
	jp Audio1_OverwriteChannelPointer

; applies both the alternate start and alternate tempo
;@ path: audio/alternate_tempo
;@ def Music_RivalAlternateStartAndTempo()
;@ The rival's theme with both the alternate first measure and the slower tempo.
Music_RivalAlternateStartAndTempo::
;> Music_RivalAlternateStart()
;> Audio1_OverwriteChannelPointer(wChannelCommandPointers, Music_MeetRival_Ch1_AlternateStartAndTempo)
	call Music_RivalAlternateStart
	ld hl, wChannelCommandPointers
	ld de, Music_MeetRival_Ch1_AlternateStartAndTempo
	jp Audio1_OverwriteChannelPointer

; an alternate tempo for Cities1 which is used for the Hall of Fame room
;@ path: audio/alternate_tempo
;@ def Music_Cities1AlternateTempo()
;@ The Hall of Fame music: fade out the current song (and wait 100 frames for it), then play the Cities1
;@ theme starting at a version with another tempo.
;@ test: skip waits 100 frames for the fade-out
Music_Cities1AlternateTempo::
;> wAudioFadeOutCounterReloadValue = 10
	ld a, 10
	ld [wAudioFadeOutCounterReloadValue], a
;> wAudioFadeOutCounter = 10
	ld [wAudioFadeOutCounter], a
;> wAudioFadeOutControl = 0xFF          # stop the music once faded out
	ld a, $ff ; stop playing music after the fade-out is finished
	ld [wAudioFadeOutControl], a
;> DelayFrames(100)
	ld c, 100
	call DelayFrames ; wait for the fade-out to finish
;> PlayMusic((Music_Cities1 - SFX_Headers_1) // 3, BANK(Music_Cities1))
	ld c, BANK(Music_Cities1)
	ld a, MUSIC_CITIES1
	call PlayMusic
;> Audio1_OverwriteChannelPointer(wChannelCommandPointers, Music_Cities1_Ch1_AlternateTempo)
	ld hl, wChannelCommandPointers
	ld de, Music_Cities1_Ch1_AlternateTempo
	jp Audio1_OverwriteChannelPointer


SECTION "Low Health Alarm (Audio Engine 2)", ROMX

;@ path: audio/low_health_alarm
;@ def Music_DoLowHealthAlarm()
;@ The low-health beep, once per frame: wLowHealthAlarm holds an on flag and a frame timer. At timer 0 the
;@ high tone starts and the timer goes back to 30; at 20 the low tone starts. While it runs, channel 5 is
;@ marked busy so no effect takes it. $FF switches the alarm off and silences channel 1.
;@ test: wLowHealthAlarm = DISABLE_LOW_HEALTH_ALARM if rand(0, 3) == 0 else (0x80 | rand(0, 2) * 20 if rand(0, 1) else rand(0, 255))
Music_DoLowHealthAlarm::
;> alarm = wLowHealthAlarm
;> tone = None
	ld a, [wLowHealthAlarm]
;> if alarm == DISABLE_LOW_HEALTH_ALARM:
	cp DISABLE_LOW_HEALTH_ALARM
	jr z, .disableAlarm

;>@off1     wLowHealthAlarm = 0
;>@off2     wChannelSoundIDs[CHAN5] = 0               # effects may use channel 5 again
;>@off3     tone = (0x00, 0x00, 0x00, 0x80)            # silence
;> elif alarm & 1 << BIT_LOW_HEALTH_ALARM:
	bit BIT_LOW_HEALTH_ALARM, a
	ret z

;>     timer = alarm & LOW_HEALTH_TIMER_MASK
;>     if timer == 0:
	and LOW_HEALTH_TIMER_MASK
	jr nz, .notToneHi ;if timer > 0, play low tone.

;>@hi         tone = (0xA0, 0xE2, 0x50, 0x87)        # the high tone
	call .playToneHi
;>         timer = 30
	ld a, 30 ;keep this tone for 30 frames.
	jr .resetTimer

.notToneHi
;>     else:
;>         if timer == 20:
	cp 20
	jr nz, .noTone   ;if timer == 20,
;>@lo             tone = (0xB0, 0xE2, 0xEE, 0x86)    # the low tone
	call .playToneLo ;actually set the sound registers.

.noTone
;>         wChannelSoundIDs[CHAN5] = ((SFX_Cry25_1 - SFX_Headers_1) // 3 + 3)   # (an ID no effect has) no effect takes channel 5
	ld a, CRY_SFX_END
	ld [wChannelSoundIDs + CHAN5], a ;disable sound channel?
;>         timer = timer - 1
	ld a, [wLowHealthAlarm]
	and LOW_HEALTH_TIMER_MASK
	dec a

.resetTimer
	; reset the timer and enable flag.
;>     wLowHealthAlarm = timer | 1 << BIT_LOW_HEALTH_ALARM
	set BIT_LOW_HEALTH_ALARM, a
	ld [wLowHealthAlarm], a
	ret

.disableAlarm
;=@off1
	xor a
	ld [wLowHealthAlarm], a  ;disable alarm
;=@off2
	ld [wChannelSoundIDs + CHAN5], a  ;re-enable sound channel?
;=@off3
	ld de, .toneDataSilence
	jr .playTone

;update the sound registers to change the frequency.
;the tone set here stays until we change it.
.playToneHi
;=@hi
	ld de, .toneDataHi
	jr .playTone

.playToneLo
;=@lo
	ld de, .toneDataLo

;update sound channel 1 to play the alarm, overriding all other sounds.
.playTone
;> if tone:                                        # (.playTone, called above) the tone goes to channel 1
;>     rAUD1SWEEP = 0                              # FF10 is always zeroed
	ld hl, rAUD1SWEEP ;channel 1 sound register
	ld c, $5
	xor a

.copyLoop
;>@cp     for i in range(4):                          # then FF11-FF14
;>         mem[addr(rAUD1LEN) + i] = tone[i]
	ld [hli], a
	ld a, [de]
	inc de
;=@cp
	dec c
	jr nz, .copyLoop
	ret


;bytes to write to sound channel 1 registers for health alarm.
;starting at FF11 (FF10 is always zeroed).
.toneDataHi
	db $A0
	db $E2
	dw $8750

.toneDataLo
	db $B0
	db $E2
	dw $86EE

;written to stop the alarm
.toneDataSilence
	db $00
	db $00
	dw $8000


SECTION "Audio Engine 2", ROMX

; The second of three duplicated sound engines.
; This copy has a few differences relating to battle sound effects
; and the low health alarm that plays in battle

;@ path: audio/engine_2
;@ def Audio2_UpdateMusic()
;@ The sound engine's frame, for the sounds in this audio bank: every channel that is playing runs one
;@ frame. While the music is paused (wMuteAudioAndPauseMusic) the music channels are skipped, and the first
;@ time round all output is switched off; effects keep playing.
;@ test: [mem.__setitem__(wChannelFlags1 + i, mem[wChannelFlags1 + i] & ~(1 << BIT_PITCH_SLIDE_ON)) for i in range(8)]
Audio2_UpdateMusic::
;> for channel in range(CHAN1, CHAN8 + 1):
	ld c, CHAN1
.loop
;>     if not wChannelSoundIDs[channel]:
;>         continue
	ld b, 0
	ld hl, wChannelSoundIDs
	add hl, bc
	ld a, [hl]
	and a
	jr z, .nextChannel
;>     if channel < CHAN5 and wMuteAudioAndPauseMusic:
	ld a, c
	cp CHAN5
	jr nc, .applyAffects ; if sfx channel
	ld a, [wMuteAudioAndPauseMusic]
	and a
	jr z, .applyAffects
;>         if not wMuteAudioAndPauseMusic & 1 << BIT_MUTE_AUDIO:
	bit BIT_MUTE_AUDIO, a
	jr nz, .nextChannel
;>             wMuteAudioAndPauseMusic = wMuteAudioAndPauseMusic | 1 << BIT_MUTE_AUDIO
	set BIT_MUTE_AUDIO, a
	ld [wMuteAudioAndPauseMusic], a
;>             rAUDTERM = 0
	xor a ; disable all channels' output
	ldh [rAUDTERM], a
;>             rAUD3ENA = 0
	ldh [rAUD3ENA], a
;>             rAUD3ENA = AUD3ENA_ON
	ld a, AUD3ENA_ON
	ldh [rAUD3ENA], a
;>         continue
	jr .nextChannel
.applyAffects
;>     Audio2_ApplyMusicAffects(channel)
	call Audio2_ApplyMusicAffects
.nextChannel
	ld a, c
	inc c ; inc channel number
	cp CHAN8
	jr nz, .loop
	ret

; this routine checks flags for music effects currently applied
; to the channel and calls certain functions based on flags.
;@ path: audio/engine_2
;@ def Audio2_ApplyMusicAffects(channel: c)
;@ One frame of a channel: when its note is over, read on to the next note; otherwise count down and apply
;@ what changes during a note - the duty cycle pattern, a pitch slide, or vibrato (after its delay, the
;@ frequency swings above and below the note on alternate steps). A music channel an effect is using waits.
;@ test: channel = rand(0, 7)
;@ test: [mem.__setitem__(wChannelFlags1 + i, mem[wChannelFlags1 + i] & ~(1 << BIT_PITCH_SLIDE_ON)) for i in range(8)]
Audio2_ApplyMusicAffects:
;> delay = wChannelNoteDelayCounters[channel]
	ld b, $0
	ld hl, wChannelNoteDelayCounters ; delay until next note
	add hl, bc
	ld a, [hl]
;> if delay == 1:                                 # the note is over
;>     return Audio2_PlayNextNote(channel, 0)
	cp 1 ; if the delay is 1, play next note
	jp z, Audio2_PlayNextNote
;> wChannelNoteDelayCounters[channel] = (delay - 1) & 0xFF
	dec a ; otherwise, decrease the delay timer
	ld [hl], a
;> if channel < CHAN5:
	ld a, c
	cp CHAN5
	jr nc, .startChecks ; if a sfx channel
;>     if wChannelSoundIDs[CHAN5 + channel]:      # an effect is using its hardware channel
;>         return
	ld hl, wChannelSoundIDs + CHAN5
	add hl, bc
	ld a, [hl]
	and a
	jr z, .startChecks
	ret
.startChecks
;> if wChannelFlags1[channel] & 1 << BIT_ROTATE_DUTY_CYCLE:
	ld hl, wChannelFlags1
	add hl, bc
	bit BIT_ROTATE_DUTY_CYCLE, [hl]
	jr z, .checkForExecuteMusic
;>     Audio2_ApplyDutyCyclePattern(channel)
	call Audio2_ApplyDutyCyclePattern
.checkForExecuteMusic
;> if not wChannelFlags2[channel] & 1 << BIT_EXECUTE_MUSIC:
	ld b, 0
	ld hl, wChannelFlags2
	add hl, bc
	bit BIT_EXECUTE_MUSIC, [hl]
	jr nz, .checkForPitchSlide
;>     if wChannelFlags1[channel] & 1 << BIT_NOISE_OR_SFX:
;>         return                                 # an effect's own notes have no slides or vibrato
	ld hl, wChannelFlags1
	add hl, bc
	bit BIT_NOISE_OR_SFX, [hl]
	jr nz, .skipPitchSlideVibrato
.checkForPitchSlide
;> if wChannelFlags1[channel] & 1 << BIT_PITCH_SLIDE_ON:
	ld hl, wChannelFlags1
	add hl, bc
	bit BIT_PITCH_SLIDE_ON, [hl]
	jr z, .checkVibratoDelay
;>     return Audio2_ApplyPitchSlide(channel, 0)
	jp Audio2_ApplyPitchSlide
.checkVibratoDelay
;> if wChannelVibratoDelayCounters[channel]:     # the vibrato waits for its delay
	ld hl, wChannelVibratoDelayCounters
	add hl, bc
	ld a, [hl]
	and a ; check if delay is over
	jr z, .checkForVibrato
;>     wChannelVibratoDelayCounters[channel] = wChannelVibratoDelayCounters[channel] - 1
	dec [hl] ; otherwise, dec delay
.skipPitchSlideVibrato
;>     return
	ret
.checkForVibrato
;> extent = wChannelVibratoExtents[channel]
	ld hl, wChannelVibratoExtents
	add hl, bc
	ld a, [hl]
;> if not extent:                                # no vibrato
;>     return
	and a
	jr nz, .vibrato
	ret ; no vibrato
.vibrato
;> rate = wChannelVibratoRates[channel]         # high nibble: reload value, low nibble: counter
	ld d, a
	ld hl, wChannelVibratoRates
	add hl, bc
	ld a, [hl]
;> if rate & 0xF:
	and $f
	and a
	jr z, .applyVibrato
;>     wChannelVibratoRates[channel] = rate - 1
;>     return
	dec [hl] ; decrement counter
	ret
.applyVibrato
;> wChannelVibratoRates[channel] = rate | rate >> 4  # reload the counter
	ld a, [hl]
	swap [hl]
	or [hl]
	ld [hl], a ; reload the counter
;> low = wChannelFrequencyLowBytes[channel]     # the note's frequency
	ld hl, wChannelFrequencyLowBytes
	add hl, bc
	ld e, [hl] ; get note pitch
;> if wChannelFlags1[channel] & 1 << BIT_VIBRATO_DIRECTION:   # up and down on alternate steps
	ld hl, wChannelFlags1
	add hl, bc
; This is the only code that sets/resets the vibrato direction bit, so it
; continuously alternates which path it takes.
	bit BIT_VIBRATO_DIRECTION, [hl]
	jr z, .unset
;>     wChannelFlags1[channel] = wChannelFlags1[channel] & ~(1 << BIT_VIBRATO_DIRECTION) & 0xFF
	res BIT_VIBRATO_DIRECTION, [hl]
;>     below = extent & 0xF                      # the extent below the note
	ld a, d
	and $f
	ld d, a
;>     low = max(low - below, 0)
	ld a, e
	sub d
	jr nc, .noCarry
	ld a, 0
.noCarry
	jr .done
.unset
;> else:
;>     wChannelFlags1[channel] = wChannelFlags1[channel] | 1 << BIT_VIBRATO_DIRECTION
	set BIT_VIBRATO_DIRECTION, [hl]
;>     above = extent >> 4                       # the extent above the note
	ld a, d
	and $f0
	swap a
;>     low = min(low + above, 0xFF)
	add e
	jr nc, .done
	ld a, $ff
.done
;> mem[Audio2_GetRegisterPointer(REG_FREQUENCY_LO, channel)] = low
	ld d, a
	ld b, REG_FREQUENCY_LO
	call Audio2_GetRegisterPointer
	ld [hl], d
	ret

; this routine executes all music commands that take up no time,
; like tempo changes, duty cycle changes etc. and doesn't return
; until the first note is reached
;@ path: audio/engine_2
;@ def Audio2_PlayNextNote(channel: c, zero: b)
;@ A note has ended: restart the vibrato delay, end any pitch slide, and run the channel's commands up to
;@ its next note - except on effect channel 5 while the low-health alarm sounds there. b is 0 on entry.
;@ test: channel = rand(0, 7); zero = 0
;@ test: [mem.__setitem__(wChannelFlags1 + i, mem[wChannelFlags1 + i] & ~(1 << BIT_PITCH_SLIDE_ON)) for i in range(8)]
Audio2_PlayNextNote:
; reload the vibrato delay counter
;> wChannelVibratoDelayCounters[channel] = wChannelVibratoDelayCounterReloadValues[channel]
	ld hl, wChannelVibratoDelayCounterReloadValues
	add hl, bc
	ld a, [hl]
	ld hl, wChannelVibratoDelayCounters
	add hl, bc
	ld [hl], a

;> # the pitch slide is over
;> wChannelFlags1[channel] = wChannelFlags1[channel] & ~(1 << BIT_PITCH_SLIDE_ON | 1 << BIT_PITCH_SLIDE_DECREASING) & 0xFF
	ld hl, wChannelFlags1
	add hl, bc
	res BIT_PITCH_SLIDE_ON, [hl]
	res BIT_PITCH_SLIDE_DECREASING, [hl]
	; --- this section is only present in this copy of the sound engine
;> if channel == CHAN5 and wLowHealthAlarm & 1 << BIT_LOW_HEALTH_ALARM:
;>     return                                      # the alarm has channel 5
	ld a, c
	cp CHAN5
	jr nz, .beginChecks
	ld a, [wLowHealthAlarm]
	bit BIT_LOW_HEALTH_ALARM, a
	ret nz
.beginChecks
	; ---
;> Audio2_sound_ret(channel)
	call Audio2_sound_ret
	ret

;@ path: audio/engine_2
;@ def Audio2_sound_ret(channel: c)
;@ Read and run a channel's next command. This is where the command chain starts: each handler below
;@ checks for its command and passes anything else on to the next one, until a note ends the frame's work.
;@ The sound_ret command itself returns from a sound_call, or ends the channel: its output is switched
;@ off, a finished cry restores the volume, and the channel's sound ID is cleared.
;@ test: channel = rand(0, 7)
;@ test: [mem.__setitem__(wChannelFlags1 + i, mem[wChannelFlags1 + i] & ~(1 << BIT_PITCH_SLIDE_ON)) for i in range(8)]
Audio2_sound_ret:
;> cmd = Audio2_GetNextMusicByte(channel)
	call Audio2_GetNextMusicByte
	ld d, a
;> if cmd != sound_ret_cmd:
;>     return Audio2_sound_call(channel, cmd, cmd)    # not this command: on down the chain
	cp sound_ret_cmd
	jp nz, Audio2_sound_call
;> if wChannelFlags1[channel] & 1 << BIT_SOUND_CALL:   # the end of a sound_call
	ld b, 0
	ld hl, wChannelFlags1
	add hl, bc
	bit BIT_SOUND_CALL, [hl]
	jr nz, .returnFromCall
;>@rf     wChannelFlags1[channel] = wChannelFlags1[channel] & ~(1 << BIT_SOUND_CALL) & 0xFF
;>@ri     i = 2 * channel & 0xFF                     # both tables hold 2-byte pointers
;>@rc     cur = addr(wChannelCommandPointers) + i
;>@rs     saved = addr(wChannelReturnAddresses) + i
;>@rp     mem[cur] = mem[saved]                      # back to the command after the call
;>@rp2     mem[cur + 1] = mem[saved + 1]
;>@rr     return Audio2_sound_ret(channel)            # and run it
;> if channel < CHAN4:
;>     disable = True                              # a music channel has ended: its output goes off
	ld a, c
	cp CHAN4
	jr nc, .noiseOrSfxChannel
	jr .disableChannelOutput
.noiseOrSfxChannel
;> else:                                           # an effect has ended: the hardware goes back to the music
;>     wChannelFlags1[channel] = wChannelFlags1[channel] & ~(1 << BIT_NOISE_OR_SFX) & 0xFF
	res BIT_NOISE_OR_SFX, [hl]
;>     wChannelFlags2[channel] = wChannelFlags2[channel] & ~(1 << BIT_EXECUTE_MUSIC) & 0xFF
	ld hl, wChannelFlags2
	add hl, bc
	res BIT_EXECUTE_MUSIC, [hl]
;>     if channel == CHAN7:
	cp CHAN7
	jr nz, .skipSfxChannel3
; restart hardware channel 3 (wave channel) output
;>         rAUD3ENA = AUD3ENA_OFF
	ld a, AUD3ENA_OFF
	ldh [rAUD3ENA], a
;>         rAUD3ENA = AUD3ENA_ON
	ld a, AUD3ENA_ON
	ldh [rAUD3ENA], a
.skipSfxChannel3
;>     disable = channel == CHAN7 and wDisableChannelOutputWhenSfxEnds != 0
	jr nz, .dontDisable
	ld a, [wDisableChannelOutputWhenSfxEnds]
	and a
	jr z, .dontDisable
;>     if disable:
;>         wDisableChannelOutputWhenSfxEnds = 0
	xor a
	ld [wDisableChannelOutputWhenSfxEnds], a
	jr .disableChannelOutput
.dontDisable
;=@cut
	jr .afterDisable
.returnFromCall
;=@rf
	res BIT_SOUND_CALL, [hl]
;=@ri
	ld d, $0
	ld a, c
	add a
	ld e, a
;=@rc
	ld hl, wChannelCommandPointers
	add hl, de
	push hl ; store current channel address
;=@rs
	ld hl, wChannelReturnAddresses
	add hl, de
	ld e, l
	ld d, h
	pop hl
;=@rp
	ld a, [de]
	ld [hli], a
;=@rp2
	inc de
	ld a, [de]
	ld [hl], a ; loads channel address to return to
;=@rr
	jp Audio2_sound_ret
.disableChannelOutput
;>@cut if disable:
;>     rAUDTERM = rAUDTERM & mem[Audio2_HWChannelDisableMasks + channel]
	ld hl, Audio2_HWChannelDisableMasks
	add hl, bc
	ldh a, [rAUDTERM]
	and [hl]
	ldh [rAUDTERM], a
.afterDisable
;>@cry if (SFX_Cry00_1 - SFX_Headers_1) // 3 <= wChannelSoundIDs[CHAN5] < ((SFX_Cry25_1 - SFX_Headers_1) // 3 + 3):   # a cry is playing
	ld a, [wChannelSoundIDs + CHAN5]
	cp CRY_SFX_START
	jr nc, .maybeCry
	jr .skipCry
.maybeCry
;=@cry
	ld a, [wChannelSoundIDs + CHAN5]
	cp CRY_SFX_END
	jr z, .skipCry
	jr c, .cry
	jr .skipCry
.cry
;>     if channel != CHAN5 and Audio2_GoBackOneCommandIfCry(channel):
;>         return                                  # the cry's other channels wait for channel 5
	ld a, c
	cp CHAN5
	jr z, .skipRewind
	call Audio2_GoBackOneCommandIfCry
	ret c
.skipRewind
;>     rAUDVOL = wSavedVolume                      # the cry is over: the volume from before it
	ld a, [wSavedVolume]
	ldh [rAUDVOL], a
;>     wSavedVolume = 0
	xor a
	ld [wSavedVolume], a
.skipCry
;> wChannelSoundIDs[channel] = 0                   # the channel is free
	ld hl, wChannelSoundIDs
	add hl, bc
	ld [hl], b
	ret

;@ path: audio/engine_2
;@ def Audio2_sound_call(channel: c, cmd: a, cmd_d: d)
;@ sound_call: remember where the channel is and continue at the address that follows (a subroutine of
;@ sound data). The command byte arrives in both a and d.
;@ test: cmd = sound_call_cmd if rand(0, 1) else rand(0, 255); cmd_d = cmd; channel = rand(0, 7)
;@ test: [mem.__setitem__(wChannelFlags1 + i, mem[wChannelFlags1 + i] & ~(1 << BIT_PITCH_SLIDE_ON)) for i in range(8)]
Audio2_sound_call:
;> if cmd != sound_call_cmd:
;>     return Audio2_sound_loop(channel, cmd, cmd_d)
	cp sound_call_cmd
	jp nz, Audio2_sound_loop
;> lo = Audio2_GetNextMusicByte(channel)        # the address to call
	call Audio2_GetNextMusicByte
	push af
;> hi = Audio2_GetNextMusicByte(channel)
	call Audio2_GetNextMusicByte
	ld d, a
	pop af
	ld e, a
	push de ; store pointer
;> i = 2 * channel & 0xFF
	ld d, $0
	ld a, c
	add a
	ld e, a
;> cur = addr(wChannelCommandPointers) + i
	ld hl, wChannelCommandPointers
	add hl, de
	push hl
;> saved = addr(wChannelReturnAddresses) + i
	ld hl, wChannelReturnAddresses
	add hl, de
	ld e, l
	ld d, h
	pop hl
;> mem[saved] = mem[cur]                       # where to come back to
	ld a, [hli]
	ld [de], a
;> mem[saved + 1] = mem[cur + 1]
	inc de
	ld a, [hld]
	ld [de], a ; copy current channel address
;> mem[cur] = lo
	pop de
	ld [hl], e
;> mem[cur + 1] = hi
	inc hl
	ld [hl], d ; overwrite current address with pointer
;> wChannelFlags1[channel] = wChannelFlags1[channel] | 1 << BIT_SOUND_CALL
	ld b, $0
	ld hl, wChannelFlags1
	add hl, bc
	set BIT_SOUND_CALL, [hl] ; set the call flag
;> return Audio2_sound_ret(channel)
	jp Audio2_sound_ret

;@ path: audio/engine_2
;@ def Audio2_sound_loop(channel: c, cmd: a, cmd_d: d)
;@ sound_loop count, address: jump back `count` times (0 = forever), then go on after the command.
;@ test: cmd = sound_loop_cmd if rand(0, 1) else rand(0, 255); cmd_d = cmd; channel = rand(0, 7)
;@ test: [mem.__setitem__(wChannelFlags1 + i, mem[wChannelFlags1 + i] & ~(1 << BIT_PITCH_SLIDE_ON)) for i in range(8)]
Audio2_sound_loop:
;> if cmd != sound_loop_cmd:
;>     return Audio2_note_type(channel, cmd, cmd_d)
	cp sound_loop_cmd
	jp nz, Audio2_note_type
;> count = Audio2_GetNextMusicByte(channel)
	call Audio2_GetNextMusicByte
	ld e, a
;> if count:
	and a
	jr z, .infiniteLoop
;>     if wChannelLoopCounters[channel] == count:
	ld b, 0
	ld hl, wChannelLoopCounters
	add hl, bc
	ld a, [hl]
	cp e
	jr nz, .loopAgain
;>         wChannelLoopCounters[channel] = 1      # done: skip the address
	ld a, $1 ; if no more loops to make,
	ld [hl], a
;>         Audio2_GetNextMusicByte(channel)
	call Audio2_GetNextMusicByte ; skip pointer
;>         Audio2_GetNextMusicByte(channel)
	call Audio2_GetNextMusicByte
;>         return Audio2_sound_ret(channel)
	jp Audio2_sound_ret
.loopAgain ; inc loop count
;>     wChannelLoopCounters[channel] = (wChannelLoopCounters[channel] + 1) & 0xFF
	inc a
	ld [hl], a
	; fall through
.infiniteLoop ; overwrite current address with pointer
;> lo = Audio2_GetNextMusicByte(channel)
	call Audio2_GetNextMusicByte
	push af
;> hi = Audio2_GetNextMusicByte(channel)
	call Audio2_GetNextMusicByte
	ld b, a
;> i = 2 * channel & 0xFF
	ld d, $0
	ld a, c
	add a
	ld e, a
;> wChannelCommandPointers[i] = lo
	ld hl, wChannelCommandPointers
	add hl, de
	pop af
	ld [hli], a
;> wChannelCommandPointers[i + 1] = hi
	ld [hl], b
;> return Audio2_sound_ret(channel)
	jp Audio2_sound_ret

;@ path: audio/engine_2
;@ def Audio2_note_type(channel: c, cmd: a, cmd_d: d)
;@ note_type speed, volume, fade: the low nibble is the note speed; then one byte of volume and fade (none on
;@ the noise channel). On the wave channel the byte picks the wave instrument and a volume level instead.
;@ test: cmd = note_type_cmd | rand(0, 15) if rand(0, 1) else rand(0, 255); cmd_d = cmd; channel = rand(0, 7)
;@ test: [mem.__setitem__(wChannelFlags1 + i, mem[wChannelFlags1 + i] & ~(1 << BIT_PITCH_SLIDE_ON)) for i in range(8)]
Audio2_note_type:
;> if cmd & 0xF0 != note_type_cmd:
;>     return Audio2_toggle_perfect_pitch(channel, cmd_d)
	and $f0
	cp note_type_cmd
	jp nz, Audio2_toggle_perfect_pitch
;> wChannelNoteSpeeds[channel] = cmd_d & 0xF
	ld a, d
	and $f
	ld b, $0
	ld hl, wChannelNoteSpeeds
	add hl, bc
	ld [hl], a ; store low nibble as speed
;> if channel != CHAN4:                          # the noise channel has no parameter byte
	ld a, c
	cp CHAN4
	jr z, .noiseChannel ; noise channel has 0 params
;>     param = Audio2_GetNextMusicByte(channel)
	call Audio2_GetNextMusicByte
	ld d, a
;>     if channel == CHAN3:
	ld a, c
	cp CHAN3
	jr z, .musicChannel3
;>@mw         slot = addr(wMusicWaveInstrument)
;>     elif channel == CHAN7:
	cp CHAN7
	jr nz, .skipChannel3
;>         slot = addr(wSfxWaveInstrument)
	ld hl, wSfxWaveInstrument
	jr .channel3
.musicChannel3
;=@mw
	ld hl, wMusicWaveInstrument
.channel3
;>     if channel in (CHAN3, CHAN7):              # the wave channel
;>         mem[slot] = param & 0xF                # the wave instrument
	ld a, d
	and $f
	ld [hl], a ; store low nibble of param as wave instrument
;>         param = (param & 0x30) << 1            # and a volume level
	ld a, d
	and $30
	sla a
	ld d, a
	; fall through

	; if channel 3, store high nibble as volume
	; else, store volume (high nibble) and fade (low nibble)
.skipChannel3
;>     wChannelVolumes[channel] = param
	ld b, 0
	ld hl, wChannelVolumes
	add hl, bc
	ld [hl], d
.noiseChannel
;> return Audio2_sound_ret(channel)
	jp Audio2_sound_ret

;@ path: audio/engine_2
;@ def Audio2_toggle_perfect_pitch(channel: c, cmd: d)
;@ toggle_perfect_pitch: from now on play every note one step higher (or stop doing so).
;@ test: cmd = toggle_perfect_pitch_cmd if rand(0, 1) else rand(0, 255); channel = rand(0, 7)
;@ test: [mem.__setitem__(wChannelFlags1 + i, mem[wChannelFlags1 + i] & ~(1 << BIT_PITCH_SLIDE_ON)) for i in range(8)]
Audio2_toggle_perfect_pitch:
;> if cmd != toggle_perfect_pitch_cmd:
;>     return Audio2_vibrato(channel, cmd, cmd)
	ld a, d
	cp toggle_perfect_pitch_cmd
	jr nz, Audio2_vibrato
;> wChannelFlags1[channel] = wChannelFlags1[channel] ^ 1 << BIT_PERFECT_PITCH
	ld b, 0
	ld hl, wChannelFlags1
	add hl, bc
	ld a, [hl]
	xor 1 << BIT_PERFECT_PITCH
	ld [hl], a
;> return Audio2_sound_ret(channel)
	jp Audio2_sound_ret

;@ path: audio/engine_2
;@ def Audio2_vibrato(channel: c, cmd: a, cmd_d: d)
;@ vibrato delay, extent and rate: after `delay` frames the pitch wobbles by `extent` steps around the note,
;@ split into half above and half below.
;@ test: cmd = vibrato_cmd if rand(0, 1) else rand(0, 255); cmd_d = cmd; channel = rand(0, 7)
;@ test: [mem.__setitem__(wChannelFlags1 + i, mem[wChannelFlags1 + i] & ~(1 << BIT_PITCH_SLIDE_ON)) for i in range(8)]
Audio2_vibrato:
;> if cmd != vibrato_cmd:
;>     return Audio2_pitch_slide(channel, cmd, cmd_d)
	cp vibrato_cmd
	jr nz, Audio2_pitch_slide
;> delay = Audio2_GetNextMusicByte(channel)
	call Audio2_GetNextMusicByte
;> wChannelVibratoDelayCounters[channel] = delay
	ld b, 0
	ld hl, wChannelVibratoDelayCounters
	add hl, bc
	ld [hl], a ; store delay
;> wChannelVibratoDelayCounterReloadValues[channel] = delay
	ld hl, wChannelVibratoDelayCounterReloadValues
	add hl, bc
	ld [hl], a ; store delay
;> param = Audio2_GetNextMusicByte(channel)
	call Audio2_GetNextMusicByte
	ld d, a

; The high nybble of the command byte is the extent of the vibrato.
; Let n be the extent.
; The upper nybble of the channel's byte in the wChannelVibratoExtents
; array will store the extent above the note: (n / 2) + (n % 2).
; The lower nybble will store the extent below the note: (n / 2).
; These two values add to the total extent, n.
;> extent = param >> 4
	and $f0
	swap a
;> half = extent // 2                           # below the note
	ld b, 0
	ld hl, wChannelVibratoExtents
	add hl, bc
	srl a
	ld e, a
;> wChannelVibratoExtents[channel] = (half + extent % 2) << 4 | half   # above | below
	adc b
	swap a
	or e
	ld [hl], a

; The low nybble of the command byte is the rate of the vibrato.
; The high and low nybbles of the channel's byte in the wChannelVibratoRates
; array are both initialised to this value because the high nybble is the
; counter reload value and the low nybble is the counter itself, which should
; start at its value upon reload.
;> rate = param & 0xF
	ld a, d
	and $f
	ld d, a
;> wChannelVibratoRates[channel] = rate << 4 | rate      # reload value and counter
	ld hl, wChannelVibratoRates
	add hl, bc
	swap a
	or d
	ld [hl], a

;> return Audio2_sound_ret(channel)
	jp Audio2_sound_ret

;@ path: audio/engine_2
;@ def Audio2_pitch_slide(channel: c, cmd: a, cmd_d: d)
;@ pitch_slide length, octave and note: the next note slides towards this target pitch.
;@ test: cmd = pitch_slide_cmd if rand(0, 1) else rand(0, 255); cmd_d = cmd; channel = rand(0, 7)
;@ test: [mem.__setitem__(wChannelFlags1 + i, mem[wChannelFlags1 + i] & ~(1 << BIT_PITCH_SLIDE_ON)) for i in range(8)]
Audio2_pitch_slide:
;> if cmd != pitch_slide_cmd:
;>     return Audio2_duty_cycle(channel, cmd, cmd_d)
	cp pitch_slide_cmd
	jr nz, Audio2_duty_cycle
;> wChannelPitchSlideLengthModifiers[channel] = Audio2_GetNextMusicByte(channel)
	call Audio2_GetNextMusicByte
	ld b, 0
	ld hl, wChannelPitchSlideLengthModifiers
	add hl, bc
	ld [hl], a
;> target = Audio2_GetNextMusicByte(channel)
	call Audio2_GetNextMusicByte
	ld d, a
;> freq = Audio2_CalculateFrequency(target & 0xF, target >> 4)
	and $f0
	swap a
	ld b, a
	ld a, d
	and $f
	call Audio2_CalculateFrequency
;> wChannelPitchSlideTargetFrequencyHighBytes[channel] = freq >> 8
	ld b, 0
	ld hl, wChannelPitchSlideTargetFrequencyHighBytes
	add hl, bc
	ld [hl], d
;> wChannelPitchSlideTargetFrequencyLowBytes[channel] = freq & 0xFF
	ld hl, wChannelPitchSlideTargetFrequencyLowBytes
	add hl, bc
	ld [hl], e
;> wChannelFlags1[channel] = wChannelFlags1[channel] | 1 << BIT_PITCH_SLIDE_ON
	ld b, 0
	ld hl, wChannelFlags1
	add hl, bc
	set BIT_PITCH_SLIDE_ON, [hl]
;> return Audio2_note_length(channel, Audio2_GetNextMusicByte(channel))
	call Audio2_GetNextMusicByte
	ld d, a
	jp Audio2_note_length

;@ path: audio/engine_2
;@ def Audio2_duty_cycle(channel: c, cmd: a, cmd_d: d)
;@ duty_cycle n: the square wave's duty (0 = 12.5%, 1 = 25%, 2 = 50%, 3 = 75%).
;@ test: cmd = duty_cycle_cmd if rand(0, 1) else rand(0, 255); cmd_d = cmd; channel = rand(0, 7)
;@ test: [mem.__setitem__(wChannelFlags1 + i, mem[wChannelFlags1 + i] & ~(1 << BIT_PITCH_SLIDE_ON)) for i in range(8)]
Audio2_duty_cycle:
;> if cmd != duty_cycle_cmd:
;>     return Audio2_tempo(channel, cmd, cmd_d)
	cp duty_cycle_cmd
	jr nz, Audio2_tempo
;> duty = (Audio2_GetNextMusicByte(channel) & 3) << 6     # into bits 6-7, where the hardware has it
	call Audio2_GetNextMusicByte
	rrca
	rrca
	and $c0
;> wChannelDutyCycles[channel] = duty
	ld b, 0
	ld hl, wChannelDutyCycles
	add hl, bc
	ld [hl], a ; store duty cycle
;> return Audio2_sound_ret(channel)
	jp Audio2_sound_ret

;@ path: audio/engine_2
;@ def Audio2_tempo(channel: c, cmd: a, cmd_d: d)
;@ tempo hi, lo: the music's tempo (on a music channel) or the effects' tempo; the fractional parts of the
;@ note timers start again from 0.
;@ test: cmd = tempo_cmd if rand(0, 1) else rand(0, 255); cmd_d = cmd; channel = rand(0, 7)
;@ test: [mem.__setitem__(wChannelFlags1 + i, mem[wChannelFlags1 + i] & ~(1 << BIT_PITCH_SLIDE_ON)) for i in range(8)]
Audio2_tempo:
;> if cmd != tempo_cmd:
;>     return Audio2_stereo_panning(channel, cmd, cmd_d)
	cp tempo_cmd
	jr nz, Audio2_stereo_panning
;> if channel < CHAN5:
	ld a, c
	cp CHAN5
	jr nc, .sfxChannel
;>     wMusicTempo[0] = Audio2_GetNextMusicByte(channel)
	call Audio2_GetNextMusicByte
	ld [wMusicTempo], a ; store first param
;>     wMusicTempo[1] = Audio2_GetNextMusicByte(channel)
	call Audio2_GetNextMusicByte
	ld [wMusicTempo + 1], a ; store second param
;>     fill(addr(wChannelNoteDelayCountersFractionalPart), 0, 4)       # the music channels' fractions
	xor a
	ld [wChannelNoteDelayCountersFractionalPart], a ; clear RAM
	ld [wChannelNoteDelayCountersFractionalPart + 1], a
	ld [wChannelNoteDelayCountersFractionalPart + 2], a
	ld [wChannelNoteDelayCountersFractionalPart + 3], a
	jr .musicChannelDone
.sfxChannel
;> else:
;>     wSfxTempo[0] = Audio2_GetNextMusicByte(channel)
	call Audio2_GetNextMusicByte
	ld [wSfxTempo], a ; store first param
;>     wSfxTempo[1] = Audio2_GetNextMusicByte(channel)
	call Audio2_GetNextMusicByte
	ld [wSfxTempo + 1], a ; store second param
;>     fill(addr(wChannelNoteDelayCountersFractionalPart) + 4, 0, 4)   # the effect channels' fractions
	xor a
	ld [wChannelNoteDelayCountersFractionalPart + 4], a ; clear RAM
	ld [wChannelNoteDelayCountersFractionalPart + 5], a
	ld [wChannelNoteDelayCountersFractionalPart + 6], a
	ld [wChannelNoteDelayCountersFractionalPart + 7], a
.musicChannelDone
;> return Audio2_sound_ret(channel)
	jp Audio2_sound_ret

;@ path: audio/engine_2
;@ def Audio2_stereo_panning(channel: c, cmd: a, cmd_d: d)
;@ stereo_panning: which channels play on the left and right speaker.
;@ test: cmd = stereo_panning_cmd if rand(0, 1) else rand(0, 255); cmd_d = cmd; channel = rand(0, 7)
;@ test: [mem.__setitem__(wChannelFlags1 + i, mem[wChannelFlags1 + i] & ~(1 << BIT_PITCH_SLIDE_ON)) for i in range(8)]
Audio2_stereo_panning:
;> if cmd != stereo_panning_cmd:
;>     return Audio2_unknownmusic0xef(channel, cmd, cmd_d)
	cp stereo_panning_cmd
	jr nz, Audio2_unknownmusic0xef
;> wStereoPanning = Audio2_GetNextMusicByte(channel)
	call Audio2_GetNextMusicByte
	ld [wStereoPanning], a ; store panning
;> return Audio2_sound_ret(channel)
	jp Audio2_sound_ret

; this appears to never be used
;@ path: audio/engine_2
;@ def Audio2_unknownmusic0xef(channel: c, cmd: a, cmd_d: d)
;@ Command $EF: start another sound from inside the sound data, and let it switch its channel's output off
;@ when it ends. No sound in the game uses it.
;@ test: cmd = unknownmusic0xef_cmd if rand(0, 1) else rand(0, 255); cmd_d = cmd; channel = rand(0, 7)
;@ test: [mem.__setitem__(wChannelFlags1 + i, mem[wChannelFlags1 + i] & ~(1 << BIT_PITCH_SLIDE_ON)) for i in range(8)]
Audio2_unknownmusic0xef:
;> if cmd != unknownmusic0xef_cmd:
;>     return Audio2_duty_cycle_pattern(channel, cmd, cmd_d)
	cp unknownmusic0xef_cmd
	jr nz, Audio2_duty_cycle_pattern
;> Audio2_PlaySound(Audio2_GetNextMusicByte(channel))
	call Audio2_GetNextMusicByte
	push bc
	call Audio2_PlaySound
	pop bc
;> if not wDisableChannelOutputWhenSfxEnds:
	ld a, [wDisableChannelOutputWhenSfxEnds]
	and a
	jr nz, .skip
;>     wDisableChannelOutputWhenSfxEnds = wChannelSoundIDs[CHAN8]
	ld a, [wChannelSoundIDs + CHAN8]
	ld [wDisableChannelOutputWhenSfxEnds], a
;>     wChannelSoundIDs[CHAN8] = 0
	xor a
	ld [wChannelSoundIDs + CHAN8], a
.skip
;> return Audio2_sound_ret(channel)
	jp Audio2_sound_ret

;@ path: audio/engine_2
;@ def Audio2_duty_cycle_pattern(channel: c, cmd: a, cmd_d: d)
;@ duty_cycle_pattern: four 2-bit duties that take turns, one per frame.
;@ test: cmd = duty_cycle_pattern_cmd if rand(0, 1) else rand(0, 255); cmd_d = cmd; channel = rand(0, 7)
;@ test: [mem.__setitem__(wChannelFlags1 + i, mem[wChannelFlags1 + i] & ~(1 << BIT_PITCH_SLIDE_ON)) for i in range(8)]
Audio2_duty_cycle_pattern:
;> if cmd != duty_cycle_pattern_cmd:
;>     return Audio2_volume(channel, cmd, cmd_d)
	cp duty_cycle_pattern_cmd
	jr nz, Audio2_volume
;> pattern = Audio2_GetNextMusicByte(channel)
	call Audio2_GetNextMusicByte
;> wChannelDutyCyclePatterns[channel] = pattern
	ld b, 0
	ld hl, wChannelDutyCyclePatterns
	add hl, bc
	ld [hl], a ; store full pattern
;> wChannelDutyCycles[channel] = pattern & 0xC0
	and %11000000
	ld hl, wChannelDutyCycles
	add hl, bc
	ld [hl], a ; store first duty cycle
;> wChannelFlags1[channel] = wChannelFlags1[channel] | 1 << BIT_ROTATE_DUTY_CYCLE
	ld hl, wChannelFlags1
	add hl, bc
	set BIT_ROTATE_DUTY_CYCLE, [hl]
;> return Audio2_sound_ret(channel)
	jp Audio2_sound_ret

;@ path: audio/engine_2
;@ def Audio2_volume(channel: c, cmd: a, cmd_d: d)
;@ volume: the master volume of both speakers.
;@ test: cmd = volume_cmd if rand(0, 1) else rand(0, 255); cmd_d = cmd; channel = rand(0, 7)
;@ test: [mem.__setitem__(wChannelFlags1 + i, mem[wChannelFlags1 + i] & ~(1 << BIT_PITCH_SLIDE_ON)) for i in range(8)]
Audio2_volume:
;> if cmd != volume_cmd:
;>     return Audio2_execute_music(channel, cmd, cmd_d)
	cp volume_cmd
	jr nz, Audio2_execute_music
;> rAUDVOL = Audio2_GetNextMusicByte(channel)
	call Audio2_GetNextMusicByte
	ldh [rAUDVOL], a ; store volume
;> return Audio2_sound_ret(channel)
	jp Audio2_sound_ret

;@ path: audio/engine_2
;@ def Audio2_execute_music(channel: c, cmd: a, cmd_d: d)
;@ execute_music: an effect channel reads the rest of its data as music commands (no sfx_note or pitch_sweep).
;@ test: cmd = execute_music_cmd if rand(0, 1) else rand(0, 255); cmd_d = cmd; channel = rand(0, 7)
;@ test: [mem.__setitem__(wChannelFlags1 + i, mem[wChannelFlags1 + i] & ~(1 << BIT_PITCH_SLIDE_ON)) for i in range(8)]
Audio2_execute_music:
;> if cmd != execute_music_cmd:
;>     return Audio2_octave(channel, cmd, cmd_d)
	cp execute_music_cmd
	jr nz, Audio2_octave
;> wChannelFlags2[channel] = wChannelFlags2[channel] | 1 << BIT_EXECUTE_MUSIC
	ld b, $0
	ld hl, wChannelFlags2
	add hl, bc
	set BIT_EXECUTE_MUSIC, [hl]
;> return Audio2_sound_ret(channel)
	jp Audio2_sound_ret

;@ path: audio/engine_2
;@ def Audio2_octave(channel: c, cmd: a, cmd_d: d)
;@ octave n: the octave of the notes that follow.
;@ test: cmd = octave_cmd | rand(0, 15) if rand(0, 1) else rand(0, 255); cmd_d = cmd; channel = rand(0, 7)
;@ test: [mem.__setitem__(wChannelFlags1 + i, mem[wChannelFlags1 + i] & ~(1 << BIT_PITCH_SLIDE_ON)) for i in range(8)]
Audio2_octave:
;> if cmd & 0xF0 != octave_cmd:
;>     return Audio2_sfx_note(channel, cmd & 0xF0, cmd_d)
	and $f0
	cp octave_cmd
	jr nz, Audio2_sfx_note
;> wChannelOctaves[channel] = cmd_d & 0xF
	ld hl, wChannelOctaves
	ld b, 0
	add hl, bc
	ld a, d
	and $f
	ld [hl], a ; store low nibble as octave
;> return Audio2_sound_ret(channel)
	jp Audio2_sound_ret

; sfx_note is either square_note or noise_note depending on the channel
;@ path: audio/engine_2
;@ def Audio2_sfx_note(channel: c, cmd: a, cmd_d: d)
;@ A sound effect's note (square_note or noise_note): length, volume envelope and frequency written straight
;@ to the channel's registers. a holds the command's high nibble, d the whole command.
;@ test: cmd_d = sfx_note_cmd | rand(0, 15) if rand(0, 1) else rand(0, 255); cmd = cmd_d & 0xF0; channel = rand(0, 7)
;@ test: [mem.__setitem__(wChannelFlags1 + i, mem[wChannelFlags1 + i] & ~(1 << BIT_PITCH_SLIDE_ON)) for i in range(8)]
;@ test: mem[wChannelFlags1 + channel] |= 1 << BIT_NOISE_OR_SFX
Audio2_sfx_note:
;> if cmd != sfx_note_cmd:
;>     return Audio2_pitch_sweep(channel, cmd_d)
	cp sfx_note_cmd
	jr nz, Audio2_pitch_sweep
;> if channel < CHAN4:                            # only on the noise and effect channels
;>     return Audio2_pitch_sweep(channel, cmd_d)
	ld a, c
	cp CHAN4 ; is this a noise or sfx channel?
	jr c, Audio2_pitch_sweep ; no
;> if wChannelFlags2[channel] & 1 << BIT_EXECUTE_MUSIC:   # not while it reads music commands
;>     return Audio2_pitch_sweep(channel, cmd_d)
	ld b, 0
	ld hl, wChannelFlags2
	add hl, bc
	bit BIT_EXECUTE_MUSIC, [hl] ; is execute_music being used?
	jr nz, Audio2_pitch_sweep ; yes
;> Audio2_note_length(channel, cmd_d)
	call Audio2_note_length

; This code seems to do the same thing as what Audio2_ApplyDutyCycleAndSoundLength
; does below.
;> length = wChannelNoteDelayCounters[channel]   # (left in a by note_length)
	ld d, a
;> value = wChannelDutyCycles[channel] | length
	ld b, 0
	ld hl, wChannelDutyCycles
	add hl, bc
	ld a, [hl]
	or d
	ld d, a
;> mem[Audio2_GetRegisterPointer(REG_DUTY_SOUND_LEN, channel)] = value
	ld b, REG_DUTY_SOUND_LEN
	call Audio2_GetRegisterPointer
	ld [hl], d

;> envelope = Audio2_GetNextMusicByte(channel)
	call Audio2_GetNextMusicByte
	ld d, a
;> mem[Audio2_GetRegisterPointer(REG_VOLUME_ENVELOPE, channel)] = envelope
	ld b, REG_VOLUME_ENVELOPE
	call Audio2_GetRegisterPointer
	ld [hl], d
;> lo = Audio2_GetNextMusicByte(channel)
	call Audio2_GetNextMusicByte
	ld e, a
;> hi = 0
;> if channel != CHAN8:
	ld a, c
	cp CHAN8
	ld a, 0
	jr z, .skip
; Channels 1 through 3 have 2 registers that control frequency, but the noise
; channel a single register (the polynomial counter) that controls frequency,
; so this command has one less byte on the noise channel.
;>     hi = Audio2_GetNextMusicByte(channel)
	push de
	call Audio2_GetNextMusicByte
	pop de
.skip
;> freq = hi << 8 | lo
	ld d, a
	push de
;> Audio2_ApplyDutyCycleAndSoundLength(channel)
	call Audio2_ApplyDutyCycleAndSoundLength
;> Audio2_EnableChannelOutput(channel)
	call Audio2_EnableChannelOutput
;> Audio2_ApplyWavePatternAndFrequency(channel, freq)
	pop de
	call Audio2_ApplyWavePatternAndFrequency
	ret

;@ path: audio/engine_2
;@ def Audio2_pitch_sweep(channel: c, cmd: d)
;@ pitch_sweep: an effect on channel 1 sets the hardware frequency sweep.
;@ test: cmd = pitch_sweep_cmd if rand(0, 1) else rand(0, 255); channel = rand(0, 7)
;@ test: [mem.__setitem__(wChannelFlags1 + i, mem[wChannelFlags1 + i] & ~(1 << BIT_PITCH_SLIDE_ON)) for i in range(8)]
Audio2_pitch_sweep:
;> if channel < CHAN5:                             # only effects use it
;>     return Audio2_note(channel, cmd)
	ld a, c
	cp CHAN5
	jr c, Audio2_note ; if not a sfx
;> if cmd != pitch_sweep_cmd:
;>     return Audio2_note(channel, cmd)
	ld a, d
	cp pitch_sweep_cmd
	jr nz, Audio2_note
;> if wChannelFlags2[channel] & 1 << BIT_EXECUTE_MUSIC:
;>     return Audio2_note(channel, cmd)
	ld b, $0
	ld hl, wChannelFlags2
	add hl, bc
	bit BIT_EXECUTE_MUSIC, [hl]
	jr nz, Audio2_note ; no
;> rAUD1SWEEP = Audio2_GetNextMusicByte(channel)
	call Audio2_GetNextMusicByte
	ldh [rAUD1SWEEP], a
;> return Audio2_sound_ret(channel)
	jp Audio2_sound_ret

;@ path: audio/engine_2
;@ def Audio2_note(channel: c, cmd: d)
;@ A note. On the music noise channel it is a drum: drum_note plays a noise instrument (one of the noise
;@ sound effects) and waits; a single byte below $B0 is an unused shorter form of it.
;@ test: cmd = rand(0, 255); channel = CHAN4 if rand(0, 1) else rand(0, 7)
;@ test: [mem.__setitem__(wChannelFlags1 + i, mem[wChannelFlags1 + i] & ~(1 << BIT_PITCH_SLIDE_ON)) for i in range(8)]
Audio2_note:
;> if channel != CHAN4:                            # drums only on the noise channel
;>     return Audio2_note_length(channel, cmd)
	ld a, c
	cp CHAN4
	jr nz, Audio2_note_length ; if not noise channel
;> kind = cmd & 0xF0
	ld a, d
	and $f0
;> if kind == drum_note_cmd:
	cp drum_note_cmd
	jr z, .drum_note
;>@dlen     cmd = cmd & 0xF                         # the length
;>@dins     instrument = Audio2_GetNextMusicByte(channel)   # the instrument in the next byte
;> elif kind > drum_note_cmd:
;>     return Audio2_note_length(channel, cmd)
	jr nc, Audio2_note_length

	; this executes when on the noise channel and
	; the command id is less than drum_note_cmd ($b0)
	; in this case, the upper nybble is used as the noise instrument ($1-$a)
	; and the lower nybble is the length minus 1 (0-15)
	; however, this doesn't work for instrument #2 because the command id
	; is captured by the noise_note command (command id $2x)
	; this essentially acts like a drum_note command that is only 1 byte
	; instead of 2 and can only be used with instruments 1 and 3 through 10
	; this is unused by the game
;> else:
;>     instrument = cmd >> 4
	swap a
	ld b, a
;>     cmd = cmd & 0xF                             # the length
	ld a, d
	and $f
	ld d, a
	ld a, b
;>     # (the length and channel are kept for later)
	push de
	push bc
	jr .playDnote

.drum_note
;=@dlen
	ld a, d
	and $f
	push af
	push bc
;=@dins
	call Audio2_GetNextMusicByte ; get drum_note instrument
.playDnote
;> if not wDisableChannelOutputWhenSfxEnds:
	ld d, a
	ld a, [wDisableChannelOutputWhenSfxEnds]
	and a
	jr nz, .skipDnote
;>     Audio2_PlaySound(instrument)                # the instrument is a noise sound effect
	ld a, d
	call Audio2_PlaySound
.skipDnote
;> return Audio2_note_length(channel, cmd)         # and wait for the drum's length
	pop bc
	pop de

;@ path: audio/engine_2
;@ def Audio2_note_length(channel: c, cmd: d)
;@ How long the note lasts: (length + 1) * note speed * tempo, in 1/256 frames, added to the fractional part
;@ left over from the last note. Then the note's pitch, unless this is an effect's own note.
;@ test: cmd = rand(0, 255); channel = rand(0, 7)
;@ test: [mem.__setitem__(wChannelFlags1 + i, mem[wChannelFlags1 + i] & ~(1 << BIT_PITCH_SLIDE_ON)) for i in range(8)]
Audio2_note_length:
;> kept = cmd                                      # for note_pitch
	ld a, d
	push af
;> length = (cmd & 0xF) + 1                        # in 16ths
	and $f
	inc a
	ld b, 0
	ld e, a  ; store note length (in 16ths)
	ld d, b
;> ticks = Audio2_MultiplyAdd(wChannelNoteSpeeds[channel], length, 0) & 0xFF
	ld hl, wChannelNoteSpeeds
	add hl, bc
	ld a, [hl]
	ld l, b
	call Audio2_MultiplyAdd
;> if channel < CHAN5:
	ld a, c
	cp CHAN5
	jr nc, .sfxChannel
;>     tempo = wMusicTempo[0] << 8 | wMusicTempo[1]
	ld a, [wMusicTempo]
	ld d, a
	ld a, [wMusicTempo + 1]
	ld e, a
	jr .skip
.sfxChannel
;> elif channel == CHAN8:
;>     tempo = 0x100
	ld d, $1
	ld e, $0
	cp CHAN8
	jr z, .skip ; if noise channel
;> else:
;>     Audio2_SetSfxTempo()
	call Audio2_SetSfxTempo
;>     tempo = wSfxTempo[0] << 8 | wSfxTempo[1]
	ld a, [wSfxTempo]
	ld d, a
	ld a, [wSfxTempo + 1]
	ld e, a
.skip
;> total = Audio2_MultiplyAdd(ticks, tempo, wChannelNoteDelayCountersFractionalPart[channel])
	ld a, l ; a = note_length * note_speed
	ld b, 0
	ld hl, wChannelNoteDelayCountersFractionalPart
	add hl, bc
	ld l, [hl]
	call Audio2_MultiplyAdd
;> wChannelNoteDelayCountersFractionalPart[channel] = total & 0xFF
	ld e, l
	ld d, h ; de = note_delay_frac_part + (note_length * note_speed * tempo)
	ld hl, wChannelNoteDelayCountersFractionalPart
	add hl, bc
	ld [hl], e
;> wChannelNoteDelayCounters[channel] = total >> 8      # whole frames
	ld a, d
	ld hl, wChannelNoteDelayCounters
	add hl, bc
	ld [hl], a
;> if wChannelFlags2[channel] & 1 << BIT_EXECUTE_MUSIC:
;>     return Audio2_note_pitch(channel, kept)
	ld hl, wChannelFlags2
	add hl, bc
	bit BIT_EXECUTE_MUSIC, [hl]
	jr nz, Audio2_note_pitch
;> if not wChannelFlags1[channel] & 1 << BIT_NOISE_OR_SFX:
;>     return Audio2_note_pitch(channel, kept)
	ld hl, wChannelFlags1
	add hl, bc
	bit BIT_NOISE_OR_SFX, [hl]
	jr z, Audio2_note_pitch
;> return                                          # an effect's note sets no pitch here (kept is dropped)
	pop hl
	ret

;@ path: audio/engine_2
;@ def Audio2_note_pitch(channel: c, cmd)
;@ The note's pitch: a rest silences the channel (unless an effect has it); a note gets its frequency from
;@ the pitch table and the channel's octave, starts any pitch slide, and is written to the hardware - but a
;@ music channel stays quiet while an effect plays on it. The command byte is the one note_length left on
;@ the stack.
;@ test: skip starts by popping the command byte Audio2_note_length pushed
Audio2_note_pitch:
;> if cmd & 0xF0 == rest_cmd:
	pop af
	and $f0
	cp rest_cmd
	jr nz, .notRest
;>     if channel < CHAN5:
	ld a, c
	cp CHAN5
	jr nc, .next
; If this isn't an SFX channel, try the corresponding SFX channel.
;>         if wChannelSoundIDs[CHAN5 + channel]:
;>             return                              # an effect has the hardware channel
	ld hl, wChannelSoundIDs + CHAN5
	add hl, bc
	ld a, [hl]
	and a
	jr nz, .done
	; fall through
.next
;>     if channel == CHAN3 or channel == CHAN7:
	ld a, c
	cp CHAN3
	jr z, .channel3
	cp CHAN7
	jr nz, .notChannel3
.channel3
;>         mask = mem[Audio2_HWChannelDisableMasks + channel]
	ld b, 0
	ld hl, Audio2_HWChannelDisableMasks
	add hl, bc
;>         rAUDTERM = rAUDTERM & mask              # the wave channel's output off
	ldh a, [rAUDTERM]
	and [hl]
	ldh [rAUDTERM], a ; disable hardware channel 3's output
	jr .done
.notChannel3
;>     else:
;>         reg = Audio2_GetRegisterPointer(REG_VOLUME_ENVELOPE, channel)
	ld b, REG_VOLUME_ENVELOPE
	call Audio2_GetRegisterPointer
;>         mem[reg] = 8                            # volume 0, rising
	ld a, $8 ; fade in sound
	ld [hli], a
;>         mem[reg + 2] = 0x80                     # restart the channel
	inc hl
	ld a, $80 ; restart sound
	ld [hl], a
.done
;>     return
	ret
.notRest
;> freq = Audio2_CalculateFrequency(cmd >> 4, wChannelOctaves[channel])
	swap a
	ld b, 0
	ld hl, wChannelOctaves
	add hl, bc
	ld b, [hl]
	call Audio2_CalculateFrequency
;> if wChannelFlags1[channel] & 1 << BIT_PITCH_SLIDE_ON:
;>     freq = Audio2_InitPitchSlideVars(channel, freq, 0)
	ld b, 0
	ld hl, wChannelFlags1
	add hl, bc
	bit BIT_PITCH_SLIDE_ON, [hl]
	jr z, .skipPitchSlide
	call Audio2_InitPitchSlideVars
.skipPitchSlide
;> if channel < CHAN5:
	push de
	ld a, c
	cp CHAN5
	jr nc, .sfxChannel ; if sfx channel
; If this isn't an SFX channel, try the corresponding SFX channel.
;>     busy = wChannelSoundIDs[CHAN5 + channel]
	ld hl, wChannelSoundIDs + CHAN5
	ld d, 0
	ld e, a
	add hl, de
	ld a, [hl]
;>     if busy:
	and a
	jr nz, .noSfx
	jr .sfxChannel
.noSfx
;>         return                                  # the music stays quiet under the effect
	pop de
	ret
.sfxChannel
;> volume = wChannelVolumes[channel]
	ld b, 0
	ld hl, wChannelVolumes
	add hl, bc
	ld d, [hl]
;> mem[Audio2_GetRegisterPointer(REG_VOLUME_ENVELOPE, channel)] = volume
	ld b, REG_VOLUME_ENVELOPE
	call Audio2_GetRegisterPointer
	ld [hl], d
;> Audio2_ApplyDutyCycleAndSoundLength(channel)
	call Audio2_ApplyDutyCycleAndSoundLength
;> Audio2_EnableChannelOutput(channel)
	call Audio2_EnableChannelOutput
;> if wChannelFlags1[channel] & 1 << BIT_PERFECT_PITCH:
	pop de
	ld b, $0
	ld hl, wChannelFlags1
	add hl, bc
	bit BIT_PERFECT_PITCH, [hl] ; has toggle_perfect_pitch been used?
	jr z, .skipFrequencyInc
;>     freq = freq & 0xFF00 | (freq + 1) & 0xFF    # the carry into the high byte never happens
	inc e                       ; if yes, increment the frequency by 1
	jr nc, .skipFrequencyInc    ; Likely a mistake, because `inc` does not set flag C.
	                            ; Fortunately this does not seem to affect any notes that actually occur.
	inc d
.skipFrequencyInc
;> wChannelFrequencyLowBytes[channel] = freq & 0xFF
	ld hl, wChannelFrequencyLowBytes
	add hl, bc
	ld [hl], e
;> Audio2_ApplyWavePatternAndFrequency(channel, freq)
	call Audio2_ApplyWavePatternAndFrequency
	ret

;@ path: audio/engine_2
;@ def Audio2_EnableChannelOutput(channel: c)
;@ Turn a channel's output on in rAUDTERM. For the noise effect channel, or a music channel no effect is
;@ covering, only on the sides wStereoPanning allows.
;@ test: channel = rand(0, 7)
Audio2_EnableChannelOutput:
;> value = rAUDTERM | mem[Audio2_HWChannelEnableMasks + channel]   # this channel's bits on
	ld b, 0
	ld hl, Audio2_HWChannelEnableMasks
	add hl, bc
	ldh a, [rAUDTERM]
	or [hl] ; set this channel's bits
	ld d, a
;> pan = channel == CHAN8 or channel < CHAN5
	ld a, c
	cp CHAN8
	jr z, .noiseChannelOrNoSfx
	cp CHAN5
	jr nc, .skip ; if sfx channel
; If this isn't an SFX channel, try the corresponding SFX channel.
;> if channel < CHAN5 and wChannelSoundIDs[CHAN5 + channel]:
;>     pan = False                                 # an effect covers this music channel
	ld hl, wChannelSoundIDs + CHAN5
	add hl, bc
	ld a, [hl]
	and a
	jr nz, .skip
.noiseChannelOrNoSfx
; If this is the SFX noise channel or a music channel whose corresponding
; SFX channel is off, apply stereo panning.
;> if pan:
;>     sides = wStereoPanning & mem[Audio2_HWChannelEnableMasks + channel]
	ld a, [wStereoPanning]
	ld hl, Audio2_HWChannelEnableMasks
	add hl, bc
	and [hl]
	ld d, a
;>     value = rAUDTERM & mem[Audio2_HWChannelDisableMasks + channel] | sides
	ldh a, [rAUDTERM]
	ld hl, Audio2_HWChannelDisableMasks
	add hl, bc
	and [hl] ; reset this channel's output bits
	or d ; set this channel's output bits that enabled in [wStereoPanning]
	ld d, a
.skip
;> rAUDTERM = value
	ld a, d
	ldh [rAUDTERM], a
	ret

;@ path: audio/engine_2
;@ def Audio2_ApplyDutyCycleAndSoundLength(channel: c)
;@ Write a channel's duty/length register: the note's length, plus the duty cycle on the square and
;@ noise channels (the wave channel has no duty).
;@ test: channel = rand(0, 7)
Audio2_ApplyDutyCycleAndSoundLength:
;> value = wChannelNoteDelayCounters[channel]    # the note's length
	ld b, 0
	ld hl, wChannelNoteDelayCounters ; use the note delay as sound length
	add hl, bc
	ld d, [hl]
;> if channel != CHAN3 and channel != CHAN7:
	ld a, c
	cp CHAN3
	jr z, .skipDuty ; if music channel 3
	cp CHAN7
	jr z, .skipDuty ; if sfx channel 3
; include duty cycle (except on channel 3 which doesn't have it)
;>     value = value & 0x3F
	ld a, d
	and $3f
	ld d, a
;>     value = value | wChannelDutyCycles[channel]
	ld hl, wChannelDutyCycles
	add hl, bc
	ld a, [hl]
	or d
	ld d, a
.skipDuty
;> mem[Audio2_GetRegisterPointer(REG_DUTY_SOUND_LEN, channel)] = value
	ld b, REG_DUTY_SOUND_LEN
	call Audio2_GetRegisterPointer
	ld [hl], d
	ret

;@ path: audio/engine_2
;@ def Audio2_ApplyWavePatternAndFrequency(channel: c, freq: de)
;@ Start a note on a channel: on the wave channel first load its instrument's 32 samples into wave RAM
;@ (with the channel stopped), then write the frequency with the counter-mode flag.
;@ test: channel = rand(0, 7)
Audio2_ApplyWavePatternAndFrequency:
;> if channel == CHAN3 or channel == CHAN7:     # the wave channel
	ld a, c
	cp CHAN3
	jr z, .channel3
	cp CHAN7
	jr nz, .notChannel3
	; fall through
.channel3
;>     instrument = wMusicWaveInstrument if channel == CHAN3 else wSfxWaveInstrument
	push de
	ld de, wMusicWaveInstrument
	cp CHAN3
	jr z, .next
	ld de, wSfxWaveInstrument
.next
;>     i = 2 * instrument & 0xFF
	ld a, [de]
	add a
	ld d, 0
	ld e, a
;>     src = mem16[Audio2_WavePointers + i]       # its 32 samples
	ld hl, Audio2_WavePointers
	add hl, de
	ld e, [hl]
	inc hl
	ld d, [hl]
;=@wave
	ld hl, _AUD3WAVERAM
	ld b, AUD3WAVE_SIZE - 1
;>     rAUD3ENA = 0                               # stopped while its wave RAM is written
	ld a, $0 ; stop hardware channel 3
	ldh [rAUD3ENA], a
.loop
;>@wave     for i in range(AUD3WAVE_SIZE):
;>         mem[_AUD3WAVERAM + i] = mem[src + i]
	ld a, [de]
	inc de
	ld [hli], a
;=@wave
	ld a, b
	dec b
	and a
	jr nz, .loop
;>     rAUD3ENA = AUD3ENA_ON
	ld a, AUD3ENA_ON ; start hardware channel 3
	ldh [rAUD3ENA], a
	pop de
.notChannel3
;> hi = (freq >> 8 | 0x80) & 0xC7
	ld a, d
	or $80 ; use counter mode (i.e. disable output when the counter reaches 0)
	and $c7 ; zero the unused bits in the register
	ld d, a
;> reg = Audio2_GetRegisterPointer(REG_FREQUENCY_LO, channel)
	ld b, REG_FREQUENCY_LO
	call Audio2_GetRegisterPointer
;> mem[reg] = freq & 0xFF
	ld [hl], e ; store frequency low byte
;> mem[reg + 1] = hi
	inc hl
	ld [hl], d ; store frequency high byte
	; --- this section is only present in this copy of the sound engine
;> if channel >= CHAN5:                            # effect channels follow the pitch modifier
	ld a, c
	cp CHAN5
	jr c, .musicChannel
;>     Audio2_ApplyFrequencyModifier(reg + 1, hi << 8 | freq & 0xFF)
	call Audio2_ApplyFrequencyModifier
.musicChannel
	; ---
	ret

; --- this section is only present in this copy of the sound engine
; unused
;@ path: audio/engine_2
;@ def Audio2_ResetCryModifiers(channel: c)
;@ On effect channel 5, while the low-health alarm sounds, set the pitch and tempo modifiers back to
;@ neutral (pitch +0, tempo $80). Nothing calls it.
;@ test: channel = CHAN5 if rand(0, 1) else rand(0, 7)
Audio2_ResetCryModifiers:
;> if channel == CHAN5 and wLowHealthAlarm & 1 << BIT_LOW_HEALTH_ALARM:
	ld a, c
	cp CHAN5
	jr nz, .skip
	ld a, [wLowHealthAlarm]
	bit BIT_LOW_HEALTH_ALARM, a
	jr z, .skip
;>     wFrequencyModifier = 0
;>     wTempoModifier = 0x80
	xor a
	ld [wFrequencyModifier], a
	ld a, $80
	ld [wTempoModifier], a
.skip
	ret
; ---

;@ path: audio/engine_2
;@ def Audio2_SetSfxTempo()
;@ Sound effects normally run at tempo $100; a cry or a battle sound runs at $80 plus the tempo modifier.
Audio2_SetSfxTempo:
;> if Audio2_IsCry() or Audio2_IsBattleSFX():
	call Audio2_IsCry
	jr c, .skipCryCheck
	call Audio2_IsBattleSFX
	jr nc, .notCry
.skipCryCheck
;>     tempo = wTempoModifier + 0x80
	ld d, 0
	ld a, [wTempoModifier]
	add $80
	jr nc, .next
	inc d
.next
;>     wSfxTempo[1] = tempo & 0xFF
	ld [wSfxTempo + 1], a
;>     wSfxTempo[0] = tempo >> 8
	ld a, d
	ld [wSfxTempo], a
	jr .done
.notCry
;> else:
;>     wSfxTempo[1] = 0                           # tempo $100
	xor a
	ld [wSfxTempo + 1], a
;>     wSfxTempo[0] = 1
	ld a, $1
	ld [wSfxTempo], a
.done
	ret

;@ path: audio/engine_2
;@ def Audio2_ApplyFrequencyModifier(reg: hl, freq: de)
;@ While a cry or a battle sound plays, raise the frequency just written to the register pair ending at `reg`
;@ by the pitch modifier.
;@ test: reg = rand(0xC001, 0xDF00)
Audio2_ApplyFrequencyModifier:
;> if Audio2_IsCry() or Audio2_IsBattleSFX():
	call Audio2_IsCry
	jr c, .skipCryCheck
	call Audio2_IsBattleSFX
	jr nc, .done
.skipCryCheck
; if playing a cry, add the cry's frequency modifier
;>     freq = (freq + wFrequencyModifier) & 0xFFFF
	ld a, [wFrequencyModifier]
	add e
	jr nc, .noCarry
	inc d
.noCarry
;>     mem[reg - 1] = freq & 0xFF
	dec hl
	ld e, a
	ld [hl], e
;>     mem[reg] = freq >> 8
	inc hl
	ld [hl], d
.done
	ret

;@ path: audio/engine_2
;@ def Audio2_GoBackOneCommandIfCry(channel: c) -> carry
;@ For a cry, step the channel's data pointer back one byte (so the byte is read again) and return carry.
;@ test: channel = rand(0, 7)
Audio2_GoBackOneCommandIfCry:
;> if not Audio2_IsCry():
;>     return False
	call Audio2_IsCry
	jr nc, .done
;> p = addr(wChannelCommandPointers) + 2 * channel
	ld hl, wChannelCommandPointers
	ld e, c
	ld d, 0
	sla e
	rl d
	add hl, de
;> borrow = mem[p] == 0
;> mem[p] = (mem[p] - 1) & 0xFF                  # one byte back
	ld a, [hl]
	sub 1
	ld [hl], a
;> mem[p + 1] = (mem[p + 1] - borrow) & 0xFF
	inc hl
	ld a, [hl]
	sbc 0
	ld [hl], a
;> return True
	scf
	ret
.done
	scf
	ccf
	ret

;@ path: audio/engine_2
;@ def Audio2_IsCry() -> carry
;@ Whether the sound effect on channel 5 is a Pokemon cry.
Audio2_IsCry:
; Returns whether the currently playing audio is a cry in carry.
;> sound = wChannelSoundIDs[CHAN5]
	ld a, [wChannelSoundIDs + CHAN5]
;> if sound < (SFX_Cry00_1 - SFX_Headers_1) // 3:
;>     return False
	cp CRY_SFX_START
	jr nc, .next
	jr .no
.next
;> return sound < ((SFX_Cry25_1 - SFX_Headers_1) // 3 + 3)                     # the answer goes back in the carry flag
	cp CRY_SFX_END
	jr z, .no
	jr c, .yes
.no
;> # .no: carry clear
	scf
	ccf
	ret
.yes
;> # .yes: carry set
	scf
	ret

; --- this section is only present in this copy of the sound engine
;@ path: audio/engine_2
;@ def Audio2_IsBattleSFX() -> carry
;@ Whether the effect playing is one of the battle sounds (move sounds and the like). It tests the
;@ sound IDs of channels 5 and 8 combined with `or`.
Audio2_IsBattleSFX:
; Returns whether the currently playing audio is a battle sfx in carry.
;> sound = wChannelSoundIDs[CHAN8] | wChannelSoundIDs[CHAN5]
	ld a, [wChannelSoundIDs + CHAN8]
	ld b, a
	ld a, [wChannelSoundIDs + CHAN5]
	or b
;> if sound < (SFX_Peck - SFX_Headers_1) // 3:
;>     return False
	cp BATTLE_SFX_START
	jr nc, .next
	jr .no
.next
;> return sound < ((SFX_Trainer_Appeared - SFX_Headers_1) // 3 + 1)                  # the answer goes back in the carry flag
	cp BATTLE_SFX_END
	jr z, .no
	jr c, .yes
.no
;> # .no: carry clear
	scf
	ccf
	ret
.yes
;> # .yes: carry set
	scf
	ret
; ---

;@ path: audio/engine_2
;@ def Audio2_ApplyPitchSlide(channel: c, zero: b)
;@ One frame of a pitch slide: move the frequency a step (plus the fractional step) towards the target, and
;@ stop the slide once it would pass it. b is 0 on entry.
;@ test: channel = rand(0, 7); zero = 0
Audio2_ApplyPitchSlide:
;> if not wChannelFlags1[channel] & 1 << BIT_PITCH_SLIDE_DECREASING:
	ld hl, wChannelFlags1
	add hl, bc
	bit BIT_PITCH_SLIDE_DECREASING, [hl]
	jp nz, .frequencyDecreasing
; frequency increasing
;>     cur_lo = wChannelPitchSlideCurrentFrequencyLowBytes[channel]
	ld hl, wChannelPitchSlideCurrentFrequencyLowBytes
	add hl, bc
	ld e, [hl]
;>     cur = wChannelPitchSlideCurrentFrequencyHighBytes[channel] << 8 | cur_lo
	ld hl, wChannelPitchSlideCurrentFrequencyHighBytes
	add hl, bc
	ld d, [hl]
;>     step = wChannelPitchSlideFrequencySteps[channel]
	ld hl, wChannelPitchSlideFrequencySteps
	add hl, bc
	ld l, [hl]
	ld h, b
;>     new = (cur + step) & 0xFFFF
	add hl, de
	ld d, h
	ld e, l
;>     step_frac = wChannelPitchSlideFrequencyStepsFractionalPart[channel]
	ld hl, wChannelPitchSlideCurrentFrequencyFractionalPart
	add hl, bc
	push hl
	ld hl, wChannelPitchSlideFrequencyStepsFractionalPart
	add hl, bc
	ld a, [hl]
;>     frac = wChannelPitchSlideCurrentFrequencyFractionalPart[channel] + step_frac
	pop hl
	add [hl]
;>     wChannelPitchSlideCurrentFrequencyFractionalPart[channel] = frac & 0xFF
	ld [hl], a
;>     new = (new + (frac >> 8)) & 0xFFFF         # plus the fraction's carry
	ld a, 0
	adc e
	ld e, a
	ld a, 0
	adc d
	ld d, a
;>     target_hi = wChannelPitchSlideTargetFrequencyHighBytes[channel]
	ld hl, wChannelPitchSlideTargetFrequencyHighBytes
	add hl, bc
	ld a, [hl]
;>     reached = new >> 8 > target_hi
	cp d
	jp c, .reachedTargetFrequency
;>     if new >> 8 == target_hi:
	jr nz, .applyUpdatedFrequency
;>         reached = new & 0xFF > wChannelPitchSlideTargetFrequencyLowBytes[channel]
	ld hl, wChannelPitchSlideTargetFrequencyLowBytes
	add hl, bc
	ld a, [hl]
	cp e
	jp c, .reachedTargetFrequency
	jr .applyUpdatedFrequency
.frequencyDecreasing
;> else:
;>     cur_lo = wChannelPitchSlideCurrentFrequencyLowBytes[channel]
	ld hl, wChannelPitchSlideCurrentFrequencyLowBytes
	add hl, bc
	ld a, [hl]
;>     cur = wChannelPitchSlideCurrentFrequencyHighBytes[channel] << 8 | cur_lo
	ld hl, wChannelPitchSlideCurrentFrequencyHighBytes
	add hl, bc
	ld d, [hl]
;>     step = wChannelPitchSlideFrequencySteps[channel]
	ld hl, wChannelPitchSlideFrequencySteps
	add hl, bc
	ld e, [hl]
;>     new = (cur - step) & 0xFFFF
	sub e
	ld e, a
	ld a, d
	sbc b
	ld d, a
;>     frac = wChannelPitchSlideFrequencyStepsFractionalPart[channel] * 2   # the fractional step doubles each frame
;>     wChannelPitchSlideFrequencyStepsFractionalPart[channel] = frac & 0xFF
	ld hl, wChannelPitchSlideFrequencyStepsFractionalPart
	add hl, bc
	ld a, [hl]
	add a
	ld [hl], a
;>     new = (new - (frac >> 8)) & 0xFFFF         # minus its carry
	ld a, e
	sbc b
	ld e, a
	ld a, d
	sbc b
	ld d, a
;>     target_hi = wChannelPitchSlideTargetFrequencyHighBytes[channel]
	ld hl, wChannelPitchSlideTargetFrequencyHighBytes
	add hl, bc
;>     reached = new >> 8 < target_hi
	ld a, d
	cp [hl]
	jr c, .reachedTargetFrequency
;>     if new >> 8 == target_hi:
	jr nz, .applyUpdatedFrequency
;>         reached = new & 0xFF < wChannelPitchSlideTargetFrequencyLowBytes[channel]
	ld hl, wChannelPitchSlideTargetFrequencyLowBytes
	add hl, bc
	ld a, e
	cp [hl]
	jr c, .reachedTargetFrequency
.applyUpdatedFrequency
;> if reached:                                     # the slide ends at its target
;>@stop     wChannelFlags1[channel] = wChannelFlags1[channel] & ~(1 << BIT_PITCH_SLIDE_ON | 1 << BIT_PITCH_SLIDE_DECREASING) & 0xFF
;>@ret     return
;> wChannelPitchSlideCurrentFrequencyLowBytes[channel] = new & 0xFF
	ld hl, wChannelPitchSlideCurrentFrequencyLowBytes
	add hl, bc
	ld [hl], e
;> wChannelPitchSlideCurrentFrequencyHighBytes[channel] = new >> 8
	ld hl, wChannelPitchSlideCurrentFrequencyHighBytes
	add hl, bc
	ld [hl], d
;> reg = Audio2_GetRegisterPointer(REG_FREQUENCY_LO, channel)
	ld b, REG_FREQUENCY_LO
	call Audio2_GetRegisterPointer
;> mem[reg] = new & 0xFF
	ld a, e
	ld [hli], a
;> mem[reg + 1] = new >> 8
	ld [hl], d
	ret
.reachedTargetFrequency
; Turn off pitch slide when the target frequency has been reached.
;=@stop
	ld hl, wChannelFlags1
	add hl, bc
	res BIT_PITCH_SLIDE_ON, [hl]
	res BIT_PITCH_SLIDE_DECREASING, [hl]
;=@ret
	ret

;@ path: audio/engine_2
;@ def Audio2_InitPitchSlideVars(channel: c, freq: de, zero: b) -> de
;@ Set up a pitch slide from freq to the target: the slide lasts the note's length minus the length
;@ modifier (at least 1 frame); the distance divided by that length gives the step per frame and a
;@ fractional step. Returns (steps + 1, remainder - length) in de. b is 0 on entry.
;@ test: channel = rand(0, 7); zero = 0
;@ test: mod = rand(0, 100); mem[wChannelPitchSlideLengthModifiers + channel] = mod; mem[wChannelNoteDelayCounters + channel] = mod + rand(16, 155)
Audio2_InitPitchSlideVars:
;> wChannelPitchSlideCurrentFrequencyHighBytes[channel] = freq >> 8
	ld hl, wChannelPitchSlideCurrentFrequencyHighBytes
	add hl, bc
	ld [hl], d
;> wChannelPitchSlideCurrentFrequencyLowBytes[channel] = freq & 0xFF
	ld hl, wChannelPitchSlideCurrentFrequencyLowBytes
	add hl, bc
	ld [hl], e
;> length = wChannelNoteDelayCounters[channel] - wChannelPitchSlideLengthModifiers[channel]
	ld hl, wChannelNoteDelayCounters
	add hl, bc
	ld a, [hl]
	ld hl, wChannelPitchSlideLengthModifiers
	add hl, bc
	sub [hl]
;> if length < 0:                                 # at least one frame
;>     length = 1
	jr nc, .next
	ld a, 1
.next
;> wChannelPitchSlideLengthModifiers[channel] = length   # from now on it holds the slide's length
	ld [hl], a
;> lo = (freq & 0xFF) - wChannelPitchSlideTargetFrequencyLowBytes[channel]
	ld hl, wChannelPitchSlideTargetFrequencyLowBytes
	add hl, bc
	ld a, e
	sub [hl]
	ld e, a
;> hi = ((freq >> 8) - (lo < 0)) & 0xFF
	ld a, d
	sbc b
;> if hi >= wChannelPitchSlideTargetFrequencyHighBytes[channel]:   # sliding down: current - target
	ld hl, wChannelPitchSlideTargetFrequencyHighBytes
	add hl, bc
	sub [hl]
	jr c, .targetFrequencyGreater
;>     diff = (hi - wChannelPitchSlideTargetFrequencyHighBytes[channel]) << 8 | lo & 0xFF
	ld d, a
;>     wChannelFlags1[channel] = wChannelFlags1[channel] | 1 << BIT_PITCH_SLIDE_DECREASING
	ld b, 0
	ld hl, wChannelFlags1
	add hl, bc
	set BIT_PITCH_SLIDE_DECREASING, [hl]
	jr .next2
.targetFrequencyGreater
; If the target frequency is greater, subtract the current frequency from
; the target frequency to get the absolute difference.
;> else:                                          # sliding up: target - current
;>     cur_hi = wChannelPitchSlideCurrentFrequencyHighBytes[channel]
	ld hl, wChannelPitchSlideCurrentFrequencyHighBytes
	add hl, bc
	ld d, [hl]
;>     cur_lo = wChannelPitchSlideCurrentFrequencyLowBytes[channel]
	ld hl, wChannelPitchSlideCurrentFrequencyLowBytes
	add hl, bc
	ld e, [hl]
;>     lo = wChannelPitchSlideTargetFrequencyLowBytes[channel] - cur_lo
	ld hl, wChannelPitchSlideTargetFrequencyLowBytes
	add hl, bc
	ld a, [hl]
	sub e
	ld e, a

; Bug. Instead of borrowing from the high byte of the target frequency as it
; should, it borrows from the high byte of the current frequency instead.
; This means that the result will be 0x200 greater than it should be if the
; low byte of the current frequency is greater than the low byte of the
; target frequency.
;>     hi = (cur_hi - (lo < 0)) & 0xFF
	ld a, d
	sbc b
	ld d, a

;>     diff = (wChannelPitchSlideTargetFrequencyHighBytes[channel] - hi) % 256 << 8 | lo & 0xFF
	ld hl, wChannelPitchSlideTargetFrequencyHighBytes
	add hl, bc
	ld a, [hl]
	sub d
	ld d, a
;>     wChannelFlags1[channel] = wChannelFlags1[channel] & ~(1 << BIT_PITCH_SLIDE_DECREASING) & 0xFF
	ld b, 0
	ld hl, wChannelFlags1
	add hl, bc
	res BIT_PITCH_SLIDE_DECREASING, [hl]

.next2
;> count = 0                                      # diff / length, by subtracting the length until it borrows
	ld hl, wChannelPitchSlideLengthModifiers
	add hl, bc
.divideLoop
;>@dv while True:
;>     count += 1
	inc b
;>     borrow = (diff & 0xFF) < length
;>     diff = diff & 0xFF00 | (diff - length) & 0xFF
	ld a, e
	sub [hl]
	ld e, a
;>     if not borrow:
;>         continue
	jr nc, .divideLoop
;>     if diff >> 8 == 0:
;>         break
	ld a, d
	and a
	jr z, .doneDividing
;>     diff -= 0x100                              # the borrow from the high byte
	dec a
	ld d, a
;=@dv
	jr .divideLoop
.doneDividing
;> rest = (diff + length) & 0xFF                  # the remainder
	ld a, e ; a = remainder - dividend
	add [hl]
;> wChannelPitchSlideFrequencySteps[channel] = count       # the quotient + 1
	ld d, b ; d = quotient + 1
	ld b, 0
	ld hl, wChannelPitchSlideFrequencySteps
	add hl, bc
	ld [hl], d ; store quotient + 1
;> wChannelPitchSlideFrequencyStepsFractionalPart[channel] = rest
	ld hl, wChannelPitchSlideFrequencyStepsFractionalPart
	add hl, bc
	ld [hl], a ; store remainder - dividend
;> wChannelPitchSlideCurrentFrequencyFractionalPart[channel] = rest
	ld hl, wChannelPitchSlideCurrentFrequencyFractionalPart
	add hl, bc
	ld [hl], a ; store remainder - dividend
;> return count << 8 | diff & 0xFF
	ret

;@ path: audio/engine_2
;@ def Audio2_ApplyDutyCyclePattern(channel: c)
;@ Step a channel's duty cycle pattern: four 2-bit duty values that rotate each frame, the top one going
;@ into the channel's duty register.
;@ test: channel = rand(0, 7)
Audio2_ApplyDutyCyclePattern:
;> p = wChannelDutyCyclePatterns[channel]
	ld b, 0
	ld hl, wChannelDutyCyclePatterns
	add hl, bc
	ld a, [hl]
;> p = (p << 2 | p >> 6) & 0xFF                   # rotate the next duty to the top
	rlca
	rlca
;> wChannelDutyCyclePatterns[channel] = p
	ld [hl], a
;> duty = p & 0xC0
	and $c0
	ld d, a
;> reg = Audio2_GetRegisterPointer(REG_DUTY_SOUND_LEN, channel)
	ld b, REG_DUTY_SOUND_LEN
	call Audio2_GetRegisterPointer
;> mem[reg] = mem[reg] & 0x3F | duty             # the duty is the register's top two bits
	ld a, [hl]
	and $3f
	or d
	ld [hl], a
	ret

;@ path: audio/engine_2
;@ def Audio2_GetNextMusicByte(channel: c) -> a
;@ Read the next byte of a channel's sound data and move its pointer on.
;@ test: channel = rand(0, 7)
Audio2_GetNextMusicByte:
;> i = 2 * channel & 0xFF
	ld d, 0
	ld a, c
	add a
	ld e, a
;> ptr = wChannelCommandPointers[i] | wChannelCommandPointers[i + 1] << 8
	ld hl, wChannelCommandPointers
	add hl, de
	ld a, [hli]
	ld e, a
	ld a, [hld]
	ld d, a
;> byte = mem[ptr]
	ld a, [de] ; get next music command
;> ptr = (ptr + 1) & 0xFFFF
	inc de
;> wChannelCommandPointers[i] = ptr & 0xFF
	ld [hl], e ; store address of next command
;> wChannelCommandPointers[i + 1] = ptr >> 8
	inc hl
	ld [hl], d
;> return byte
	ret

;@ path: audio/engine_2
;@ def Audio2_GetRegisterPointer(reg: b, channel: c) -> hl
;@ Address of sound register `reg` (0-4) of the hardware channel behind software channel `channel`.
Audio2_GetRegisterPointer:
; hl = address of hardware sound register b for software channel c
;> p = Audio2_HWChannelBaseAddresses + channel
	ld a, c
	ld hl, Audio2_HWChannelBaseAddresses
	add l
	jr nc, .noCarry
	inc h
.noCarry
	ld l, a
;> base = mem[p]                                 # low byte of the channel's first register
	ld a, [hl]
;> return 0xFF00 | (base + reg) & 0xFF
	add b
	ld l, a
	ld h, $ff
	ret

;@ path: audio/engine_2
;@ def Audio2_MultiplyAdd(n: a, step: de, base: l) -> hl
;@ base + n * step, by shifting and adding.
Audio2_MultiplyAdd:
; hl = l + (a * de)
;> result = base
	ld h, 0
.loop
;>@lp while True:
;>     low_bit, n = n & 1, n >> 1
	srl a
;>     if low_bit:
;>         result = (result + step) & 0xFFFF
	jr nc, .skipAdd
	add hl, de
.skipAdd
;>     step = (step << 1) & 0xFFFF
	sla e
	rl d
;>     if not n:
;>         break
	and a
	jr z, .done
;=@lp
	jr .loop
.done
;> return result
	ret

;@ path: audio/engine_2
;@ def Audio2_CalculateFrequency(note: a, octave: b) -> de
;@ The frequency register value for a note (0 = C ... 11 = B) in an octave: the pitch table holds octave 7;
;@ each octave below halves it. The top bits get the "restart" flag the register needs.
;@ test: note = rand(0, 11); octave = rand(0, 7)
Audio2_CalculateFrequency:
; return the frequency for note a, octave b in de
;> i = 2 * note                                   # 2 bytes per pitch
	ld h, 0
	ld l, a
	add hl, hl
	ld d, h
	ld e, l
;> freq = mem[Audio2_Pitches + i] | mem[Audio2_Pitches + i + 1] << 8
	ld hl, Audio2_Pitches
	add hl, de
	ld e, [hl]
	inc hl
	ld d, [hl]
;> o = octave
	ld a, b
.loop
;>@lp while o != 7:                               # each octave below 7 halves it
	cp 7
	jr z, .done
;>     freq = freq >> 1 | freq & 0x8000            # arithmetic shift: the table values are negative
	sra d
	rr e
;>     o = (o + 1) & 0xFF
	inc a
;=@lp
	jr .loop
.done
;> return (freq + 0x800) & 0xFFFF
	ld a, 8
	add d
	ld d, a
	ret

;@ path: audio/engine_2
;@ def Audio2_PlaySound(sound: a)
;@ Start a sound from this audio bank: $FF stops everything, IDs up to the last effect and $FF are effects,
;@ the rest (and $FE) are songs. A song resets the four music channels; an effect takes over only the
;@ channels it uses, unless a more important effect (lower ID) is playing there - noise instruments, the
;@ drums, never interrupt a real effect on the noise channel. Then each channel gets its start address
;@ from the sound's header (3 bytes per channel). A cry also claims all four effect channels and saves the
;@ volume.
Audio2_PlaySound::
;> wSoundID = sound
	ld [wSoundID], a
;> noise_end = (SFX_Noise_Instrument19_2 - SFX_Headers_2) // 3 + 1   # sound IDs count 3-byte headers
;> stop = sound == SFX_STOP_ALL_MUSIC
	cp SFX_STOP_ALL_MUSIC
	jp z, .stopAllAudio
;> last_sfx = (SFX_Trainer_Appeared - SFX_Headers_2) // 3
;> music = last_sfx < sound <= 0xFE                # the rest are sound effects
	cp MAX_SFX_ID_2
	jp z, .playSfx
	jp c, .playSfx
	cp $fe
	jr z, .playMusic
	jp nc, .playSfx

.playMusic
;> if music:
;>     wUnusedMusicByte = 0
	xor a
	ld [wUnusedMusicByte], a
;>     wDisableChannelOutputWhenSfxEnds = 0
	ld [wDisableChannelOutputWhenSfxEnds], a
;>     wMusicTempo[1] = 0
	ld [wMusicTempo + 1], a
;>     wMusicWaveInstrument = 0
	ld [wMusicWaveInstrument], a
;>     wSfxWaveInstrument = 0
	ld [wSfxWaveInstrument], a
;>     fill(wChannelReturnAddresses, 0, NUM_CHANNELS)      # 8 bytes: the four music channels' pointers
	ld d, NUM_CHANNELS
	ld hl, wChannelReturnAddresses
	call .FillMem
;>     fill(wChannelCommandPointers, 0, NUM_CHANNELS)
	ld hl, wChannelCommandPointers
	call .FillMem
;>     fill(wChannelSoundIDs, 0, NUM_MUSIC_CHANS)          # and every per-channel variable
	ld d, NUM_MUSIC_CHANS
	ld hl, wChannelSoundIDs
	call .FillMem
;>     fill(wChannelFlags1, 0, NUM_MUSIC_CHANS)
;>     fill(wChannelDutyCycles, 0, NUM_MUSIC_CHANS)
	ld hl, wChannelFlags1
	call .FillMem
	ld hl, wChannelDutyCycles
	call .FillMem
;>     fill(wChannelDutyCyclePatterns, 0, NUM_MUSIC_CHANS)
;>     fill(wChannelVibratoDelayCounters, 0, NUM_MUSIC_CHANS)
	ld hl, wChannelDutyCyclePatterns
	call .FillMem
	ld hl, wChannelVibratoDelayCounters
	call .FillMem
;>     fill(wChannelVibratoExtents, 0, NUM_MUSIC_CHANS)
;>     fill(wChannelVibratoRates, 0, NUM_MUSIC_CHANS)
	ld hl, wChannelVibratoExtents
	call .FillMem
	ld hl, wChannelVibratoRates
	call .FillMem
;>     fill(wChannelFrequencyLowBytes, 0, NUM_MUSIC_CHANS)
;>     fill(wChannelVibratoDelayCounterReloadValues, 0, NUM_MUSIC_CHANS)
	ld hl, wChannelFrequencyLowBytes
	call .FillMem
	ld hl, wChannelVibratoDelayCounterReloadValues
	call .FillMem
;>     fill(wChannelFlags2, 0, NUM_MUSIC_CHANS)
;>     fill(wChannelPitchSlideLengthModifiers, 0, NUM_MUSIC_CHANS)
	ld hl, wChannelFlags2
	call .FillMem
	ld hl, wChannelPitchSlideLengthModifiers
	call .FillMem
;>     fill(wChannelPitchSlideFrequencySteps, 0, NUM_MUSIC_CHANS)
;>     fill(wChannelPitchSlideFrequencyStepsFractionalPart, 0, NUM_MUSIC_CHANS)
	ld hl, wChannelPitchSlideFrequencySteps
	call .FillMem
	ld hl, wChannelPitchSlideFrequencyStepsFractionalPart
	call .FillMem
;>     fill(wChannelPitchSlideCurrentFrequencyFractionalPart, 0, NUM_MUSIC_CHANS)
;>     fill(wChannelPitchSlideCurrentFrequencyHighBytes, 0, NUM_MUSIC_CHANS)
	ld hl, wChannelPitchSlideCurrentFrequencyFractionalPart
	call .FillMem
	ld hl, wChannelPitchSlideCurrentFrequencyHighBytes
	call .FillMem
;>     fill(wChannelPitchSlideCurrentFrequencyLowBytes, 0, NUM_MUSIC_CHANS)
;>     fill(wChannelPitchSlideTargetFrequencyHighBytes, 0, NUM_MUSIC_CHANS)
	ld hl, wChannelPitchSlideCurrentFrequencyLowBytes
	call .FillMem
	ld hl, wChannelPitchSlideTargetFrequencyHighBytes
	call .FillMem
;>     fill(wChannelPitchSlideTargetFrequencyLowBytes, 0, NUM_MUSIC_CHANS)
	ld hl, wChannelPitchSlideTargetFrequencyLowBytes
	call .FillMem
;>     fill(wChannelLoopCounters, 1, NUM_MUSIC_CHANS)      # these start at 1
	ld a, $1
	ld hl, wChannelLoopCounters
	call .FillMem
;>     fill(wChannelNoteDelayCounters, 1, NUM_MUSIC_CHANS)
;>     fill(wChannelNoteSpeeds, 1, NUM_MUSIC_CHANS)
	ld hl, wChannelNoteDelayCounters
	call .FillMem
	ld hl, wChannelNoteSpeeds
	call .FillMem
;>     wMusicTempo[0] = 1
;>     wStereoPanning = 0xFF                       # both sides
	ld [wMusicTempo], a
	ld a, $ff
	ld [wStereoPanning], a
;>     rAUDVOL = 0
	xor a
	ldh [rAUDVOL], a
;>     rAUD1SWEEP = AUD1SWEEP_DOWN                 # sweep off
	ld a, AUD1SWEEP_DOWN
	ldh [rAUD1SWEEP], a
;>     rAUDTERM = 0
	ld a, 0
	ldh [rAUDTERM], a
;>     rAUD3ENA = 0                                # restart the wave channel
;>     rAUD3ENA = AUD3ENA_ON
	xor a
	ldh [rAUD3ENA], a
	ld a, AUD3ENA_ON
	ldh [rAUD3ENA], a
;>     rAUDVOL = 0x77                              # full volume
	ld a, $77
	ldh [rAUDVOL], a
	jp .playSoundCommon

.playSfx
;> elif not stop:
;>     i = 3 * sound
	ld l, a
	ld e, a
	ld h, 0
	ld d, h
	add hl, hl
	add hl, de
;>     header = (SFX_Headers_2 + i) & 0xFFFF
	ld de, SFX_Headers_2
	add hl, de
;>     wSfxHeaderPointer[0] = header >> 8
;>     wSfxHeaderPointer[1] = header & 0xFF
	ld a, h
	ld [wSfxHeaderPointer], a
	ld a, l
	ld [wSfxHeaderPointer + 1], a
;>     last = mem[header] >> 6                     # the effect's number of channels - 1
	ld a, [hl]
	and $c0
	rlca
	rlca
	ld c, a
.sfxChannelLoop
;>@loop     for k in range(last, -1, -1):          # its channels, last first
;>         i = 3 * k
	ld d, c
	ld a, c
	add a
	add c
	ld c, a
	ld b, 0
;>         entry = header + i                      # (the header address comes back from wSfxHeaderPointer)
	ld a, [wSfxHeaderPointer]
	ld h, a
	ld a, [wSfxHeaderPointer + 1]
	ld l, a
	add hl, bc
	ld c, d
;>         ch = mem[entry] & 0xF                   # the software channel
	ld a, [hl]
	and $f
	ld e, a ; software channel ID
;>         playing = wChannelSoundIDs[ch]
;>         if playing:                             # the channel is busy
	ld d, 0
	ld hl, wChannelSoundIDs
	add hl, de
	ld a, [hl]
	and a
	jr z, .playChannel
;>             if ch == CHAN8:
	ld a, e
	cp CHAN8
	jr nz, .notNoiseChannel
;>                 if wSoundID < noise_end:
;>                     return                      # a drum never interrupts an effect on the noise channel
	ld a, [wSoundID]
	cp NOISE_INSTRUMENTS_END
	jr nc, .notNoiseInstrument
	ret
.notNoiseInstrument
;>                 replace = playing <= noise_end  # while a drum may always be replaced
	ld a, [hl]
	cp NOISE_INSTRUMENTS_END
	jr z, .playChannel
	jr c, .playChannel
.notNoiseChannel
;>             if not (ch == CHAN8 and replace) and wSoundID > playing:
;>                 return                          # a more important effect (lower ID) plays there
	ld a, [wSoundID]
	cp [hl]
	jr z, .playChannel
	jr c, .playChannel
	ret
.playChannel
;>         # (a = 0 for the clearing below)
	xor a
;>         j = 2 * ch                              # the pointer tables have 2 bytes per channel
	push de
	ld h, d
	ld l, e
	add hl, hl
	ld d, h
	ld e, l
;>         wChannelReturnAddresses[j] = 0
;>         wChannelReturnAddresses[j + 1] = 0
	ld hl, wChannelReturnAddresses
	add hl, de
	ld [hli], a
	ld [hl], a
;>         wChannelCommandPointers[j] = 0
;>         wChannelCommandPointers[j + 1] = 0
	ld hl, wChannelCommandPointers
	add hl, de
	ld [hli], a
	ld [hl], a
	pop de
;>         wChannelSoundIDs[ch] = 0
;>         wChannelFlags1[ch] = 0
	ld hl, wChannelSoundIDs
	add hl, de
	ld [hl], a
	ld hl, wChannelFlags1
	add hl, de
	ld [hl], a
;>         wChannelDutyCycles[ch] = 0
;>         wChannelDutyCyclePatterns[ch] = 0
	ld hl, wChannelDutyCycles
	add hl, de
	ld [hl], a
	ld hl, wChannelDutyCyclePatterns
	add hl, de
	ld [hl], a
;>         wChannelVibratoDelayCounters[ch] = 0
;>         wChannelVibratoExtents[ch] = 0
	ld hl, wChannelVibratoDelayCounters
	add hl, de
	ld [hl], a
	ld hl, wChannelVibratoExtents
	add hl, de
	ld [hl], a
;>         wChannelVibratoRates[ch] = 0
;>         wChannelFrequencyLowBytes[ch] = 0
	ld hl, wChannelVibratoRates
	add hl, de
	ld [hl], a
	ld hl, wChannelFrequencyLowBytes
	add hl, de
	ld [hl], a
;>         wChannelVibratoDelayCounterReloadValues[ch] = 0
;>         wChannelPitchSlideLengthModifiers[ch] = 0
	ld hl, wChannelVibratoDelayCounterReloadValues
	add hl, de
	ld [hl], a
	ld hl, wChannelPitchSlideLengthModifiers
	add hl, de
	ld [hl], a
;>         wChannelPitchSlideFrequencySteps[ch] = 0
;>         wChannelPitchSlideFrequencyStepsFractionalPart[ch] = 0
	ld hl, wChannelPitchSlideFrequencySteps
	add hl, de
	ld [hl], a
	ld hl, wChannelPitchSlideFrequencyStepsFractionalPart
	add hl, de
	ld [hl], a
;>         wChannelPitchSlideCurrentFrequencyFractionalPart[ch] = 0
;>         wChannelPitchSlideCurrentFrequencyHighBytes[ch] = 0
	ld hl, wChannelPitchSlideCurrentFrequencyFractionalPart
	add hl, de
	ld [hl], a
	ld hl, wChannelPitchSlideCurrentFrequencyHighBytes
	add hl, de
	ld [hl], a
;>         wChannelPitchSlideCurrentFrequencyLowBytes[ch] = 0
;>         wChannelPitchSlideTargetFrequencyHighBytes[ch] = 0
	ld hl, wChannelPitchSlideCurrentFrequencyLowBytes
	add hl, de
	ld [hl], a
	ld hl, wChannelPitchSlideTargetFrequencyHighBytes
	add hl, de
	ld [hl], a
;>         wChannelPitchSlideTargetFrequencyLowBytes[ch] = 0
;>         wChannelFlags2[ch] = 0
	ld hl, wChannelPitchSlideTargetFrequencyLowBytes
	add hl, de
	ld [hl], a
	ld hl, wChannelFlags2
	add hl, de
	ld [hl], a
;>         wChannelLoopCounters[ch] = 1
	ld a, $1
	ld hl, wChannelLoopCounters
	add hl, de
	ld [hl], a
;>         wChannelNoteDelayCounters[ch] = 1
;>         wChannelNoteSpeeds[ch] = 1
	ld hl, wChannelNoteDelayCounters
	add hl, de
	ld [hl], a
	ld hl, wChannelNoteSpeeds
	add hl, de
	ld [hl], a
;>         if ch == CHAN5:
;>             rAUD1SWEEP = AUD1SWEEP_DOWN         # sweep off
	ld a, e
	cp CHAN5
	jr nz, .skipSweepDisable
	ld a, AUD1SWEEP_DOWN
	ldh [rAUD1SWEEP], a ; sweep off
.skipSweepDisable
;=@loop
	ld a, c
	and a
	jp z, .playSoundCommon
	dec c
	jp .sfxChannelLoop

.stopAllAudio
;> else:                                           # stop everything
;>     rAUDENA = AUDENA_ON
	ld a, AUDENA_ON
	ldh [rAUDENA], a ; sound hardware on
;>     rAUD3ENA = AUDENA_ON
	ldh [rAUD3ENA], a ; wave playback on
;>     rAUDTERM = 0
	xor a
	ldh [rAUDTERM], a ; no sound output
;>     rAUD3LEVEL = 0
	ldh [rAUD3LEVEL], a ; mute channel 3 (wave channel)
;>     rAUD1SWEEP = AUD1SWEEP_DOWN
	ld a, AUD1SWEEP_DOWN
	ldh [rAUD1SWEEP], a ; sweep off
;>     rAUD1ENV = AUD1SWEEP_DOWN                   # (the same value: volume 0)
	ldh [rAUD1ENV], a ; mute channel 1 (pulse channel 1)
;>     rAUD2ENV = AUD1SWEEP_DOWN
	ldh [rAUD2ENV], a ; mute channel 2 (pulse channel 2)
;>     rAUD4ENV = AUD1SWEEP_DOWN
	ldh [rAUD4ENV], a ; mute channel 4 (noise channel)
;>     rAUD1HIGH = AUD1HIGH_LENGTH_ON
	ld a, AUD1HIGH_LENGTH_ON
	ldh [rAUD1HIGH], a ; counter mode
;>     rAUD2HIGH = AUD1HIGH_LENGTH_ON
	ldh [rAUD2HIGH], a
;>     rAUD4GO = AUD1HIGH_LENGTH_ON
	ldh [rAUD4GO], a
;>     rAUDVOL = 0x77
	ld a, $77
	ldh [rAUDVOL], a ; full volume
;>     wUnusedMusicByte = 0
	xor a
	ld [wUnusedMusicByte], a
;>     wDisableChannelOutputWhenSfxEnds = 0
	ld [wDisableChannelOutputWhenSfxEnds], a
;>     wMuteAudioAndPauseMusic = 0
	ld [wMuteAudioAndPauseMusic], a
;>     wMusicTempo[1] = 0
	ld [wMusicTempo + 1], a
;>     wSfxTempo[1] = 0
	ld [wSfxTempo + 1], a
;>     wMusicWaveInstrument = 0
	ld [wMusicWaveInstrument], a
;>     wSfxWaveInstrument = 0
	ld [wSfxWaveInstrument], a
;>     fill(wChannelCommandPointers, 0, 0xA0)      # every channel variable up to the note timers
	ld d, $a0
	ld hl, wChannelCommandPointers
	call .FillMem
;>     fill(wChannelNoteDelayCounters, 1, 0x18)    # note timers, loop counters, note speeds
	ld a, $1
	ld d, $18
	ld hl, wChannelNoteDelayCounters
	call .FillMem
;>     wMusicTempo[0] = 1
	ld [wMusicTempo], a
;>     wSfxTempo[0] = 1
	ld [wSfxTempo], a
;>     wStereoPanning = 0xFF
;>     return
	ld a, $ff
	ld [wStereoPanning], a
	ret

; fills d bytes at hl with a
.FillMem
;> # .FillMem is the fill() used above: d bytes at hl set to a
	ld b, d
.loop
	ld [hli], a
	dec b
	jr nz, .loop
	ret

.playSoundCommon
;> sound = wSoundID
	ld a, [wSoundID]
;> i = 3 * sound
	ld l, a
	ld e, a
	ld h, 0
	ld d, h
	add hl, hl
	add hl, de
;> header = (SFX_Headers_2 + i) & 0xFFFF
	ld de, SFX_Headers_2
	add hl, de
;> p = header
	ld e, l
	ld d, h
	ld hl, wChannelCommandPointers
;> n = mem[p] >> 6                                 # the number of channels - 1
	ld a, [de] ; get channel number
	ld b, a
	rlca
	rlca
	and $3
	ld c, a
;> ch = mem[p] & 0xF                               # the first entry's channel
	ld a, b
	and $f
;> channels = n + 1
	ld b, c
	inc b
;> p += 1
	inc de
;> slot = 0                                        # which channel's pointer the next entry fills
	ld c, 0
.commandPointerLoop
;>@each for _ in range(channels):
;>     while slot != ch:
	cp c
	jr z, .next
;>         slot = (slot + 1) & 0xFF
	inc c
	inc hl
	inc hl
	jr .commandPointerLoop
.next
;>     # (the slot, the counter and ch are kept)
	push hl
	push bc
	push af
;>     wChannelSoundIDs[ch] = wSoundID
	ld b, 0
	ld c, a
	ld hl, wChannelSoundIDs
	add hl, bc
	ld a, [wSoundID]
	ld [hl], a
;>     if ch >= CHAN4:
;>         wChannelFlags1[ch] = wChannelFlags1[ch] | 1 << BIT_NOISE_OR_SFX
	pop af
	cp CHAN4
	jr c, .skipSettingFlag
	ld hl, wChannelFlags1
	add hl, bc
	set BIT_NOISE_OR_SFX, [hl]
.skipSettingFlag
;>     mem[wChannelCommandPointers + 2 * slot] = mem[p]          # the channel's start address
	pop bc
	pop hl
	ld a, [de] ; get channel pointer
	ld [hli], a
;>     mem[wChannelCommandPointers + 2 * slot + 1] = mem[p + 1]
	inc de
	ld a, [de]
	ld [hli], a
	inc de
;>     slot = (slot + 1) & 0xFF
	inc c
;=@each
	dec b
	ld a, b
	and a
;>     ch = mem[p + 2]                             # the next entry's channel byte
;>     p += 3
	ld a, [de]
	inc de
;=@each
	jr nz, .commandPointerLoop
;>@cry if (SFX_Cry00_1 - SFX_Headers_1) // 3 <= wSoundID < ((SFX_Cry25_1 - SFX_Headers_1) // 3 + 3):     # a cry
	ld a, [wSoundID]
	cp CRY_SFX_START
	jr nc, .maybeCry
	jr .done
.maybeCry
;=@cry
	ld a, [wSoundID]
	cp CRY_SFX_END
	jr z, .done
	jr c, .cry
	jr .done
.cry
;>     for i in range(CHAN5, CHAN8 + 1):           # claims all four effect channels
;>         wChannelSoundIDs[i] = wSoundID
	ld hl, wChannelSoundIDs + CHAN5
	ld [hli], a
	ld [hli], a
	ld [hli], a
	ld [hl], a
;>     wChannelCommandPointers[2 * CHAN7] = Audio2_CryRet & 0xFF   # its wave channel ends at once
;>     wChannelCommandPointers[2 * CHAN7 + 1] = Audio2_CryRet >> 8
	ld hl, wChannelCommandPointers + CHAN7 * 2 ; sfx wave channel pointer
	ld de, Audio2_CryRet
	ld [hl], e
	inc hl
	ld [hl], d ; overwrite pointer to point to sound_ret
;>     if not wSavedVolume:
;>         wSavedVolume = rAUDVOL                  # kept for when the cry ends
	ld a, [wSavedVolume]
	and a
	jr nz, .done
	ldh a, [rAUDVOL]
	ld [wSavedVolume], a
;>         rAUDVOL = 0x77                          # full volume
	ld a, $77
	ldh [rAUDVOL], a ; full volume
.done
	ret

;@ path: audio/engine_2
Audio2_CryRet:
	db sound_ret_cmd

;@ path: audio/engine_2
Audio2_HWChannelBaseAddresses:
; the low bytes of each HW channel's base address
	db HW_CH1_BASE, HW_CH2_BASE, HW_CH3_BASE, HW_CH4_BASE ; channels 0-3
	db HW_CH1_BASE, HW_CH2_BASE, HW_CH3_BASE, HW_CH4_BASE ; channels 4-7

;@ path: audio/engine_2
Audio2_HWChannelDisableMasks:
	db HW_CH1_DISABLE_MASK, HW_CH2_DISABLE_MASK, HW_CH3_DISABLE_MASK, HW_CH4_DISABLE_MASK ; channels 0-3
	db HW_CH1_DISABLE_MASK, HW_CH2_DISABLE_MASK, HW_CH3_DISABLE_MASK, HW_CH4_DISABLE_MASK ; channels 4-7

;@ path: audio/engine_2
Audio2_HWChannelEnableMasks:
	db HW_CH1_ENABLE_MASK, HW_CH2_ENABLE_MASK, HW_CH3_ENABLE_MASK, HW_CH4_ENABLE_MASK ; channels 0-3
	db HW_CH1_ENABLE_MASK, HW_CH2_ENABLE_MASK, HW_CH3_ENABLE_MASK, HW_CH4_ENABLE_MASK ; channels 4-7

;@ path: audio/engine_2
Audio2_Pitches:
; This file is INCLUDEd three times, once in each audio engine.

	dw $F82C ; C_
	dw $F89D ; C#
	dw $F907 ; D_
	dw $F96B ; D#
	dw $F9CA ; E_
	dw $FA23 ; F_
	dw $FA77 ; F#
	dw $FAC7 ; G_
	dw $FB12 ; G#
	dw $FB58 ; A_
	dw $FB9B ; A#
	dw $FBDA ; B_
;@ path: audio/poke_flute
;@ def Music_PokeFluteInBattle()
;@ The Poke Flute in battle: start the "caught" jingle (after the current effect), then switch its three
;@ channels over to the flute melody.
;@ test: skip waits for the current sound effect to end
Music_PokeFluteInBattle::
	; begin playing the "caught mon" sound effect
;> PlaySoundWaitForCurrent((SFX_Caught_Mon - SFX_Headers_1) // 3)
	ld a, SFX_CAUGHT_MON
	call PlaySoundWaitForCurrent
	; then immediately overwrite the channel pointers
;> ptr = Audio2_OverwriteChannelPointer(wChannelCommandPointers + 2 * CHAN5, SFX_Pokeflute_Ch5)
	ld hl, wChannelCommandPointers + CHAN5 * 2
	ld de, SFX_Pokeflute_Ch5
	call Audio2_OverwriteChannelPointer
;> ptr = Audio2_OverwriteChannelPointer(ptr, SFX_Pokeflute_Ch6)
	ld de, SFX_Pokeflute_Ch6
	call Audio2_OverwriteChannelPointer
;> Audio2_OverwriteChannelPointer(ptr, SFX_Pokeflute_Ch7)    # it follows
	ld de, SFX_Pokeflute_Ch7

;@ path: audio/poke_flute
;@ def Audio2_OverwriteChannelPointer(ptr: hl, address: de) -> hl
;@ Point a channel at other sound data: store `address` at `ptr` and move on to the next channel's pointer.
;@ test: ptr = wChannelCommandPointers + 2 * rand(0, 7)
Audio2_OverwriteChannelPointer:
;> mem16[ptr] = address
;> return ptr + 2
	ld a, e
	ld [hli], a
	ld a, d
	ld [hli], a
	ret


SECTION "Audio Engine 3", ROMX

;@ path: audio/pokedex_rating_sfx
;@ def PlayPokedexRatingSfx()
;@ The jingle after Professor Oak's Pokedex rating: the more Pokemon owned, the better the jingle
;@ (thresholds 10, 40, 60, 90, 120, 150). Afterwards the area's music comes back.
;@ test: skip waits for the current sound effect to end
PlayPokedexRatingSfx::
;> owned = hDexRatingNumMonsOwned
	ldh a, [hDexRatingNumMonsOwned]
;> i = 0
	ld c, $0
	ld hl, OwnedMonValues
.getSfxPointer
;>@lp while owned >= mem[OwnedMonValues + i]:
	cp [hl]
	jr c, .gotSfxPointer
;>     i = i + 1
	inc c
	inc hl
;=@lp
	jr .getSfxPointer
.gotSfxPointer
;> wNewSoundID = SFX_STOP_ALL_MUSIC
	push bc
	ld a, SFX_STOP_ALL_MUSIC
	ld [wNewSoundID], a
;> PlaySoundWaitForCurrent(SFX_STOP_ALL_MUSIC)
	call PlaySoundWaitForCurrent
;> p = PokedexRatingSfxPointers + 2 * i         # sound ID and bank
	pop bc
	ld b, $0
	ld hl, PokedexRatingSfxPointers
	add hl, bc
	add hl, bc
;> PlayMusic(mem[p], mem[p + 1])
	ld a, [hli]
	ld c, [hl]
	call PlayMusic
;> PlayDefaultMusic()
	jp PlayDefaultMusic

;@ path: audio/pokedex_rating_sfx
PokedexRatingSfxPointers:
	db SFX_DENIED,         BANK(SFX_Denied_3)
	db SFX_POKEDEX_RATING, BANK(SFX_Pokedex_Rating_1)
	db SFX_GET_ITEM_1,     BANK(SFX_Get_Item1_1)
	db SFX_CAUGHT_MON,     BANK(SFX_Caught_Mon)
	db SFX_LEVEL_UP,       BANK(SFX_Level_Up)
	db SFX_GET_KEY_ITEM,   BANK(SFX_Get_Key_Item_1)
	db SFX_GET_ITEM_2,     BANK(SFX_Get_Item2_1)

;@ path: audio/pokedex_rating_sfx
OwnedMonValues:
	db 10, 40, 60, 90, 120, 150, $ff
; The third of three duplicated sound engines.

;@ path: audio/engine_3
;@ def Audio3_UpdateMusic()
;@ The sound engine's frame, for the sounds in this audio bank: every channel that is playing runs one
;@ frame. While the music is paused (wMuteAudioAndPauseMusic) the music channels are skipped, and the first
;@ time round all output is switched off; effects keep playing.
;@ test: [mem.__setitem__(wChannelFlags1 + i, mem[wChannelFlags1 + i] & ~(1 << BIT_PITCH_SLIDE_ON)) for i in range(8)]
Audio3_UpdateMusic::
;> for channel in range(CHAN1, CHAN8 + 1):
	ld c, CHAN1
.loop
;>     if not wChannelSoundIDs[channel]:
;>         continue
	ld b, 0
	ld hl, wChannelSoundIDs
	add hl, bc
	ld a, [hl]
	and a
	jr z, .nextChannel
;>     if channel < CHAN5 and wMuteAudioAndPauseMusic:
	ld a, c
	cp CHAN5
	jr nc, .applyAffects ; if sfx channel
	ld a, [wMuteAudioAndPauseMusic]
	and a
	jr z, .applyAffects
;>         if not wMuteAudioAndPauseMusic & 1 << BIT_MUTE_AUDIO:
	bit BIT_MUTE_AUDIO, a
	jr nz, .nextChannel
;>             wMuteAudioAndPauseMusic = wMuteAudioAndPauseMusic | 1 << BIT_MUTE_AUDIO
	set BIT_MUTE_AUDIO, a
	ld [wMuteAudioAndPauseMusic], a
;>             rAUDTERM = 0
	xor a ; disable all channels' output
	ldh [rAUDTERM], a
;>             rAUD3ENA = 0
	ldh [rAUD3ENA], a
;>             rAUD3ENA = AUD3ENA_ON
	ld a, AUD3ENA_ON
	ldh [rAUD3ENA], a
;>         continue
	jr .nextChannel
.applyAffects
;>     Audio3_ApplyMusicAffects(channel)
	call Audio3_ApplyMusicAffects
.nextChannel
	ld a, c
	inc c ; inc channel number
	cp CHAN8
	jr nz, .loop
	ret

; this routine checks flags for music effects currently applied
; to the channel and calls certain functions based on flags.
;@ path: audio/engine_3
;@ def Audio3_ApplyMusicAffects(channel: c)
;@ One frame of a channel: when its note is over, read on to the next note; otherwise count down and apply
;@ what changes during a note - the duty cycle pattern, a pitch slide, or vibrato (after its delay, the
;@ frequency swings above and below the note on alternate steps). A music channel an effect is using waits.
;@ test: channel = rand(0, 7)
;@ test: [mem.__setitem__(wChannelFlags1 + i, mem[wChannelFlags1 + i] & ~(1 << BIT_PITCH_SLIDE_ON)) for i in range(8)]
Audio3_ApplyMusicAffects:
;> delay = wChannelNoteDelayCounters[channel]
	ld b, $0
	ld hl, wChannelNoteDelayCounters ; delay until next note
	add hl, bc
	ld a, [hl]
;> if delay == 1:                                 # the note is over
;>     return Audio3_PlayNextNote(channel, 0)
	cp 1 ; if the delay is 1, play next note
	jp z, Audio3_PlayNextNote
;> wChannelNoteDelayCounters[channel] = (delay - 1) & 0xFF
	dec a ; otherwise, decrease the delay timer
	ld [hl], a
;> if channel < CHAN5:
	ld a, c
	cp CHAN5
	jr nc, .startChecks ; if a sfx channel
;>     if wChannelSoundIDs[CHAN5 + channel]:      # an effect is using its hardware channel
;>         return
	ld hl, wChannelSoundIDs + CHAN5
	add hl, bc
	ld a, [hl]
	and a
	jr z, .startChecks
	ret
.startChecks
;> if wChannelFlags1[channel] & 1 << BIT_ROTATE_DUTY_CYCLE:
	ld hl, wChannelFlags1
	add hl, bc
	bit BIT_ROTATE_DUTY_CYCLE, [hl]
	jr z, .checkForExecuteMusic
;>     Audio3_ApplyDutyCyclePattern(channel)
	call Audio3_ApplyDutyCyclePattern
.checkForExecuteMusic
;> if not wChannelFlags2[channel] & 1 << BIT_EXECUTE_MUSIC:
	ld b, 0
	ld hl, wChannelFlags2
	add hl, bc
	bit BIT_EXECUTE_MUSIC, [hl]
	jr nz, .checkForPitchSlide
;>     if wChannelFlags1[channel] & 1 << BIT_NOISE_OR_SFX:
;>         return                                 # an effect's own notes have no slides or vibrato
	ld hl, wChannelFlags1
	add hl, bc
	bit BIT_NOISE_OR_SFX, [hl]
	jr nz, .skipPitchSlideVibrato
.checkForPitchSlide
;> if wChannelFlags1[channel] & 1 << BIT_PITCH_SLIDE_ON:
	ld hl, wChannelFlags1
	add hl, bc
	bit BIT_PITCH_SLIDE_ON, [hl]
	jr z, .checkVibratoDelay
;>     return Audio3_ApplyPitchSlide(channel, 0)
	jp Audio3_ApplyPitchSlide
.checkVibratoDelay
;> if wChannelVibratoDelayCounters[channel]:     # the vibrato waits for its delay
	ld hl, wChannelVibratoDelayCounters
	add hl, bc
	ld a, [hl]
	and a ; check if delay is over
	jr z, .checkForVibrato
;>     wChannelVibratoDelayCounters[channel] = wChannelVibratoDelayCounters[channel] - 1
	dec [hl] ; otherwise, dec delay
.skipPitchSlideVibrato
;>     return
	ret
.checkForVibrato
;> extent = wChannelVibratoExtents[channel]
	ld hl, wChannelVibratoExtents
	add hl, bc
	ld a, [hl]
;> if not extent:                                # no vibrato
;>     return
	and a
	jr nz, .vibrato
	ret ; no vibrato
.vibrato
;> rate = wChannelVibratoRates[channel]         # high nibble: reload value, low nibble: counter
	ld d, a
	ld hl, wChannelVibratoRates
	add hl, bc
	ld a, [hl]
;> if rate & 0xF:
	and $f
	and a
	jr z, .applyVibrato
;>     wChannelVibratoRates[channel] = rate - 1
;>     return
	dec [hl] ; decrement counter
	ret
.applyVibrato
;> wChannelVibratoRates[channel] = rate | rate >> 4  # reload the counter
	ld a, [hl]
	swap [hl]
	or [hl]
	ld [hl], a ; reload the counter
;> low = wChannelFrequencyLowBytes[channel]     # the note's frequency
	ld hl, wChannelFrequencyLowBytes
	add hl, bc
	ld e, [hl] ; get note pitch
;> if wChannelFlags1[channel] & 1 << BIT_VIBRATO_DIRECTION:   # up and down on alternate steps
	ld hl, wChannelFlags1
	add hl, bc
; This is the only code that sets/resets the vibrato direction bit, so it
; continuously alternates which path it takes.
	bit BIT_VIBRATO_DIRECTION, [hl]
	jr z, .unset
;>     wChannelFlags1[channel] = wChannelFlags1[channel] & ~(1 << BIT_VIBRATO_DIRECTION) & 0xFF
	res BIT_VIBRATO_DIRECTION, [hl]
;>     below = extent & 0xF                      # the extent below the note
	ld a, d
	and $f
	ld d, a
;>     low = max(low - below, 0)
	ld a, e
	sub d
	jr nc, .noCarry
	ld a, 0
.noCarry
	jr .done
.unset
;> else:
;>     wChannelFlags1[channel] = wChannelFlags1[channel] | 1 << BIT_VIBRATO_DIRECTION
	set BIT_VIBRATO_DIRECTION, [hl]
;>     above = extent >> 4                       # the extent above the note
	ld a, d
	and $f0
	swap a
;>     low = min(low + above, 0xFF)
	add e
	jr nc, .done
	ld a, $ff
.done
;> mem[Audio3_GetRegisterPointer(REG_FREQUENCY_LO, channel)] = low
	ld d, a
	ld b, REG_FREQUENCY_LO
	call Audio3_GetRegisterPointer
	ld [hl], d
	ret

; this routine executes all music commands that take up no time,
; like tempo changes, duty cycle changes etc. and doesn't return
; until the first note is reached
;@ path: audio/engine_3
;@ def Audio3_PlayNextNote(channel: c, zero: b)
;@ A note has ended: restart the vibrato delay, end any pitch slide, and run the channel's commands up to
;@ its next note. b is 0 on entry.
;@ test: channel = rand(0, 7); zero = 0
;@ test: [mem.__setitem__(wChannelFlags1 + i, mem[wChannelFlags1 + i] & ~(1 << BIT_PITCH_SLIDE_ON)) for i in range(8)]
Audio3_PlayNextNote:
; reload the vibrato delay counter
;> wChannelVibratoDelayCounters[channel] = wChannelVibratoDelayCounterReloadValues[channel]
	ld hl, wChannelVibratoDelayCounterReloadValues
	add hl, bc
	ld a, [hl]
	ld hl, wChannelVibratoDelayCounters
	add hl, bc
	ld [hl], a

;> # the pitch slide is over
;> wChannelFlags1[channel] = wChannelFlags1[channel] & ~(1 << BIT_PITCH_SLIDE_ON | 1 << BIT_PITCH_SLIDE_DECREASING) & 0xFF
	ld hl, wChannelFlags1
	add hl, bc
	res BIT_PITCH_SLIDE_ON, [hl]
	res BIT_PITCH_SLIDE_DECREASING, [hl]
;> Audio3_sound_ret(channel)
	call Audio3_sound_ret
	ret

;@ path: audio/engine_3
;@ def Audio3_sound_ret(channel: c)
;@ Read and run a channel's next command. This is where the command chain starts: each handler below
;@ checks for its command and passes anything else on to the next one, until a note ends the frame's work.
;@ The sound_ret command itself returns from a sound_call, or ends the channel: its output is switched
;@ off, a finished cry restores the volume, and the channel's sound ID is cleared.
;@ test: channel = rand(0, 7)
;@ test: [mem.__setitem__(wChannelFlags1 + i, mem[wChannelFlags1 + i] & ~(1 << BIT_PITCH_SLIDE_ON)) for i in range(8)]
Audio3_sound_ret:
;> cmd = Audio3_GetNextMusicByte(channel)
	call Audio3_GetNextMusicByte
	ld d, a
;> if cmd != sound_ret_cmd:
;>     return Audio3_sound_call(channel, cmd, cmd)    # not this command: on down the chain
	cp sound_ret_cmd
	jp nz, Audio3_sound_call
;> if wChannelFlags1[channel] & 1 << BIT_SOUND_CALL:   # the end of a sound_call
	ld b, 0
	ld hl, wChannelFlags1
	add hl, bc
	bit BIT_SOUND_CALL, [hl]
	jr nz, .returnFromCall
;>@rf     wChannelFlags1[channel] = wChannelFlags1[channel] & ~(1 << BIT_SOUND_CALL) & 0xFF
;>@ri     i = 2 * channel & 0xFF                     # both tables hold 2-byte pointers
;>@rc     cur = addr(wChannelCommandPointers) + i
;>@rs     saved = addr(wChannelReturnAddresses) + i
;>@rp     mem[cur] = mem[saved]                      # back to the command after the call
;>@rp2     mem[cur + 1] = mem[saved + 1]
;>@rr     return Audio3_sound_ret(channel)            # and run it
;> if channel < CHAN4:
;>     disable = True                              # a music channel has ended: its output goes off
	ld a, c
	cp CHAN4
	jr nc, .noiseOrSfxChannel
	jr .disableChannelOutput
.noiseOrSfxChannel
;> else:                                           # an effect has ended: the hardware goes back to the music
;>     wChannelFlags1[channel] = wChannelFlags1[channel] & ~(1 << BIT_NOISE_OR_SFX) & 0xFF
	res BIT_NOISE_OR_SFX, [hl]
;>     wChannelFlags2[channel] = wChannelFlags2[channel] & ~(1 << BIT_EXECUTE_MUSIC) & 0xFF
	ld hl, wChannelFlags2
	add hl, bc
	res BIT_EXECUTE_MUSIC, [hl]
;>     if channel == CHAN7:
	cp CHAN7
	jr nz, .skipSfxChannel3
; restart hardware channel 3 (wave channel) output
;>         rAUD3ENA = AUD3ENA_OFF
	ld a, AUD3ENA_OFF
	ldh [rAUD3ENA], a
;>         rAUD3ENA = AUD3ENA_ON
	ld a, AUD3ENA_ON
	ldh [rAUD3ENA], a
.skipSfxChannel3
;>     disable = channel == CHAN7 and wDisableChannelOutputWhenSfxEnds != 0
	jr nz, .dontDisable
	ld a, [wDisableChannelOutputWhenSfxEnds]
	and a
	jr z, .dontDisable
;>     if disable:
;>         wDisableChannelOutputWhenSfxEnds = 0
	xor a
	ld [wDisableChannelOutputWhenSfxEnds], a
	jr .disableChannelOutput
.dontDisable
;=@cut
	jr .afterDisable
.returnFromCall
;=@rf
	res BIT_SOUND_CALL, [hl]
;=@ri
	ld d, $0
	ld a, c
	add a
	ld e, a
;=@rc
	ld hl, wChannelCommandPointers
	add hl, de
	push hl ; store current channel address
;=@rs
	ld hl, wChannelReturnAddresses
	add hl, de
	ld e, l
	ld d, h
	pop hl
;=@rp
	ld a, [de]
	ld [hli], a
;=@rp2
	inc de
	ld a, [de]
	ld [hl], a ; loads channel address to return to
;=@rr
	jp Audio3_sound_ret
.disableChannelOutput
;>@cut if disable:
;>     rAUDTERM = rAUDTERM & mem[Audio3_HWChannelDisableMasks + channel]
	ld hl, Audio3_HWChannelDisableMasks
	add hl, bc
	ldh a, [rAUDTERM]
	and [hl]
	ldh [rAUDTERM], a
.afterDisable
;>@cry if (SFX_Cry00_1 - SFX_Headers_1) // 3 <= wChannelSoundIDs[CHAN5] < ((SFX_Cry25_1 - SFX_Headers_1) // 3 + 3):   # a cry is playing
	ld a, [wChannelSoundIDs + CHAN5]
	cp CRY_SFX_START
	jr nc, .maybeCry
	jr .skipCry
.maybeCry
;=@cry
	ld a, [wChannelSoundIDs + CHAN5]
	cp CRY_SFX_END
	jr z, .skipCry
	jr c, .cry
	jr .skipCry
.cry
;>     if channel != CHAN5 and Audio3_GoBackOneCommandIfCry(channel):
;>         return                                  # the cry's other channels wait for channel 5
	ld a, c
	cp CHAN5
	jr z, .skipRewind
	call Audio3_GoBackOneCommandIfCry
	ret c
.skipRewind
;>     rAUDVOL = wSavedVolume                      # the cry is over: the volume from before it
	ld a, [wSavedVolume]
	ldh [rAUDVOL], a
;>     wSavedVolume = 0
	xor a
	ld [wSavedVolume], a
.skipCry
;> wChannelSoundIDs[channel] = 0                   # the channel is free
	ld hl, wChannelSoundIDs
	add hl, bc
	ld [hl], b
	ret

;@ path: audio/engine_3
;@ def Audio3_sound_call(channel: c, cmd: a, cmd_d: d)
;@ sound_call: remember where the channel is and continue at the address that follows (a subroutine of
;@ sound data). The command byte arrives in both a and d.
;@ test: cmd = sound_call_cmd if rand(0, 1) else rand(0, 255); cmd_d = cmd; channel = rand(0, 7)
;@ test: [mem.__setitem__(wChannelFlags1 + i, mem[wChannelFlags1 + i] & ~(1 << BIT_PITCH_SLIDE_ON)) for i in range(8)]
Audio3_sound_call:
;> if cmd != sound_call_cmd:
;>     return Audio3_sound_loop(channel, cmd, cmd_d)
	cp sound_call_cmd
	jp nz, Audio3_sound_loop
;> lo = Audio3_GetNextMusicByte(channel)        # the address to call
	call Audio3_GetNextMusicByte
	push af
;> hi = Audio3_GetNextMusicByte(channel)
	call Audio3_GetNextMusicByte
	ld d, a
	pop af
	ld e, a
	push de ; store pointer
;> i = 2 * channel & 0xFF
	ld d, $0
	ld a, c
	add a
	ld e, a
;> cur = addr(wChannelCommandPointers) + i
	ld hl, wChannelCommandPointers
	add hl, de
	push hl
;> saved = addr(wChannelReturnAddresses) + i
	ld hl, wChannelReturnAddresses
	add hl, de
	ld e, l
	ld d, h
	pop hl
;> mem[saved] = mem[cur]                       # where to come back to
	ld a, [hli]
	ld [de], a
;> mem[saved + 1] = mem[cur + 1]
	inc de
	ld a, [hld]
	ld [de], a ; copy current channel address
;> mem[cur] = lo
	pop de
	ld [hl], e
;> mem[cur + 1] = hi
	inc hl
	ld [hl], d ; overwrite current address with pointer
;> wChannelFlags1[channel] = wChannelFlags1[channel] | 1 << BIT_SOUND_CALL
	ld b, $0
	ld hl, wChannelFlags1
	add hl, bc
	set BIT_SOUND_CALL, [hl] ; set the call flag
;> return Audio3_sound_ret(channel)
	jp Audio3_sound_ret

;@ path: audio/engine_3
;@ def Audio3_sound_loop(channel: c, cmd: a, cmd_d: d)
;@ sound_loop count, address: jump back `count` times (0 = forever), then go on after the command.
;@ test: cmd = sound_loop_cmd if rand(0, 1) else rand(0, 255); cmd_d = cmd; channel = rand(0, 7)
;@ test: [mem.__setitem__(wChannelFlags1 + i, mem[wChannelFlags1 + i] & ~(1 << BIT_PITCH_SLIDE_ON)) for i in range(8)]
Audio3_sound_loop:
;> if cmd != sound_loop_cmd:
;>     return Audio3_note_type(channel, cmd, cmd_d)
	cp sound_loop_cmd
	jp nz, Audio3_note_type
;> count = Audio3_GetNextMusicByte(channel)
	call Audio3_GetNextMusicByte
	ld e, a
;> if count:
	and a
	jr z, .infiniteLoop
;>     if wChannelLoopCounters[channel] == count:
	ld b, 0
	ld hl, wChannelLoopCounters
	add hl, bc
	ld a, [hl]
	cp e
	jr nz, .loopAgain
;>         wChannelLoopCounters[channel] = 1      # done: skip the address
	ld a, $1 ; if no more loops to make,
	ld [hl], a
;>         Audio3_GetNextMusicByte(channel)
	call Audio3_GetNextMusicByte ; skip pointer
;>         Audio3_GetNextMusicByte(channel)
	call Audio3_GetNextMusicByte
;>         return Audio3_sound_ret(channel)
	jp Audio3_sound_ret
.loopAgain ; inc loop count
;>     wChannelLoopCounters[channel] = (wChannelLoopCounters[channel] + 1) & 0xFF
	inc a
	ld [hl], a
	; fall through
.infiniteLoop ; overwrite current address with pointer
;> lo = Audio3_GetNextMusicByte(channel)
	call Audio3_GetNextMusicByte
	push af
;> hi = Audio3_GetNextMusicByte(channel)
	call Audio3_GetNextMusicByte
	ld b, a
;> i = 2 * channel & 0xFF
	ld d, $0
	ld a, c
	add a
	ld e, a
;> wChannelCommandPointers[i] = lo
	ld hl, wChannelCommandPointers
	add hl, de
	pop af
	ld [hli], a
;> wChannelCommandPointers[i + 1] = hi
	ld [hl], b
;> return Audio3_sound_ret(channel)
	jp Audio3_sound_ret

;@ path: audio/engine_3
;@ def Audio3_note_type(channel: c, cmd: a, cmd_d: d)
;@ note_type speed, volume, fade: the low nibble is the note speed; then one byte of volume and fade (none on
;@ the noise channel). On the wave channel the byte picks the wave instrument and a volume level instead.
;@ test: cmd = note_type_cmd | rand(0, 15) if rand(0, 1) else rand(0, 255); cmd_d = cmd; channel = rand(0, 7)
;@ test: [mem.__setitem__(wChannelFlags1 + i, mem[wChannelFlags1 + i] & ~(1 << BIT_PITCH_SLIDE_ON)) for i in range(8)]
Audio3_note_type:
;> if cmd & 0xF0 != note_type_cmd:
;>     return Audio3_toggle_perfect_pitch(channel, cmd_d)
	and $f0
	cp note_type_cmd
	jp nz, Audio3_toggle_perfect_pitch
;> wChannelNoteSpeeds[channel] = cmd_d & 0xF
	ld a, d
	and $f
	ld b, $0
	ld hl, wChannelNoteSpeeds
	add hl, bc
	ld [hl], a ; store low nibble as speed
;> if channel != CHAN4:                          # the noise channel has no parameter byte
	ld a, c
	cp CHAN4
	jr z, .noiseChannel ; noise channel has 0 params
;>     param = Audio3_GetNextMusicByte(channel)
	call Audio3_GetNextMusicByte
	ld d, a
;>     if channel == CHAN3:
	ld a, c
	cp CHAN3
	jr z, .musicChannel3
;>@mw         slot = addr(wMusicWaveInstrument)
;>     elif channel == CHAN7:
	cp CHAN7
	jr nz, .skipChannel3
;>         slot = addr(wSfxWaveInstrument)
	ld hl, wSfxWaveInstrument
	jr .channel3
.musicChannel3
;=@mw
	ld hl, wMusicWaveInstrument
.channel3
;>     if channel in (CHAN3, CHAN7):              # the wave channel
;>         mem[slot] = param & 0xF                # the wave instrument
	ld a, d
	and $f
	ld [hl], a ; store low nibble of param as wave instrument
;>         param = (param & 0x30) << 1            # and a volume level
	ld a, d
	and $30
	sla a
	ld d, a
	; fall through

	; if channel 3, store high nibble as volume
	; else, store volume (high nibble) and fade (low nibble)
.skipChannel3
;>     wChannelVolumes[channel] = param
	ld b, 0
	ld hl, wChannelVolumes
	add hl, bc
	ld [hl], d
.noiseChannel
;> return Audio3_sound_ret(channel)
	jp Audio3_sound_ret

;@ path: audio/engine_3
;@ def Audio3_toggle_perfect_pitch(channel: c, cmd: d)
;@ toggle_perfect_pitch: from now on play every note one step higher (or stop doing so).
;@ test: cmd = toggle_perfect_pitch_cmd if rand(0, 1) else rand(0, 255); channel = rand(0, 7)
;@ test: [mem.__setitem__(wChannelFlags1 + i, mem[wChannelFlags1 + i] & ~(1 << BIT_PITCH_SLIDE_ON)) for i in range(8)]
Audio3_toggle_perfect_pitch:
;> if cmd != toggle_perfect_pitch_cmd:
;>     return Audio3_vibrato(channel, cmd, cmd)
	ld a, d
	cp toggle_perfect_pitch_cmd
	jr nz, Audio3_vibrato
;> wChannelFlags1[channel] = wChannelFlags1[channel] ^ 1 << BIT_PERFECT_PITCH
	ld b, 0
	ld hl, wChannelFlags1
	add hl, bc
	ld a, [hl]
	xor 1 << BIT_PERFECT_PITCH
	ld [hl], a
;> return Audio3_sound_ret(channel)
	jp Audio3_sound_ret

;@ path: audio/engine_3
;@ def Audio3_vibrato(channel: c, cmd: a, cmd_d: d)
;@ vibrato delay, extent and rate: after `delay` frames the pitch wobbles by `extent` steps around the note,
;@ split into half above and half below.
;@ test: cmd = vibrato_cmd if rand(0, 1) else rand(0, 255); cmd_d = cmd; channel = rand(0, 7)
;@ test: [mem.__setitem__(wChannelFlags1 + i, mem[wChannelFlags1 + i] & ~(1 << BIT_PITCH_SLIDE_ON)) for i in range(8)]
Audio3_vibrato:
;> if cmd != vibrato_cmd:
;>     return Audio3_pitch_slide(channel, cmd, cmd_d)
	cp vibrato_cmd
	jr nz, Audio3_pitch_slide
;> delay = Audio3_GetNextMusicByte(channel)
	call Audio3_GetNextMusicByte
;> wChannelVibratoDelayCounters[channel] = delay
	ld b, 0
	ld hl, wChannelVibratoDelayCounters
	add hl, bc
	ld [hl], a ; store delay
;> wChannelVibratoDelayCounterReloadValues[channel] = delay
	ld hl, wChannelVibratoDelayCounterReloadValues
	add hl, bc
	ld [hl], a ; store delay
;> param = Audio3_GetNextMusicByte(channel)
	call Audio3_GetNextMusicByte
	ld d, a

; The high nybble of the command byte is the extent of the vibrato.
; Let n be the extent.
; The upper nybble of the channel's byte in the wChannelVibratoExtents
; array will store the extent above the note: (n / 2) + (n % 2).
; The lower nybble will store the extent below the note: (n / 2).
; These two values add to the total extent, n.
;> extent = param >> 4
	and $f0
	swap a
;> half = extent // 2                           # below the note
	ld b, 0
	ld hl, wChannelVibratoExtents
	add hl, bc
	srl a
	ld e, a
;> wChannelVibratoExtents[channel] = (half + extent % 2) << 4 | half   # above | below
	adc b
	swap a
	or e
	ld [hl], a

; The low nybble of the command byte is the rate of the vibrato.
; The high and low nybbles of the channel's byte in the wChannelVibratoRates
; array are both initialised to this value because the high nybble is the
; counter reload value and the low nybble is the counter itself, which should
; start at its value upon reload.
;> rate = param & 0xF
	ld a, d
	and $f
	ld d, a
;> wChannelVibratoRates[channel] = rate << 4 | rate      # reload value and counter
	ld hl, wChannelVibratoRates
	add hl, bc
	swap a
	or d
	ld [hl], a

;> return Audio3_sound_ret(channel)
	jp Audio3_sound_ret

;@ path: audio/engine_3
;@ def Audio3_pitch_slide(channel: c, cmd: a, cmd_d: d)
;@ pitch_slide length, octave and note: the next note slides towards this target pitch.
;@ test: cmd = pitch_slide_cmd if rand(0, 1) else rand(0, 255); cmd_d = cmd; channel = rand(0, 7)
;@ test: [mem.__setitem__(wChannelFlags1 + i, mem[wChannelFlags1 + i] & ~(1 << BIT_PITCH_SLIDE_ON)) for i in range(8)]
Audio3_pitch_slide:
;> if cmd != pitch_slide_cmd:
;>     return Audio3_duty_cycle(channel, cmd, cmd_d)
	cp pitch_slide_cmd
	jr nz, Audio3_duty_cycle
;> wChannelPitchSlideLengthModifiers[channel] = Audio3_GetNextMusicByte(channel)
	call Audio3_GetNextMusicByte
	ld b, 0
	ld hl, wChannelPitchSlideLengthModifiers
	add hl, bc
	ld [hl], a
;> target = Audio3_GetNextMusicByte(channel)
	call Audio3_GetNextMusicByte
	ld d, a
;> freq = Audio3_CalculateFrequency(target & 0xF, target >> 4)
	and $f0
	swap a
	ld b, a
	ld a, d
	and $f
	call Audio3_CalculateFrequency
;> wChannelPitchSlideTargetFrequencyHighBytes[channel] = freq >> 8
	ld b, 0
	ld hl, wChannelPitchSlideTargetFrequencyHighBytes
	add hl, bc
	ld [hl], d
;> wChannelPitchSlideTargetFrequencyLowBytes[channel] = freq & 0xFF
	ld hl, wChannelPitchSlideTargetFrequencyLowBytes
	add hl, bc
	ld [hl], e
;> wChannelFlags1[channel] = wChannelFlags1[channel] | 1 << BIT_PITCH_SLIDE_ON
	ld b, 0
	ld hl, wChannelFlags1
	add hl, bc
	set BIT_PITCH_SLIDE_ON, [hl]
;> return Audio3_note_length(channel, Audio3_GetNextMusicByte(channel))
	call Audio3_GetNextMusicByte
	ld d, a
	jp Audio3_note_length

;@ path: audio/engine_3
;@ def Audio3_duty_cycle(channel: c, cmd: a, cmd_d: d)
;@ duty_cycle n: the square wave's duty (0 = 12.5%, 1 = 25%, 2 = 50%, 3 = 75%).
;@ test: cmd = duty_cycle_cmd if rand(0, 1) else rand(0, 255); cmd_d = cmd; channel = rand(0, 7)
;@ test: [mem.__setitem__(wChannelFlags1 + i, mem[wChannelFlags1 + i] & ~(1 << BIT_PITCH_SLIDE_ON)) for i in range(8)]
Audio3_duty_cycle:
;> if cmd != duty_cycle_cmd:
;>     return Audio3_tempo(channel, cmd, cmd_d)
	cp duty_cycle_cmd
	jr nz, Audio3_tempo
;> duty = (Audio3_GetNextMusicByte(channel) & 3) << 6     # into bits 6-7, where the hardware has it
	call Audio3_GetNextMusicByte
	rrca
	rrca
	and $c0
;> wChannelDutyCycles[channel] = duty
	ld b, 0
	ld hl, wChannelDutyCycles
	add hl, bc
	ld [hl], a ; store duty cycle
;> return Audio3_sound_ret(channel)
	jp Audio3_sound_ret

;@ path: audio/engine_3
;@ def Audio3_tempo(channel: c, cmd: a, cmd_d: d)
;@ tempo hi, lo: the music's tempo (on a music channel) or the effects' tempo; the fractional parts of the
;@ note timers start again from 0.
;@ test: cmd = tempo_cmd if rand(0, 1) else rand(0, 255); cmd_d = cmd; channel = rand(0, 7)
;@ test: [mem.__setitem__(wChannelFlags1 + i, mem[wChannelFlags1 + i] & ~(1 << BIT_PITCH_SLIDE_ON)) for i in range(8)]
Audio3_tempo:
;> if cmd != tempo_cmd:
;>     return Audio3_stereo_panning(channel, cmd, cmd_d)
	cp tempo_cmd
	jr nz, Audio3_stereo_panning
;> if channel < CHAN5:
	ld a, c
	cp CHAN5
	jr nc, .sfxChannel
;>     wMusicTempo[0] = Audio3_GetNextMusicByte(channel)
	call Audio3_GetNextMusicByte
	ld [wMusicTempo], a ; store first param
;>     wMusicTempo[1] = Audio3_GetNextMusicByte(channel)
	call Audio3_GetNextMusicByte
	ld [wMusicTempo + 1], a ; store second param
;>     fill(addr(wChannelNoteDelayCountersFractionalPart), 0, 4)       # the music channels' fractions
	xor a
	ld [wChannelNoteDelayCountersFractionalPart], a ; clear RAM
	ld [wChannelNoteDelayCountersFractionalPart + 1], a
	ld [wChannelNoteDelayCountersFractionalPart + 2], a
	ld [wChannelNoteDelayCountersFractionalPart + 3], a
	jr .musicChannelDone
.sfxChannel
;> else:
;>     wSfxTempo[0] = Audio3_GetNextMusicByte(channel)
	call Audio3_GetNextMusicByte
	ld [wSfxTempo], a ; store first param
;>     wSfxTempo[1] = Audio3_GetNextMusicByte(channel)
	call Audio3_GetNextMusicByte
	ld [wSfxTempo + 1], a ; store second param
;>     fill(addr(wChannelNoteDelayCountersFractionalPart) + 4, 0, 4)   # the effect channels' fractions
	xor a
	ld [wChannelNoteDelayCountersFractionalPart + 4], a ; clear RAM
	ld [wChannelNoteDelayCountersFractionalPart + 5], a
	ld [wChannelNoteDelayCountersFractionalPart + 6], a
	ld [wChannelNoteDelayCountersFractionalPart + 7], a
.musicChannelDone
;> return Audio3_sound_ret(channel)
	jp Audio3_sound_ret

;@ path: audio/engine_3
;@ def Audio3_stereo_panning(channel: c, cmd: a, cmd_d: d)
;@ stereo_panning: which channels play on the left and right speaker.
;@ test: cmd = stereo_panning_cmd if rand(0, 1) else rand(0, 255); cmd_d = cmd; channel = rand(0, 7)
;@ test: [mem.__setitem__(wChannelFlags1 + i, mem[wChannelFlags1 + i] & ~(1 << BIT_PITCH_SLIDE_ON)) for i in range(8)]
Audio3_stereo_panning:
;> if cmd != stereo_panning_cmd:
;>     return Audio3_unknownmusic0xef(channel, cmd, cmd_d)
	cp stereo_panning_cmd
	jr nz, Audio3_unknownmusic0xef
;> wStereoPanning = Audio3_GetNextMusicByte(channel)
	call Audio3_GetNextMusicByte
	ld [wStereoPanning], a ; store panning
;> return Audio3_sound_ret(channel)
	jp Audio3_sound_ret

; this appears to never be used
;@ path: audio/engine_3
;@ def Audio3_unknownmusic0xef(channel: c, cmd: a, cmd_d: d)
;@ Command $EF: start another sound from inside the sound data, and let it switch its channel's output off
;@ when it ends. No sound in the game uses it.
;@ test: cmd = unknownmusic0xef_cmd if rand(0, 1) else rand(0, 255); cmd_d = cmd; channel = rand(0, 7)
;@ test: [mem.__setitem__(wChannelFlags1 + i, mem[wChannelFlags1 + i] & ~(1 << BIT_PITCH_SLIDE_ON)) for i in range(8)]
Audio3_unknownmusic0xef:
;> if cmd != unknownmusic0xef_cmd:
;>     return Audio3_duty_cycle_pattern(channel, cmd, cmd_d)
	cp unknownmusic0xef_cmd
	jr nz, Audio3_duty_cycle_pattern
;> Audio3_PlaySound(Audio3_GetNextMusicByte(channel))
	call Audio3_GetNextMusicByte
	push bc
	call Audio3_PlaySound
	pop bc
;> if not wDisableChannelOutputWhenSfxEnds:
	ld a, [wDisableChannelOutputWhenSfxEnds]
	and a
	jr nz, .skip
;>     wDisableChannelOutputWhenSfxEnds = wChannelSoundIDs[CHAN8]
	ld a, [wChannelSoundIDs + CHAN8]
	ld [wDisableChannelOutputWhenSfxEnds], a
;>     wChannelSoundIDs[CHAN8] = 0
	xor a
	ld [wChannelSoundIDs + CHAN8], a
.skip
;> return Audio3_sound_ret(channel)
	jp Audio3_sound_ret

;@ path: audio/engine_3
;@ def Audio3_duty_cycle_pattern(channel: c, cmd: a, cmd_d: d)
;@ duty_cycle_pattern: four 2-bit duties that take turns, one per frame.
;@ test: cmd = duty_cycle_pattern_cmd if rand(0, 1) else rand(0, 255); cmd_d = cmd; channel = rand(0, 7)
;@ test: [mem.__setitem__(wChannelFlags1 + i, mem[wChannelFlags1 + i] & ~(1 << BIT_PITCH_SLIDE_ON)) for i in range(8)]
Audio3_duty_cycle_pattern:
;> if cmd != duty_cycle_pattern_cmd:
;>     return Audio3_volume(channel, cmd, cmd_d)
	cp duty_cycle_pattern_cmd
	jr nz, Audio3_volume
;> pattern = Audio3_GetNextMusicByte(channel)
	call Audio3_GetNextMusicByte
;> wChannelDutyCyclePatterns[channel] = pattern
	ld b, 0
	ld hl, wChannelDutyCyclePatterns
	add hl, bc
	ld [hl], a ; store full pattern
;> wChannelDutyCycles[channel] = pattern & 0xC0
	and %11000000
	ld hl, wChannelDutyCycles
	add hl, bc
	ld [hl], a ; store first duty cycle
;> wChannelFlags1[channel] = wChannelFlags1[channel] | 1 << BIT_ROTATE_DUTY_CYCLE
	ld hl, wChannelFlags1
	add hl, bc
	set BIT_ROTATE_DUTY_CYCLE, [hl]
;> return Audio3_sound_ret(channel)
	jp Audio3_sound_ret

;@ path: audio/engine_3
;@ def Audio3_volume(channel: c, cmd: a, cmd_d: d)
;@ volume: the master volume of both speakers.
;@ test: cmd = volume_cmd if rand(0, 1) else rand(0, 255); cmd_d = cmd; channel = rand(0, 7)
;@ test: [mem.__setitem__(wChannelFlags1 + i, mem[wChannelFlags1 + i] & ~(1 << BIT_PITCH_SLIDE_ON)) for i in range(8)]
Audio3_volume:
;> if cmd != volume_cmd:
;>     return Audio3_execute_music(channel, cmd, cmd_d)
	cp volume_cmd
	jr nz, Audio3_execute_music
;> rAUDVOL = Audio3_GetNextMusicByte(channel)
	call Audio3_GetNextMusicByte
	ldh [rAUDVOL], a ; store volume
;> return Audio3_sound_ret(channel)
	jp Audio3_sound_ret

;@ path: audio/engine_3
;@ def Audio3_execute_music(channel: c, cmd: a, cmd_d: d)
;@ execute_music: an effect channel reads the rest of its data as music commands (no sfx_note or pitch_sweep).
;@ test: cmd = execute_music_cmd if rand(0, 1) else rand(0, 255); cmd_d = cmd; channel = rand(0, 7)
;@ test: [mem.__setitem__(wChannelFlags1 + i, mem[wChannelFlags1 + i] & ~(1 << BIT_PITCH_SLIDE_ON)) for i in range(8)]
Audio3_execute_music:
;> if cmd != execute_music_cmd:
;>     return Audio3_octave(channel, cmd, cmd_d)
	cp execute_music_cmd
	jr nz, Audio3_octave
;> wChannelFlags2[channel] = wChannelFlags2[channel] | 1 << BIT_EXECUTE_MUSIC
	ld b, $0
	ld hl, wChannelFlags2
	add hl, bc
	set BIT_EXECUTE_MUSIC, [hl]
;> return Audio3_sound_ret(channel)
	jp Audio3_sound_ret

;@ path: audio/engine_3
;@ def Audio3_octave(channel: c, cmd: a, cmd_d: d)
;@ octave n: the octave of the notes that follow.
;@ test: cmd = octave_cmd | rand(0, 15) if rand(0, 1) else rand(0, 255); cmd_d = cmd; channel = rand(0, 7)
;@ test: [mem.__setitem__(wChannelFlags1 + i, mem[wChannelFlags1 + i] & ~(1 << BIT_PITCH_SLIDE_ON)) for i in range(8)]
Audio3_octave:
;> if cmd & 0xF0 != octave_cmd:
;>     return Audio3_sfx_note(channel, cmd & 0xF0, cmd_d)
	and $f0
	cp octave_cmd
	jr nz, Audio3_sfx_note
;> wChannelOctaves[channel] = cmd_d & 0xF
	ld hl, wChannelOctaves
	ld b, 0
	add hl, bc
	ld a, d
	and $f
	ld [hl], a ; store low nibble as octave
;> return Audio3_sound_ret(channel)
	jp Audio3_sound_ret

; sfx_note is either square_note or noise_note depending on the channel
;@ path: audio/engine_3
;@ def Audio3_sfx_note(channel: c, cmd: a, cmd_d: d)
;@ A sound effect's note (square_note or noise_note): length, volume envelope and frequency written straight
;@ to the channel's registers. a holds the command's high nibble, d the whole command.
;@ test: cmd_d = sfx_note_cmd | rand(0, 15) if rand(0, 1) else rand(0, 255); cmd = cmd_d & 0xF0; channel = rand(0, 7)
;@ test: [mem.__setitem__(wChannelFlags1 + i, mem[wChannelFlags1 + i] & ~(1 << BIT_PITCH_SLIDE_ON)) for i in range(8)]
;@ test: mem[wChannelFlags1 + channel] |= 1 << BIT_NOISE_OR_SFX
Audio3_sfx_note:
;> if cmd != sfx_note_cmd:
;>     return Audio3_pitch_sweep(channel, cmd_d)
	cp sfx_note_cmd
	jr nz, Audio3_pitch_sweep
;> if channel < CHAN4:                            # only on the noise and effect channels
;>     return Audio3_pitch_sweep(channel, cmd_d)
	ld a, c
	cp CHAN4 ; is this a noise or sfx channel?
	jr c, Audio3_pitch_sweep ; no
;> if wChannelFlags2[channel] & 1 << BIT_EXECUTE_MUSIC:   # not while it reads music commands
;>     return Audio3_pitch_sweep(channel, cmd_d)
	ld b, 0
	ld hl, wChannelFlags2
	add hl, bc
	bit BIT_EXECUTE_MUSIC, [hl] ; is execute_music being used?
	jr nz, Audio3_pitch_sweep ; yes
;> Audio3_note_length(channel, cmd_d)
	call Audio3_note_length

; This code seems to do the same thing as what Audio3_ApplyDutyCycleAndSoundLength
; does below.
;> length = wChannelNoteDelayCounters[channel]   # (left in a by note_length)
	ld d, a
;> value = wChannelDutyCycles[channel] | length
	ld b, 0
	ld hl, wChannelDutyCycles
	add hl, bc
	ld a, [hl]
	or d
	ld d, a
;> mem[Audio3_GetRegisterPointer(REG_DUTY_SOUND_LEN, channel)] = value
	ld b, REG_DUTY_SOUND_LEN
	call Audio3_GetRegisterPointer
	ld [hl], d

;> envelope = Audio3_GetNextMusicByte(channel)
	call Audio3_GetNextMusicByte
	ld d, a
;> mem[Audio3_GetRegisterPointer(REG_VOLUME_ENVELOPE, channel)] = envelope
	ld b, REG_VOLUME_ENVELOPE
	call Audio3_GetRegisterPointer
	ld [hl], d
;> lo = Audio3_GetNextMusicByte(channel)
	call Audio3_GetNextMusicByte
	ld e, a
;> hi = 0
;> if channel != CHAN8:
	ld a, c
	cp CHAN8
	ld a, 0
	jr z, .skip
; Channels 1 through 3 have 2 registers that control frequency, but the noise
; channel a single register (the polynomial counter) that controls frequency,
; so this command has one less byte on the noise channel.
;>     hi = Audio3_GetNextMusicByte(channel)
	push de
	call Audio3_GetNextMusicByte
	pop de
.skip
;> freq = hi << 8 | lo
	ld d, a
	push de
;> Audio3_ApplyDutyCycleAndSoundLength(channel)
	call Audio3_ApplyDutyCycleAndSoundLength
;> Audio3_EnableChannelOutput(channel)
	call Audio3_EnableChannelOutput
;> Audio3_ApplyWavePatternAndFrequency(channel, freq)
	pop de
	call Audio3_ApplyWavePatternAndFrequency
	ret

;@ path: audio/engine_3
;@ def Audio3_pitch_sweep(channel: c, cmd: d)
;@ pitch_sweep: an effect on channel 1 sets the hardware frequency sweep.
;@ test: cmd = pitch_sweep_cmd if rand(0, 1) else rand(0, 255); channel = rand(0, 7)
;@ test: [mem.__setitem__(wChannelFlags1 + i, mem[wChannelFlags1 + i] & ~(1 << BIT_PITCH_SLIDE_ON)) for i in range(8)]
Audio3_pitch_sweep:
;> if channel < CHAN5:                             # only effects use it
;>     return Audio3_note(channel, cmd)
	ld a, c
	cp CHAN5
	jr c, Audio3_note ; if not a sfx
;> if cmd != pitch_sweep_cmd:
;>     return Audio3_note(channel, cmd)
	ld a, d
	cp pitch_sweep_cmd
	jr nz, Audio3_note
;> if wChannelFlags2[channel] & 1 << BIT_EXECUTE_MUSIC:
;>     return Audio3_note(channel, cmd)
	ld b, $0
	ld hl, wChannelFlags2
	add hl, bc
	bit BIT_EXECUTE_MUSIC, [hl]
	jr nz, Audio3_note ; no
;> rAUD1SWEEP = Audio3_GetNextMusicByte(channel)
	call Audio3_GetNextMusicByte
	ldh [rAUD1SWEEP], a
;> return Audio3_sound_ret(channel)
	jp Audio3_sound_ret

;@ path: audio/engine_3
;@ def Audio3_note(channel: c, cmd: d)
;@ A note. On the music noise channel it is a drum: drum_note plays a noise instrument (one of the noise
;@ sound effects) and waits; a single byte below $B0 is an unused shorter form of it.
;@ test: cmd = rand(0, 255); channel = CHAN4 if rand(0, 1) else rand(0, 7)
;@ test: [mem.__setitem__(wChannelFlags1 + i, mem[wChannelFlags1 + i] & ~(1 << BIT_PITCH_SLIDE_ON)) for i in range(8)]
Audio3_note:
;> if channel != CHAN4:                            # drums only on the noise channel
;>     return Audio3_note_length(channel, cmd)
	ld a, c
	cp CHAN4
	jr nz, Audio3_note_length ; if not noise channel
;> kind = cmd & 0xF0
	ld a, d
	and $f0
;> if kind == drum_note_cmd:
	cp drum_note_cmd
	jr z, .drum_note
;>@dlen     cmd = cmd & 0xF                         # the length
;>@dins     instrument = Audio3_GetNextMusicByte(channel)   # the instrument in the next byte
;> elif kind > drum_note_cmd:
;>     return Audio3_note_length(channel, cmd)
	jr nc, Audio3_note_length

	; this executes when on the noise channel and
	; the command id is less than drum_note_cmd ($b0)
	; in this case, the upper nybble is used as the noise instrument ($1-$a)
	; and the lower nybble is the length minus 1 (0-15)
	; however, this doesn't work for instrument #2 because the command id
	; is captured by the noise_note command (command id $2x)
	; this essentially acts like a drum_note command that is only 1 byte
	; instead of 2 and can only be used with instruments 1 and 3 through 10
	; this is unused by the game
;> else:
;>     instrument = cmd >> 4
	swap a
	ld b, a
;>     cmd = cmd & 0xF                             # the length
	ld a, d
	and $f
	ld d, a
	ld a, b
;>     # (the length and channel are kept for later)
	push de
	push bc
	jr .playDnote

.drum_note
;=@dlen
	ld a, d
	and $f
	push af
	push bc
;=@dins
	call Audio3_GetNextMusicByte ; get drum_note instrument
.playDnote
;> if not wDisableChannelOutputWhenSfxEnds:
	ld d, a
	ld a, [wDisableChannelOutputWhenSfxEnds]
	and a
	jr nz, .skipDnote
;>     Audio3_PlaySound(instrument)                # the instrument is a noise sound effect
	ld a, d
	call Audio3_PlaySound
.skipDnote
;> return Audio3_note_length(channel, cmd)         # and wait for the drum's length
	pop bc
	pop de

;@ path: audio/engine_3
;@ def Audio3_note_length(channel: c, cmd: d)
;@ How long the note lasts: (length + 1) * note speed * tempo, in 1/256 frames, added to the fractional part
;@ left over from the last note. Then the note's pitch, unless this is an effect's own note.
;@ test: cmd = rand(0, 255); channel = rand(0, 7)
;@ test: [mem.__setitem__(wChannelFlags1 + i, mem[wChannelFlags1 + i] & ~(1 << BIT_PITCH_SLIDE_ON)) for i in range(8)]
Audio3_note_length:
;> kept = cmd                                      # for note_pitch
	ld a, d
	push af
;> length = (cmd & 0xF) + 1                        # in 16ths
	and $f
	inc a
	ld b, 0
	ld e, a  ; store note length (in 16ths)
	ld d, b
;> ticks = Audio3_MultiplyAdd(wChannelNoteSpeeds[channel], length, 0) & 0xFF
	ld hl, wChannelNoteSpeeds
	add hl, bc
	ld a, [hl]
	ld l, b
	call Audio3_MultiplyAdd
;> if channel < CHAN5:
	ld a, c
	cp CHAN5
	jr nc, .sfxChannel
;>     tempo = wMusicTempo[0] << 8 | wMusicTempo[1]
	ld a, [wMusicTempo]
	ld d, a
	ld a, [wMusicTempo + 1]
	ld e, a
	jr .skip
.sfxChannel
;> elif channel == CHAN8:
;>     tempo = 0x100
	ld d, $1
	ld e, $0
	cp CHAN8
	jr z, .skip ; if noise channel
;> else:
;>     Audio3_SetSfxTempo()
	call Audio3_SetSfxTempo
;>     tempo = wSfxTempo[0] << 8 | wSfxTempo[1]
	ld a, [wSfxTempo]
	ld d, a
	ld a, [wSfxTempo + 1]
	ld e, a
.skip
;> total = Audio3_MultiplyAdd(ticks, tempo, wChannelNoteDelayCountersFractionalPart[channel])
	ld a, l ; a = note_length * note_speed
	ld b, 0
	ld hl, wChannelNoteDelayCountersFractionalPart
	add hl, bc
	ld l, [hl]
	call Audio3_MultiplyAdd
;> wChannelNoteDelayCountersFractionalPart[channel] = total & 0xFF
	ld e, l
	ld d, h ; de = note_delay_frac_part + (note_length * note_speed * tempo)
	ld hl, wChannelNoteDelayCountersFractionalPart
	add hl, bc
	ld [hl], e
;> wChannelNoteDelayCounters[channel] = total >> 8      # whole frames
	ld a, d
	ld hl, wChannelNoteDelayCounters
	add hl, bc
	ld [hl], a
;> if wChannelFlags2[channel] & 1 << BIT_EXECUTE_MUSIC:
;>     return Audio3_note_pitch(channel, kept)
	ld hl, wChannelFlags2
	add hl, bc
	bit BIT_EXECUTE_MUSIC, [hl]
	jr nz, Audio3_note_pitch
;> if not wChannelFlags1[channel] & 1 << BIT_NOISE_OR_SFX:
;>     return Audio3_note_pitch(channel, kept)
	ld hl, wChannelFlags1
	add hl, bc
	bit BIT_NOISE_OR_SFX, [hl]
	jr z, Audio3_note_pitch
;> return                                          # an effect's note sets no pitch here (kept is dropped)
	pop hl
	ret

;@ path: audio/engine_3
;@ def Audio3_note_pitch(channel: c, cmd)
;@ The note's pitch: a rest silences the channel (unless an effect has it); a note gets its frequency from
;@ the pitch table and the channel's octave, starts any pitch slide, and is written to the hardware - but a
;@ music channel stays quiet while an effect plays on it. The command byte is the one note_length left on
;@ the stack.
;@ test: skip starts by popping the command byte Audio3_note_length pushed
Audio3_note_pitch:
;> if cmd & 0xF0 == rest_cmd:
	pop af
	and $f0
	cp rest_cmd
	jr nz, .notRest
;>     if channel < CHAN5:
	ld a, c
	cp CHAN5
	jr nc, .next
; If this isn't an SFX channel, try the corresponding SFX channel.
;>         if wChannelSoundIDs[CHAN5 + channel]:
;>             return                              # an effect has the hardware channel
	ld hl, wChannelSoundIDs + CHAN5
	add hl, bc
	ld a, [hl]
	and a
	jr nz, .done
	; fall through
.next
;>     if channel == CHAN3 or channel == CHAN7:
	ld a, c
	cp CHAN3
	jr z, .channel3
	cp CHAN7
	jr nz, .notChannel3
.channel3
;>         mask = mem[Audio3_HWChannelDisableMasks + channel]
	ld b, 0
	ld hl, Audio3_HWChannelDisableMasks
	add hl, bc
;>         rAUDTERM = rAUDTERM & mask              # the wave channel's output off
	ldh a, [rAUDTERM]
	and [hl]
	ldh [rAUDTERM], a ; disable hardware channel 3's output
	jr .done
.notChannel3
;>     else:
;>         reg = Audio3_GetRegisterPointer(REG_VOLUME_ENVELOPE, channel)
	ld b, REG_VOLUME_ENVELOPE
	call Audio3_GetRegisterPointer
;>         mem[reg] = 8                            # volume 0, rising
	ld a, $8 ; fade in sound
	ld [hli], a
;>         mem[reg + 2] = 0x80                     # restart the channel
	inc hl
	ld a, $80 ; restart sound
	ld [hl], a
.done
;>     return
	ret
.notRest
;> freq = Audio3_CalculateFrequency(cmd >> 4, wChannelOctaves[channel])
	swap a
	ld b, 0
	ld hl, wChannelOctaves
	add hl, bc
	ld b, [hl]
	call Audio3_CalculateFrequency
;> if wChannelFlags1[channel] & 1 << BIT_PITCH_SLIDE_ON:
;>     freq = Audio3_InitPitchSlideVars(channel, freq, 0)
	ld b, 0
	ld hl, wChannelFlags1
	add hl, bc
	bit BIT_PITCH_SLIDE_ON, [hl]
	jr z, .skipPitchSlide
	call Audio3_InitPitchSlideVars
.skipPitchSlide
;> if channel < CHAN5:
	push de
	ld a, c
	cp CHAN5
	jr nc, .sfxChannel ; if sfx channel
; If this isn't an SFX channel, try the corresponding SFX channel.
;>     busy = wChannelSoundIDs[CHAN5 + channel]
	ld hl, wChannelSoundIDs + CHAN5
	ld d, 0
	ld e, a
	add hl, de
	ld a, [hl]
;>     if busy:
	and a
	jr nz, .noSfx
	jr .sfxChannel
.noSfx
;>         return                                  # the music stays quiet under the effect
	pop de
	ret
.sfxChannel
;> volume = wChannelVolumes[channel]
	ld b, 0
	ld hl, wChannelVolumes
	add hl, bc
	ld d, [hl]
;> mem[Audio3_GetRegisterPointer(REG_VOLUME_ENVELOPE, channel)] = volume
	ld b, REG_VOLUME_ENVELOPE
	call Audio3_GetRegisterPointer
	ld [hl], d
;> Audio3_ApplyDutyCycleAndSoundLength(channel)
	call Audio3_ApplyDutyCycleAndSoundLength
;> Audio3_EnableChannelOutput(channel)
	call Audio3_EnableChannelOutput
;> if wChannelFlags1[channel] & 1 << BIT_PERFECT_PITCH:
	pop de
	ld b, $0
	ld hl, wChannelFlags1
	add hl, bc
	bit BIT_PERFECT_PITCH, [hl] ; has toggle_perfect_pitch been used?
	jr z, .skipFrequencyInc
;>     freq = freq & 0xFF00 | (freq + 1) & 0xFF    # the carry into the high byte never happens
	inc e                       ; if yes, increment the frequency by 1
	jr nc, .skipFrequencyInc    ; Likely a mistake, because `inc` does not set flag C.
	                            ; Fortunately this does not seem to affect any notes that actually occur.
	inc d
.skipFrequencyInc
;> wChannelFrequencyLowBytes[channel] = freq & 0xFF
	ld hl, wChannelFrequencyLowBytes
	add hl, bc
	ld [hl], e
;> Audio3_ApplyWavePatternAndFrequency(channel, freq)
	call Audio3_ApplyWavePatternAndFrequency
	ret

;@ path: audio/engine_3
;@ def Audio3_EnableChannelOutput(channel: c)
;@ Turn a channel's output on in rAUDTERM. For the noise effect channel, or a music channel no effect is
;@ covering, only on the sides wStereoPanning allows.
;@ test: channel = rand(0, 7)
Audio3_EnableChannelOutput:
;> value = rAUDTERM | mem[Audio3_HWChannelEnableMasks + channel]   # this channel's bits on
	ld b, 0
	ld hl, Audio3_HWChannelEnableMasks
	add hl, bc
	ldh a, [rAUDTERM]
	or [hl] ; set this channel's bits
	ld d, a
;> pan = channel == CHAN8 or channel < CHAN5
	ld a, c
	cp CHAN8
	jr z, .noiseChannelOrNoSfx
	cp CHAN5
	jr nc, .skip ; if sfx channel
; If this isn't an SFX channel, try the corresponding SFX channel.
;> if channel < CHAN5 and wChannelSoundIDs[CHAN5 + channel]:
;>     pan = False                                 # an effect covers this music channel
	ld hl, wChannelSoundIDs + CHAN5
	add hl, bc
	ld a, [hl]
	and a
	jr nz, .skip
.noiseChannelOrNoSfx
; If this is the SFX noise channel or a music channel whose corresponding
; SFX channel is off, apply stereo panning.
;> if pan:
;>     sides = wStereoPanning & mem[Audio3_HWChannelEnableMasks + channel]
	ld a, [wStereoPanning]
	ld hl, Audio3_HWChannelEnableMasks
	add hl, bc
	and [hl]
	ld d, a
;>     value = rAUDTERM & mem[Audio3_HWChannelDisableMasks + channel] | sides
	ldh a, [rAUDTERM]
	ld hl, Audio3_HWChannelDisableMasks
	add hl, bc
	and [hl] ; reset this channel's output bits
	or d ; set this channel's output bits that enabled in [wStereoPanning]
	ld d, a
.skip
;> rAUDTERM = value
	ld a, d
	ldh [rAUDTERM], a
	ret

;@ path: audio/engine_3
;@ def Audio3_ApplyDutyCycleAndSoundLength(channel: c)
;@ Write a channel's duty/length register: the note's length, plus the duty cycle on the square and
;@ noise channels (the wave channel has no duty).
;@ test: channel = rand(0, 7)
Audio3_ApplyDutyCycleAndSoundLength:
;> value = wChannelNoteDelayCounters[channel]    # the note's length
	ld b, 0
	ld hl, wChannelNoteDelayCounters ; use the note delay as sound length
	add hl, bc
	ld d, [hl]
;> if channel != CHAN3 and channel != CHAN7:
	ld a, c
	cp CHAN3
	jr z, .skipDuty ; if music channel 3
	cp CHAN7
	jr z, .skipDuty ; if sfx channel 3
; include duty cycle (except on channel 3 which doesn't have it)
;>     value = value & 0x3F
	ld a, d
	and $3f
	ld d, a
;>     value = value | wChannelDutyCycles[channel]
	ld hl, wChannelDutyCycles
	add hl, bc
	ld a, [hl]
	or d
	ld d, a
.skipDuty
;> mem[Audio3_GetRegisterPointer(REG_DUTY_SOUND_LEN, channel)] = value
	ld b, REG_DUTY_SOUND_LEN
	call Audio3_GetRegisterPointer
	ld [hl], d
	ret

;@ path: audio/engine_3
;@ def Audio3_ApplyWavePatternAndFrequency(channel: c, freq: de)
;@ Start a note on a channel: on the wave channel first load its instrument's 32 samples into wave RAM
;@ (with the channel stopped), then write the frequency with the counter-mode flag.
;@ test: channel = rand(0, 7)
Audio3_ApplyWavePatternAndFrequency:
;> if channel == CHAN3 or channel == CHAN7:     # the wave channel
	ld a, c
	cp CHAN3
	jr z, .channel3
	cp CHAN7
	jr nz, .notChannel3
	; fall through
.channel3
;>     instrument = wMusicWaveInstrument if channel == CHAN3 else wSfxWaveInstrument
	push de
	ld de, wMusicWaveInstrument
	cp CHAN3
	jr z, .next
	ld de, wSfxWaveInstrument
.next
;>     i = 2 * instrument & 0xFF
	ld a, [de]
	add a
	ld d, 0
	ld e, a
;>     src = mem16[Audio3_WavePointers + i]       # its 32 samples
	ld hl, Audio3_WavePointers
	add hl, de
	ld e, [hl]
	inc hl
	ld d, [hl]
;=@wave
	ld hl, _AUD3WAVERAM
	ld b, AUD3WAVE_SIZE - 1
;>     rAUD3ENA = 0                               # stopped while its wave RAM is written
	ld a, $0 ; stop hardware channel 3
	ldh [rAUD3ENA], a
.loop
;>@wave     for i in range(AUD3WAVE_SIZE):
;>         mem[_AUD3WAVERAM + i] = mem[src + i]
	ld a, [de]
	inc de
	ld [hli], a
;=@wave
	ld a, b
	dec b
	and a
	jr nz, .loop
;>     rAUD3ENA = AUD3ENA_ON
	ld a, AUD3ENA_ON ; start hardware channel 3
	ldh [rAUD3ENA], a
	pop de
.notChannel3
;> hi = (freq >> 8 | 0x80) & 0xC7
	ld a, d
	or $80 ; use counter mode (i.e. disable output when the counter reaches 0)
	and $c7 ; zero the unused bits in the register
	ld d, a
;> reg = Audio3_GetRegisterPointer(REG_FREQUENCY_LO, channel)
	ld b, REG_FREQUENCY_LO
	call Audio3_GetRegisterPointer
;> mem[reg] = freq & 0xFF
	ld [hl], e ; store frequency low byte
;> mem[reg + 1] = hi
	inc hl
	ld [hl], d ; store frequency high byte
;> Audio3_ApplyFrequencyModifier(reg + 1, hi << 8 | freq & 0xFF)
	call Audio3_ApplyFrequencyModifier
	ret

;@ path: audio/engine_3
;@ def Audio3_SetSfxTempo()
;@ Sound effects normally run at tempo $100; a cry runs at $80 plus its tempo modifier.
Audio3_SetSfxTempo:
;> if Audio3_IsCry():
	call Audio3_IsCry
	jr nc, .notCry
;>     tempo = wTempoModifier + 0x80
	ld d, 0
	ld a, [wTempoModifier]
	add $80
	jr nc, .next
	inc d
.next
;>     wSfxTempo[1] = tempo & 0xFF
	ld [wSfxTempo + 1], a
;>     wSfxTempo[0] = tempo >> 8
	ld a, d
	ld [wSfxTempo], a
	jr .done
.notCry
;> else:
;>     wSfxTempo[1] = 0                           # tempo $100
	xor a
	ld [wSfxTempo + 1], a
;>     wSfxTempo[0] = 1
	ld a, $1
	ld [wSfxTempo], a
.done
	ret

;@ path: audio/engine_3
;@ def Audio3_ApplyFrequencyModifier(reg: hl, freq: de)
;@ While a cry plays, raise the frequency just written to the register pair ending at `reg` by the cry's
;@ pitch modifier.
;@ test: reg = rand(0xC001, 0xDF00)
Audio3_ApplyFrequencyModifier:
;> if Audio3_IsCry():
	call Audio3_IsCry
	jr nc, .done
; if playing a cry, add the cry's frequency modifier
;>     freq = (freq + wFrequencyModifier) & 0xFFFF
	ld a, [wFrequencyModifier]
	add e
	jr nc, .noCarry
	inc d
.noCarry
;>     mem[reg - 1] = freq & 0xFF
	dec hl
	ld e, a
	ld [hl], e
;>     mem[reg] = freq >> 8
	inc hl
	ld [hl], d
.done
	ret

;@ path: audio/engine_3
;@ def Audio3_GoBackOneCommandIfCry(channel: c) -> carry
;@ For a cry, step the channel's data pointer back one byte (so the byte is read again) and return carry.
;@ test: channel = rand(0, 7)
Audio3_GoBackOneCommandIfCry:
;> if not Audio3_IsCry():
;>     return False
	call Audio3_IsCry
	jr nc, .done
;> p = addr(wChannelCommandPointers) + 2 * channel
	ld hl, wChannelCommandPointers
	ld e, c
	ld d, 0
	sla e
	rl d
	add hl, de
;> borrow = mem[p] == 0
;> mem[p] = (mem[p] - 1) & 0xFF                  # one byte back
	ld a, [hl]
	sub 1
	ld [hl], a
;> mem[p + 1] = (mem[p + 1] - borrow) & 0xFF
	inc hl
	ld a, [hl]
	sbc 0
	ld [hl], a
;> return True
	scf
	ret
.done
	scf
	ccf
	ret

;@ path: audio/engine_3
;@ def Audio3_IsCry() -> carry
;@ Whether the sound effect on channel 5 is a Pokemon cry.
Audio3_IsCry:
; Returns whether the currently playing audio is a cry in carry.
;> sound = wChannelSoundIDs[CHAN5]
	ld a, [wChannelSoundIDs + CHAN5]
;> if sound < (SFX_Cry00_1 - SFX_Headers_1) // 3:
;>     return False
	cp CRY_SFX_START
	jr nc, .next
	jr .no
.next
;> return sound < ((SFX_Cry25_1 - SFX_Headers_1) // 3 + 3)                     # the answer goes back in the carry flag
	cp CRY_SFX_END
	jr z, .no
	jr c, .yes
.no
;> # .no: carry clear
	scf
	ccf
	ret
.yes
;> # .yes: carry set
	scf
	ret

;@ path: audio/engine_3
;@ def Audio3_ApplyPitchSlide(channel: c, zero: b)
;@ One frame of a pitch slide: move the frequency a step (plus the fractional step) towards the target, and
;@ stop the slide once it would pass it. b is 0 on entry.
;@ test: channel = rand(0, 7); zero = 0
Audio3_ApplyPitchSlide:
;> if not wChannelFlags1[channel] & 1 << BIT_PITCH_SLIDE_DECREASING:
	ld hl, wChannelFlags1
	add hl, bc
	bit BIT_PITCH_SLIDE_DECREASING, [hl]
	jp nz, .frequencyDecreasing
; frequency increasing
;>     cur_lo = wChannelPitchSlideCurrentFrequencyLowBytes[channel]
	ld hl, wChannelPitchSlideCurrentFrequencyLowBytes
	add hl, bc
	ld e, [hl]
;>     cur = wChannelPitchSlideCurrentFrequencyHighBytes[channel] << 8 | cur_lo
	ld hl, wChannelPitchSlideCurrentFrequencyHighBytes
	add hl, bc
	ld d, [hl]
;>     step = wChannelPitchSlideFrequencySteps[channel]
	ld hl, wChannelPitchSlideFrequencySteps
	add hl, bc
	ld l, [hl]
	ld h, b
;>     new = (cur + step) & 0xFFFF
	add hl, de
	ld d, h
	ld e, l
;>     step_frac = wChannelPitchSlideFrequencyStepsFractionalPart[channel]
	ld hl, wChannelPitchSlideCurrentFrequencyFractionalPart
	add hl, bc
	push hl
	ld hl, wChannelPitchSlideFrequencyStepsFractionalPart
	add hl, bc
	ld a, [hl]
;>     frac = wChannelPitchSlideCurrentFrequencyFractionalPart[channel] + step_frac
	pop hl
	add [hl]
;>     wChannelPitchSlideCurrentFrequencyFractionalPart[channel] = frac & 0xFF
	ld [hl], a
;>     new = (new + (frac >> 8)) & 0xFFFF         # plus the fraction's carry
	ld a, 0
	adc e
	ld e, a
	ld a, 0
	adc d
	ld d, a
;>     target_hi = wChannelPitchSlideTargetFrequencyHighBytes[channel]
	ld hl, wChannelPitchSlideTargetFrequencyHighBytes
	add hl, bc
	ld a, [hl]
;>     reached = new >> 8 > target_hi
	cp d
	jp c, .reachedTargetFrequency
;>     if new >> 8 == target_hi:
	jr nz, .applyUpdatedFrequency
;>         reached = new & 0xFF > wChannelPitchSlideTargetFrequencyLowBytes[channel]
	ld hl, wChannelPitchSlideTargetFrequencyLowBytes
	add hl, bc
	ld a, [hl]
	cp e
	jp c, .reachedTargetFrequency
	jr .applyUpdatedFrequency
.frequencyDecreasing
;> else:
;>     cur_lo = wChannelPitchSlideCurrentFrequencyLowBytes[channel]
	ld hl, wChannelPitchSlideCurrentFrequencyLowBytes
	add hl, bc
	ld a, [hl]
;>     cur = wChannelPitchSlideCurrentFrequencyHighBytes[channel] << 8 | cur_lo
	ld hl, wChannelPitchSlideCurrentFrequencyHighBytes
	add hl, bc
	ld d, [hl]
;>     step = wChannelPitchSlideFrequencySteps[channel]
	ld hl, wChannelPitchSlideFrequencySteps
	add hl, bc
	ld e, [hl]
;>     new = (cur - step) & 0xFFFF
	sub e
	ld e, a
	ld a, d
	sbc b
	ld d, a
;>     frac = wChannelPitchSlideFrequencyStepsFractionalPart[channel] * 2   # the fractional step doubles each frame
;>     wChannelPitchSlideFrequencyStepsFractionalPart[channel] = frac & 0xFF
	ld hl, wChannelPitchSlideFrequencyStepsFractionalPart
	add hl, bc
	ld a, [hl]
	add a
	ld [hl], a
;>     new = (new - (frac >> 8)) & 0xFFFF         # minus its carry
	ld a, e
	sbc b
	ld e, a
	ld a, d
	sbc b
	ld d, a
;>     target_hi = wChannelPitchSlideTargetFrequencyHighBytes[channel]
	ld hl, wChannelPitchSlideTargetFrequencyHighBytes
	add hl, bc
;>     reached = new >> 8 < target_hi
	ld a, d
	cp [hl]
	jr c, .reachedTargetFrequency
;>     if new >> 8 == target_hi:
	jr nz, .applyUpdatedFrequency
;>         reached = new & 0xFF < wChannelPitchSlideTargetFrequencyLowBytes[channel]
	ld hl, wChannelPitchSlideTargetFrequencyLowBytes
	add hl, bc
	ld a, e
	cp [hl]
	jr c, .reachedTargetFrequency
.applyUpdatedFrequency
;> if reached:                                     # the slide ends at its target
;>@stop     wChannelFlags1[channel] = wChannelFlags1[channel] & ~(1 << BIT_PITCH_SLIDE_ON | 1 << BIT_PITCH_SLIDE_DECREASING) & 0xFF
;>@ret     return
;> wChannelPitchSlideCurrentFrequencyLowBytes[channel] = new & 0xFF
	ld hl, wChannelPitchSlideCurrentFrequencyLowBytes
	add hl, bc
	ld [hl], e
;> wChannelPitchSlideCurrentFrequencyHighBytes[channel] = new >> 8
	ld hl, wChannelPitchSlideCurrentFrequencyHighBytes
	add hl, bc
	ld [hl], d
;> reg = Audio3_GetRegisterPointer(REG_FREQUENCY_LO, channel)
	ld b, REG_FREQUENCY_LO
	call Audio3_GetRegisterPointer
;> mem[reg] = new & 0xFF
	ld a, e
	ld [hli], a
;> mem[reg + 1] = new >> 8
	ld [hl], d
	ret
.reachedTargetFrequency
; Turn off pitch slide when the target frequency has been reached.
;=@stop
	ld hl, wChannelFlags1
	add hl, bc
	res BIT_PITCH_SLIDE_ON, [hl]
	res BIT_PITCH_SLIDE_DECREASING, [hl]
;=@ret
	ret

;@ path: audio/engine_3
;@ def Audio3_InitPitchSlideVars(channel: c, freq: de, zero: b) -> de
;@ Set up a pitch slide from freq to the target: the slide lasts the note's length minus the length
;@ modifier (at least 1 frame); the distance divided by that length gives the step per frame and a
;@ fractional step. Returns (steps + 1, remainder - length) in de. b is 0 on entry.
;@ test: channel = rand(0, 7); zero = 0
;@ test: mod = rand(0, 100); mem[wChannelPitchSlideLengthModifiers + channel] = mod; mem[wChannelNoteDelayCounters + channel] = mod + rand(16, 155)
Audio3_InitPitchSlideVars:
;> wChannelPitchSlideCurrentFrequencyHighBytes[channel] = freq >> 8
	ld hl, wChannelPitchSlideCurrentFrequencyHighBytes
	add hl, bc
	ld [hl], d
;> wChannelPitchSlideCurrentFrequencyLowBytes[channel] = freq & 0xFF
	ld hl, wChannelPitchSlideCurrentFrequencyLowBytes
	add hl, bc
	ld [hl], e
;> length = wChannelNoteDelayCounters[channel] - wChannelPitchSlideLengthModifiers[channel]
	ld hl, wChannelNoteDelayCounters
	add hl, bc
	ld a, [hl]
	ld hl, wChannelPitchSlideLengthModifiers
	add hl, bc
	sub [hl]
;> if length < 0:                                 # at least one frame
;>     length = 1
	jr nc, .next
	ld a, 1
.next
;> wChannelPitchSlideLengthModifiers[channel] = length   # from now on it holds the slide's length
	ld [hl], a
;> lo = (freq & 0xFF) - wChannelPitchSlideTargetFrequencyLowBytes[channel]
	ld hl, wChannelPitchSlideTargetFrequencyLowBytes
	add hl, bc
	ld a, e
	sub [hl]
	ld e, a
;> hi = ((freq >> 8) - (lo < 0)) & 0xFF
	ld a, d
	sbc b
;> if hi >= wChannelPitchSlideTargetFrequencyHighBytes[channel]:   # sliding down: current - target
	ld hl, wChannelPitchSlideTargetFrequencyHighBytes
	add hl, bc
	sub [hl]
	jr c, .targetFrequencyGreater
;>     diff = (hi - wChannelPitchSlideTargetFrequencyHighBytes[channel]) << 8 | lo & 0xFF
	ld d, a
;>     wChannelFlags1[channel] = wChannelFlags1[channel] | 1 << BIT_PITCH_SLIDE_DECREASING
	ld b, 0
	ld hl, wChannelFlags1
	add hl, bc
	set BIT_PITCH_SLIDE_DECREASING, [hl]
	jr .next2
.targetFrequencyGreater
; If the target frequency is greater, subtract the current frequency from
; the target frequency to get the absolute difference.
;> else:                                          # sliding up: target - current
;>     cur_hi = wChannelPitchSlideCurrentFrequencyHighBytes[channel]
	ld hl, wChannelPitchSlideCurrentFrequencyHighBytes
	add hl, bc
	ld d, [hl]
;>     cur_lo = wChannelPitchSlideCurrentFrequencyLowBytes[channel]
	ld hl, wChannelPitchSlideCurrentFrequencyLowBytes
	add hl, bc
	ld e, [hl]
;>     lo = wChannelPitchSlideTargetFrequencyLowBytes[channel] - cur_lo
	ld hl, wChannelPitchSlideTargetFrequencyLowBytes
	add hl, bc
	ld a, [hl]
	sub e
	ld e, a

; Bug. Instead of borrowing from the high byte of the target frequency as it
; should, it borrows from the high byte of the current frequency instead.
; This means that the result will be 0x200 greater than it should be if the
; low byte of the current frequency is greater than the low byte of the
; target frequency.
;>     hi = (cur_hi - (lo < 0)) & 0xFF
	ld a, d
	sbc b
	ld d, a

;>     diff = (wChannelPitchSlideTargetFrequencyHighBytes[channel] - hi) % 256 << 8 | lo & 0xFF
	ld hl, wChannelPitchSlideTargetFrequencyHighBytes
	add hl, bc
	ld a, [hl]
	sub d
	ld d, a
;>     wChannelFlags1[channel] = wChannelFlags1[channel] & ~(1 << BIT_PITCH_SLIDE_DECREASING) & 0xFF
	ld b, 0
	ld hl, wChannelFlags1
	add hl, bc
	res BIT_PITCH_SLIDE_DECREASING, [hl]

.next2
;> count = 0                                      # diff / length, by subtracting the length until it borrows
	ld hl, wChannelPitchSlideLengthModifiers
	add hl, bc
.divideLoop
;>@dv while True:
;>     count += 1
	inc b
;>     borrow = (diff & 0xFF) < length
;>     diff = diff & 0xFF00 | (diff - length) & 0xFF
	ld a, e
	sub [hl]
	ld e, a
;>     if not borrow:
;>         continue
	jr nc, .divideLoop
;>     if diff >> 8 == 0:
;>         break
	ld a, d
	and a
	jr z, .doneDividing
;>     diff -= 0x100                              # the borrow from the high byte
	dec a
	ld d, a
;=@dv
	jr .divideLoop
.doneDividing
;> rest = (diff + length) & 0xFF                  # the remainder
	ld a, e ; a = remainder - dividend
	add [hl]
;> wChannelPitchSlideFrequencySteps[channel] = count       # the quotient + 1
	ld d, b ; d = quotient + 1
	ld b, 0
	ld hl, wChannelPitchSlideFrequencySteps
	add hl, bc
	ld [hl], d ; store quotient + 1
;> wChannelPitchSlideFrequencyStepsFractionalPart[channel] = rest
	ld hl, wChannelPitchSlideFrequencyStepsFractionalPart
	add hl, bc
	ld [hl], a ; store remainder - dividend
;> wChannelPitchSlideCurrentFrequencyFractionalPart[channel] = rest
	ld hl, wChannelPitchSlideCurrentFrequencyFractionalPart
	add hl, bc
	ld [hl], a ; store remainder - dividend
;> return count << 8 | diff & 0xFF
	ret

;@ path: audio/engine_3
;@ def Audio3_ApplyDutyCyclePattern(channel: c)
;@ Step a channel's duty cycle pattern: four 2-bit duty values that rotate each frame, the top one going
;@ into the channel's duty register.
;@ test: channel = rand(0, 7)
Audio3_ApplyDutyCyclePattern:
;> p = wChannelDutyCyclePatterns[channel]
	ld b, 0
	ld hl, wChannelDutyCyclePatterns
	add hl, bc
	ld a, [hl]
;> p = (p << 2 | p >> 6) & 0xFF                   # rotate the next duty to the top
	rlca
	rlca
;> wChannelDutyCyclePatterns[channel] = p
	ld [hl], a
;> duty = p & 0xC0
	and $c0
	ld d, a
;> reg = Audio3_GetRegisterPointer(REG_DUTY_SOUND_LEN, channel)
	ld b, REG_DUTY_SOUND_LEN
	call Audio3_GetRegisterPointer
;> mem[reg] = mem[reg] & 0x3F | duty             # the duty is the register's top two bits
	ld a, [hl]
	and $3f
	or d
	ld [hl], a
	ret

;@ path: audio/engine_3
;@ def Audio3_GetNextMusicByte(channel: c) -> a
;@ Read the next byte of a channel's sound data and move its pointer on.
;@ test: channel = rand(0, 7)
Audio3_GetNextMusicByte:
;> i = 2 * channel & 0xFF
	ld d, 0
	ld a, c
	add a
	ld e, a
;> ptr = wChannelCommandPointers[i] | wChannelCommandPointers[i + 1] << 8
	ld hl, wChannelCommandPointers
	add hl, de
	ld a, [hli]
	ld e, a
	ld a, [hld]
	ld d, a
;> byte = mem[ptr]
	ld a, [de] ; get next music command
;> ptr = (ptr + 1) & 0xFFFF
	inc de
;> wChannelCommandPointers[i] = ptr & 0xFF
	ld [hl], e ; store address of next command
;> wChannelCommandPointers[i + 1] = ptr >> 8
	inc hl
	ld [hl], d
;> return byte
	ret

;@ path: audio/engine_3
;@ def Audio3_GetRegisterPointer(reg: b, channel: c) -> hl
;@ Address of sound register `reg` (0-4) of the hardware channel behind software channel `channel`.
Audio3_GetRegisterPointer:
; hl = address of hardware sound register b for software channel c
;> p = Audio3_HWChannelBaseAddresses + channel
	ld a, c
	ld hl, Audio3_HWChannelBaseAddresses
	add l
	jr nc, .noCarry
	inc h
.noCarry
	ld l, a
;> base = mem[p]                                 # low byte of the channel's first register
	ld a, [hl]
;> return 0xFF00 | (base + reg) & 0xFF
	add b
	ld l, a
	ld h, $ff
	ret

;@ path: audio/engine_3
;@ def Audio3_MultiplyAdd(n: a, step: de, base: l) -> hl
;@ base + n * step, by shifting and adding.
Audio3_MultiplyAdd:
; hl = l + (a * de)
;> result = base
	ld h, 0
.loop
;>@lp while True:
;>     low_bit, n = n & 1, n >> 1
	srl a
;>     if low_bit:
;>         result = (result + step) & 0xFFFF
	jr nc, .skipAdd
	add hl, de
.skipAdd
;>     step = (step << 1) & 0xFFFF
	sla e
	rl d
;>     if not n:
;>         break
	and a
	jr z, .done
;=@lp
	jr .loop
.done
;> return result
	ret

;@ path: audio/engine_3
;@ def Audio3_CalculateFrequency(note: a, octave: b) -> de
;@ The frequency register value for a note (0 = C ... 11 = B) in an octave: the pitch table holds octave 7;
;@ each octave below halves it. The top bits get the "restart" flag the register needs.
;@ test: note = rand(0, 11); octave = rand(0, 7)
Audio3_CalculateFrequency:
; return the frequency for note a, octave b in de
;> i = 2 * note                                   # 2 bytes per pitch
	ld h, 0
	ld l, a
	add hl, hl
	ld d, h
	ld e, l
;> freq = mem[Audio3_Pitches + i] | mem[Audio3_Pitches + i + 1] << 8
	ld hl, Audio3_Pitches
	add hl, de
	ld e, [hl]
	inc hl
	ld d, [hl]
;> o = octave
	ld a, b
.loop
;>@lp while o != 7:                               # each octave below 7 halves it
	cp 7
	jr z, .done
;>     freq = freq >> 1 | freq & 0x8000            # arithmetic shift: the table values are negative
	sra d
	rr e
;>     o = (o + 1) & 0xFF
	inc a
;=@lp
	jr .loop
.done
;> return (freq + 0x800) & 0xFFFF
	ld a, 8
	add d
	ld d, a
	ret

;@ path: audio/engine_3
;@ def Audio3_PlaySound(sound: a)
;@ Start a sound from this audio bank: $FF stops everything, IDs up to the last effect and $FF are effects,
;@ the rest (and $FE) are songs. A song resets the four music channels; an effect takes over only the
;@ channels it uses, unless a more important effect (lower ID) is playing there - noise instruments, the
;@ drums, never interrupt a real effect on the noise channel. Then each channel gets its start address
;@ from the sound's header (3 bytes per channel). A cry also claims all four effect channels and saves the
;@ volume.
Audio3_PlaySound::
;> wSoundID = sound
	ld [wSoundID], a
;> noise_end = (SFX_Noise_Instrument19_3 - SFX_Headers_3) // 3 + 1   # sound IDs count 3-byte headers
;> stop = sound == SFX_STOP_ALL_MUSIC
	cp SFX_STOP_ALL_MUSIC
	jp z, .stopAllAudio
;> last_sfx = (SFX_Shooting_Star - SFX_Headers_3) // 3
;> music = last_sfx < sound <= 0xFE                # the rest are sound effects
	cp MAX_SFX_ID_3
	jp z, .playSfx
	jp c, .playSfx
	cp $fe
	jr z, .playMusic
	jp nc, .playSfx

.playMusic
;> if music:
;>     wUnusedMusicByte = 0
	xor a
	ld [wUnusedMusicByte], a
;>     wDisableChannelOutputWhenSfxEnds = 0
	ld [wDisableChannelOutputWhenSfxEnds], a
;>     wMusicTempo[1] = 0
	ld [wMusicTempo + 1], a
;>     wMusicWaveInstrument = 0
	ld [wMusicWaveInstrument], a
;>     wSfxWaveInstrument = 0
	ld [wSfxWaveInstrument], a
;>     fill(wChannelReturnAddresses, 0, NUM_CHANNELS)      # 8 bytes: the four music channels' pointers
	ld d, NUM_CHANNELS
	ld hl, wChannelReturnAddresses
	call .FillMem
;>     fill(wChannelCommandPointers, 0, NUM_CHANNELS)
	ld hl, wChannelCommandPointers
	call .FillMem
;>     fill(wChannelSoundIDs, 0, NUM_MUSIC_CHANS)          # and every per-channel variable
	ld d, NUM_MUSIC_CHANS
	ld hl, wChannelSoundIDs
	call .FillMem
;>     fill(wChannelFlags1, 0, NUM_MUSIC_CHANS)
;>     fill(wChannelDutyCycles, 0, NUM_MUSIC_CHANS)
	ld hl, wChannelFlags1
	call .FillMem
	ld hl, wChannelDutyCycles
	call .FillMem
;>     fill(wChannelDutyCyclePatterns, 0, NUM_MUSIC_CHANS)
;>     fill(wChannelVibratoDelayCounters, 0, NUM_MUSIC_CHANS)
	ld hl, wChannelDutyCyclePatterns
	call .FillMem
	ld hl, wChannelVibratoDelayCounters
	call .FillMem
;>     fill(wChannelVibratoExtents, 0, NUM_MUSIC_CHANS)
;>     fill(wChannelVibratoRates, 0, NUM_MUSIC_CHANS)
	ld hl, wChannelVibratoExtents
	call .FillMem
	ld hl, wChannelVibratoRates
	call .FillMem
;>     fill(wChannelFrequencyLowBytes, 0, NUM_MUSIC_CHANS)
;>     fill(wChannelVibratoDelayCounterReloadValues, 0, NUM_MUSIC_CHANS)
	ld hl, wChannelFrequencyLowBytes
	call .FillMem
	ld hl, wChannelVibratoDelayCounterReloadValues
	call .FillMem
;>     fill(wChannelFlags2, 0, NUM_MUSIC_CHANS)
;>     fill(wChannelPitchSlideLengthModifiers, 0, NUM_MUSIC_CHANS)
	ld hl, wChannelFlags2
	call .FillMem
	ld hl, wChannelPitchSlideLengthModifiers
	call .FillMem
;>     fill(wChannelPitchSlideFrequencySteps, 0, NUM_MUSIC_CHANS)
;>     fill(wChannelPitchSlideFrequencyStepsFractionalPart, 0, NUM_MUSIC_CHANS)
	ld hl, wChannelPitchSlideFrequencySteps
	call .FillMem
	ld hl, wChannelPitchSlideFrequencyStepsFractionalPart
	call .FillMem
;>     fill(wChannelPitchSlideCurrentFrequencyFractionalPart, 0, NUM_MUSIC_CHANS)
;>     fill(wChannelPitchSlideCurrentFrequencyHighBytes, 0, NUM_MUSIC_CHANS)
	ld hl, wChannelPitchSlideCurrentFrequencyFractionalPart
	call .FillMem
	ld hl, wChannelPitchSlideCurrentFrequencyHighBytes
	call .FillMem
;>     fill(wChannelPitchSlideCurrentFrequencyLowBytes, 0, NUM_MUSIC_CHANS)
;>     fill(wChannelPitchSlideTargetFrequencyHighBytes, 0, NUM_MUSIC_CHANS)
	ld hl, wChannelPitchSlideCurrentFrequencyLowBytes
	call .FillMem
	ld hl, wChannelPitchSlideTargetFrequencyHighBytes
	call .FillMem
;>     fill(wChannelPitchSlideTargetFrequencyLowBytes, 0, NUM_MUSIC_CHANS)
	ld hl, wChannelPitchSlideTargetFrequencyLowBytes
	call .FillMem
;>     fill(wChannelLoopCounters, 1, NUM_MUSIC_CHANS)      # these start at 1
	ld a, $1
	ld hl, wChannelLoopCounters
	call .FillMem
;>     fill(wChannelNoteDelayCounters, 1, NUM_MUSIC_CHANS)
;>     fill(wChannelNoteSpeeds, 1, NUM_MUSIC_CHANS)
	ld hl, wChannelNoteDelayCounters
	call .FillMem
	ld hl, wChannelNoteSpeeds
	call .FillMem
;>     wMusicTempo[0] = 1
;>     wStereoPanning = 0xFF                       # both sides
	ld [wMusicTempo], a
	ld a, $ff
	ld [wStereoPanning], a
;>     rAUDVOL = 0
	xor a
	ldh [rAUDVOL], a
;>     rAUD1SWEEP = AUD1SWEEP_DOWN                 # sweep off
	ld a, AUD1SWEEP_DOWN
	ldh [rAUD1SWEEP], a
;>     rAUDTERM = 0
	ld a, 0
	ldh [rAUDTERM], a
;>     rAUD3ENA = 0                                # restart the wave channel
;>     rAUD3ENA = AUD3ENA_ON
	xor a
	ldh [rAUD3ENA], a
	ld a, AUD3ENA_ON
	ldh [rAUD3ENA], a
;>     rAUDVOL = 0x77                              # full volume
	ld a, $77
	ldh [rAUDVOL], a
	jp .playSoundCommon

.playSfx
;> elif not stop:
;>     i = 3 * sound
	ld l, a
	ld e, a
	ld h, 0
	ld d, h
	add hl, hl
	add hl, de
;>     header = (SFX_Headers_3 + i) & 0xFFFF
	ld de, SFX_Headers_3
	add hl, de
;>     wSfxHeaderPointer[0] = header >> 8
;>     wSfxHeaderPointer[1] = header & 0xFF
	ld a, h
	ld [wSfxHeaderPointer], a
	ld a, l
	ld [wSfxHeaderPointer + 1], a
;>     last = mem[header] >> 6                     # the effect's number of channels - 1
	ld a, [hl]
	and $c0
	rlca
	rlca
	ld c, a
.sfxChannelLoop
;>@loop     for k in range(last, -1, -1):          # its channels, last first
;>         i = 3 * k
	ld d, c
	ld a, c
	add a
	add c
	ld c, a
	ld b, 0
;>         entry = header + i                      # (the header address comes back from wSfxHeaderPointer)
	ld a, [wSfxHeaderPointer]
	ld h, a
	ld a, [wSfxHeaderPointer + 1]
	ld l, a
	add hl, bc
	ld c, d
;>         ch = mem[entry] & 0xF                   # the software channel
	ld a, [hl]
	and $f
	ld e, a ; software channel ID
;>         playing = wChannelSoundIDs[ch]
;>         if playing:                             # the channel is busy
	ld d, 0
	ld hl, wChannelSoundIDs
	add hl, de
	ld a, [hl]
	and a
	jr z, .playChannel
;>             if ch == CHAN8:
	ld a, e
	cp CHAN8
	jr nz, .notNoiseChannel
;>                 if wSoundID < noise_end:
;>                     return                      # a drum never interrupts an effect on the noise channel
	ld a, [wSoundID]
	cp NOISE_INSTRUMENTS_END
	jr nc, .notNoiseInstrument
	ret
.notNoiseInstrument
;>                 replace = playing <= noise_end  # while a drum may always be replaced
	ld a, [hl]
	cp NOISE_INSTRUMENTS_END
	jr z, .playChannel
	jr c, .playChannel
.notNoiseChannel
;>             if not (ch == CHAN8 and replace) and wSoundID > playing:
;>                 return                          # a more important effect (lower ID) plays there
	ld a, [wSoundID]
	cp [hl]
	jr z, .playChannel
	jr c, .playChannel
	ret
.playChannel
;>         # (a = 0 for the clearing below)
	xor a
;>         j = 2 * ch                              # the pointer tables have 2 bytes per channel
	push de
	ld h, d
	ld l, e
	add hl, hl
	ld d, h
	ld e, l
;>         wChannelReturnAddresses[j] = 0
;>         wChannelReturnAddresses[j + 1] = 0
	ld hl, wChannelReturnAddresses
	add hl, de
	ld [hli], a
	ld [hl], a
;>         wChannelCommandPointers[j] = 0
;>         wChannelCommandPointers[j + 1] = 0
	ld hl, wChannelCommandPointers
	add hl, de
	ld [hli], a
	ld [hl], a
	pop de
;>         wChannelSoundIDs[ch] = 0
;>         wChannelFlags1[ch] = 0
	ld hl, wChannelSoundIDs
	add hl, de
	ld [hl], a
	ld hl, wChannelFlags1
	add hl, de
	ld [hl], a
;>         wChannelDutyCycles[ch] = 0
;>         wChannelDutyCyclePatterns[ch] = 0
	ld hl, wChannelDutyCycles
	add hl, de
	ld [hl], a
	ld hl, wChannelDutyCyclePatterns
	add hl, de
	ld [hl], a
;>         wChannelVibratoDelayCounters[ch] = 0
;>         wChannelVibratoExtents[ch] = 0
	ld hl, wChannelVibratoDelayCounters
	add hl, de
	ld [hl], a
	ld hl, wChannelVibratoExtents
	add hl, de
	ld [hl], a
;>         wChannelVibratoRates[ch] = 0
;>         wChannelFrequencyLowBytes[ch] = 0
	ld hl, wChannelVibratoRates
	add hl, de
	ld [hl], a
	ld hl, wChannelFrequencyLowBytes
	add hl, de
	ld [hl], a
;>         wChannelVibratoDelayCounterReloadValues[ch] = 0
;>         wChannelPitchSlideLengthModifiers[ch] = 0
	ld hl, wChannelVibratoDelayCounterReloadValues
	add hl, de
	ld [hl], a
	ld hl, wChannelPitchSlideLengthModifiers
	add hl, de
	ld [hl], a
;>         wChannelPitchSlideFrequencySteps[ch] = 0
;>         wChannelPitchSlideFrequencyStepsFractionalPart[ch] = 0
	ld hl, wChannelPitchSlideFrequencySteps
	add hl, de
	ld [hl], a
	ld hl, wChannelPitchSlideFrequencyStepsFractionalPart
	add hl, de
	ld [hl], a
;>         wChannelPitchSlideCurrentFrequencyFractionalPart[ch] = 0
;>         wChannelPitchSlideCurrentFrequencyHighBytes[ch] = 0
	ld hl, wChannelPitchSlideCurrentFrequencyFractionalPart
	add hl, de
	ld [hl], a
	ld hl, wChannelPitchSlideCurrentFrequencyHighBytes
	add hl, de
	ld [hl], a
;>         wChannelPitchSlideCurrentFrequencyLowBytes[ch] = 0
;>         wChannelPitchSlideTargetFrequencyHighBytes[ch] = 0
	ld hl, wChannelPitchSlideCurrentFrequencyLowBytes
	add hl, de
	ld [hl], a
	ld hl, wChannelPitchSlideTargetFrequencyHighBytes
	add hl, de
	ld [hl], a
;>         wChannelPitchSlideTargetFrequencyLowBytes[ch] = 0
;>         wChannelFlags2[ch] = 0
	ld hl, wChannelPitchSlideTargetFrequencyLowBytes
	add hl, de
	ld [hl], a
	ld hl, wChannelFlags2
	add hl, de
	ld [hl], a
;>         wChannelLoopCounters[ch] = 1
	ld a, $1
	ld hl, wChannelLoopCounters
	add hl, de
	ld [hl], a
;>         wChannelNoteDelayCounters[ch] = 1
;>         wChannelNoteSpeeds[ch] = 1
	ld hl, wChannelNoteDelayCounters
	add hl, de
	ld [hl], a
	ld hl, wChannelNoteSpeeds
	add hl, de
	ld [hl], a
;>         if ch == CHAN5:
;>             rAUD1SWEEP = AUD1SWEEP_DOWN         # sweep off
	ld a, e
	cp CHAN5
	jr nz, .skipSweepDisable
	ld a, AUD1SWEEP_DOWN
	ldh [rAUD1SWEEP], a ; sweep off
.skipSweepDisable
;=@loop
	ld a, c
	and a
	jp z, .playSoundCommon
	dec c
	jp .sfxChannelLoop

.stopAllAudio
;> else:                                           # stop everything
;>     rAUDENA = AUDENA_ON
	ld a, AUDENA_ON
	ldh [rAUDENA], a ; sound hardware on
;>     rAUD3ENA = AUDENA_ON
	ldh [rAUD3ENA], a ; wave playback on
;>     rAUDTERM = 0
	xor a
	ldh [rAUDTERM], a ; no sound output
;>     rAUD3LEVEL = 0
	ldh [rAUD3LEVEL], a ; mute channel 3 (wave channel)
;>     rAUD1SWEEP = AUD1SWEEP_DOWN
	ld a, AUD1SWEEP_DOWN
	ldh [rAUD1SWEEP], a ; sweep off
;>     rAUD1ENV = AUD1SWEEP_DOWN                   # (the same value: volume 0)
	ldh [rAUD1ENV], a ; mute channel 1 (pulse channel 1)
;>     rAUD2ENV = AUD1SWEEP_DOWN
	ldh [rAUD2ENV], a ; mute channel 2 (pulse channel 2)
;>     rAUD4ENV = AUD1SWEEP_DOWN
	ldh [rAUD4ENV], a ; mute channel 4 (noise channel)
;>     rAUD1HIGH = AUD1HIGH_LENGTH_ON
	ld a, AUD1HIGH_LENGTH_ON
	ldh [rAUD1HIGH], a ; counter mode
;>     rAUD2HIGH = AUD1HIGH_LENGTH_ON
	ldh [rAUD2HIGH], a
;>     rAUD4GO = AUD1HIGH_LENGTH_ON
	ldh [rAUD4GO], a
;>     rAUDVOL = 0x77
	ld a, $77
	ldh [rAUDVOL], a ; full volume
;>     wUnusedMusicByte = 0
	xor a
	ld [wUnusedMusicByte], a
;>     wDisableChannelOutputWhenSfxEnds = 0
	ld [wDisableChannelOutputWhenSfxEnds], a
;>     wMuteAudioAndPauseMusic = 0
	ld [wMuteAudioAndPauseMusic], a
;>     wMusicTempo[1] = 0
	ld [wMusicTempo + 1], a
;>     wSfxTempo[1] = 0
	ld [wSfxTempo + 1], a
;>     wMusicWaveInstrument = 0
	ld [wMusicWaveInstrument], a
;>     wSfxWaveInstrument = 0
	ld [wSfxWaveInstrument], a
;>     fill(wChannelCommandPointers, 0, 0xA0)      # every channel variable up to the note timers
	ld d, $a0
	ld hl, wChannelCommandPointers
	call .FillMem
;>     fill(wChannelNoteDelayCounters, 1, 0x18)    # note timers, loop counters, note speeds
	ld a, $1
	ld d, $18
	ld hl, wChannelNoteDelayCounters
	call .FillMem
;>     wMusicTempo[0] = 1
	ld [wMusicTempo], a
;>     wSfxTempo[0] = 1
	ld [wSfxTempo], a
;>     wStereoPanning = 0xFF
;>     return
	ld a, $ff
	ld [wStereoPanning], a
	ret

; fills d bytes at hl with a
.FillMem
;> # .FillMem is the fill() used above: d bytes at hl set to a
	ld b, d
.loop
	ld [hli], a
	dec b
	jr nz, .loop
	ret

.playSoundCommon
;> sound = wSoundID
	ld a, [wSoundID]
;> i = 3 * sound
	ld l, a
	ld e, a
	ld h, 0
	ld d, h
	add hl, hl
	add hl, de
;> header = (SFX_Headers_3 + i) & 0xFFFF
	ld de, SFX_Headers_3
	add hl, de
;> p = header
	ld e, l
	ld d, h
	ld hl, wChannelCommandPointers
;> n = mem[p] >> 6                                 # the number of channels - 1
	ld a, [de] ; get channel number
	ld b, a
	rlca
	rlca
	and $3
	ld c, a
;> ch = mem[p] & 0xF                               # the first entry's channel
	ld a, b
	and $f
;> channels = n + 1
	ld b, c
	inc b
;> p += 1
	inc de
;> slot = 0                                        # which channel's pointer the next entry fills
	ld c, 0
.commandPointerLoop
;>@each for _ in range(channels):
;>     while slot != ch:
	cp c
	jr z, .next
;>         slot = (slot + 1) & 0xFF
	inc c
	inc hl
	inc hl
	jr .commandPointerLoop
.next
;>     # (the slot, the counter and ch are kept)
	push hl
	push bc
	push af
;>     wChannelSoundIDs[ch] = wSoundID
	ld b, 0
	ld c, a
	ld hl, wChannelSoundIDs
	add hl, bc
	ld a, [wSoundID]
	ld [hl], a
;>     if ch >= CHAN4:
;>         wChannelFlags1[ch] = wChannelFlags1[ch] | 1 << BIT_NOISE_OR_SFX
	pop af
	cp CHAN4
	jr c, .skipSettingFlag
	ld hl, wChannelFlags1
	add hl, bc
	set BIT_NOISE_OR_SFX, [hl]
.skipSettingFlag
;>     mem[wChannelCommandPointers + 2 * slot] = mem[p]          # the channel's start address
	pop bc
	pop hl
	ld a, [de] ; get channel pointer
	ld [hli], a
;>     mem[wChannelCommandPointers + 2 * slot + 1] = mem[p + 1]
	inc de
	ld a, [de]
	ld [hli], a
	inc de
;>     slot = (slot + 1) & 0xFF
	inc c
;=@each
	dec b
	ld a, b
	and a
;>     ch = mem[p + 2]                             # the next entry's channel byte
;>     p += 3
	ld a, [de]
	inc de
;=@each
	jr nz, .commandPointerLoop
;>@cry if (SFX_Cry00_1 - SFX_Headers_1) // 3 <= wSoundID < ((SFX_Cry25_1 - SFX_Headers_1) // 3 + 3):     # a cry
	ld a, [wSoundID]
	cp CRY_SFX_START
	jr nc, .maybeCry
	jr .done
.maybeCry
;=@cry
	ld a, [wSoundID]
	cp CRY_SFX_END
	jr z, .done
	jr c, .cry
	jr .done
.cry
;>     for i in range(CHAN5, CHAN8 + 1):           # claims all four effect channels
;>         wChannelSoundIDs[i] = wSoundID
	ld hl, wChannelSoundIDs + CHAN5
	ld [hli], a
	ld [hli], a
	ld [hli], a
	ld [hl], a
;>     wChannelCommandPointers[2 * CHAN7] = Audio3_CryRet & 0xFF   # its wave channel ends at once
;>     wChannelCommandPointers[2 * CHAN7 + 1] = Audio3_CryRet >> 8
	ld hl, wChannelCommandPointers + CHAN7 * 2 ; sfx wave channel pointer
	ld de, Audio3_CryRet
	ld [hl], e
	inc hl
	ld [hl], d ; overwrite pointer to point to sound_ret
;>     if not wSavedVolume:
;>         wSavedVolume = rAUDVOL                  # kept for when the cry ends
	ld a, [wSavedVolume]
	and a
	jr nz, .done
	ldh a, [rAUDVOL]
	ld [wSavedVolume], a
;>         rAUDVOL = 0x77                          # full volume
	ld a, $77
	ldh [rAUDVOL], a ; full volume
.done
	ret

;@ path: audio/engine_3
Audio3_CryRet:
	db sound_ret_cmd

;@ path: audio/engine_3
Audio3_HWChannelBaseAddresses:
; the low bytes of each HW channel's base address
	db HW_CH1_BASE, HW_CH2_BASE, HW_CH3_BASE, HW_CH4_BASE ; channels 0-3
	db HW_CH1_BASE, HW_CH2_BASE, HW_CH3_BASE, HW_CH4_BASE ; channels 4-7

;@ path: audio/engine_3
Audio3_HWChannelDisableMasks:
	db HW_CH1_DISABLE_MASK, HW_CH2_DISABLE_MASK, HW_CH3_DISABLE_MASK, HW_CH4_DISABLE_MASK ; channels 0-3
	db HW_CH1_DISABLE_MASK, HW_CH2_DISABLE_MASK, HW_CH3_DISABLE_MASK, HW_CH4_DISABLE_MASK ; channels 4-7

;@ path: audio/engine_3
Audio3_HWChannelEnableMasks:
	db HW_CH1_ENABLE_MASK, HW_CH2_ENABLE_MASK, HW_CH3_ENABLE_MASK, HW_CH4_ENABLE_MASK ; channels 0-3
	db HW_CH1_ENABLE_MASK, HW_CH2_ENABLE_MASK, HW_CH3_ENABLE_MASK, HW_CH4_ENABLE_MASK ; channels 4-7

;@ path: audio/engine_3
Audio3_Pitches:
; This file is INCLUDEd three times, once in each audio engine.

	dw $F82C ; C_
	dw $F89D ; C#
	dw $F907 ; D_
	dw $F96B ; D#
	dw $F9CA ; E_
	dw $FA23 ; F_
	dw $FA77 ; F#
	dw $FAC7 ; G_
	dw $FB12 ; G#
	dw $FB58 ; A_
	dw $FB9B ; A#
	dw $FBDA ; B_


